    let b = parts[2].parse::<i32>().map_err(|_| "number")?;
    match parts[1] {
        "+" => a.checked_add(b).ok_or("overflow"),
        "-" => a.checked_sub(b).ok_or("overflow"),
        "*" => a.checked_mul(b).ok_or("overflow"),
        _ => Err("operator"),
    }
}
