/// The default uses explicit wrapping arithmetic; checked reports overflow.
/// ```
/// assert_eq!(feature_engine::sum(&[1,2,3]), Ok(6));
/// ```
pub fn sum(values: &[u8]) -> Result<u8, &'static str> {
    let mut total = 0u8;
    for &value in values {
        #[cfg(engine_checked)]
        {
            total = total.checked_add(value).ok_or("overflow")?;
        }
        #[cfg(not(engine_checked))]
        {
            total = total.wrapping_add(value);
        }
    }
    Ok(total)
}
#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn empty_and_small() {
        assert_eq!(sum(&[]), Ok(0));
        assert_eq!(sum(&[1, 2, 3]), Ok(6));
    }
    #[test]
    fn overflow_contract() {
        if cfg!(feature = "checked") {
            assert_eq!(sum(&[250, 10]), Err("overflow"));
            assert_eq!(MODE, "checked");
        } else {
            assert_eq!(sum(&[250, 10]), Ok(4));
            assert_eq!(MODE, "wrapping");
        }
    }
}

