use std::path::PathBuf;

#[derive(Debug, PartialEq)]
pub struct Config {
    pub query: String,
    pub path: PathBuf,
    pub ignore_case: bool,
}
impl Config {
    pub fn parse(
        args: impl IntoIterator<Item = String>,
    ) -> Result<Self, &'static str> {
        Self::parse_with_default(args, false)
    }
    pub fn parse_with_default(
        args: impl IntoIterator<Item = String>,
        default_ignore_case: bool,
    ) -> Result<Self, &'static str> {
        let mut positional = Vec::new();
        let mut ignore_case = default_ignore_case;
        let mut options = true;
        for arg in args {
            match arg.as_str() {
                "--" if options => options = false,
                "--ignore-case" if options => ignore_case = true,
                "--case-sensitive" if options => ignore_case = false,
                _ if options && arg.starts_with('-') => {
                    return Err("unknown option");
                }
                _ => positional.push(arg),
            }
        }
        if positional.len() != 2 {
            return Err("expected QUERY FILE");
        }
        let mut args = positional.into_iter();
        Ok(Self {
            query: args.next().unwrap(),
            path: args.next().unwrap().into(),
            ignore_case,
        })
    }
}

/// Returned lines borrow the input text, not the query.
///
/// ```
/// assert_eq!(minigrep::search("safe", "safe Rust\nfast", false), vec!["safe Rust"]);
/// ```
pub fn search<'a>(
    query: &str,
    text: &'a str,
    ignore_case: bool,
) -> Vec<&'a str> {
    let normalized = if ignore_case {
        query.to_lowercase()
    } else {
        query.to_owned()
    };
    text.lines()
        .filter(|line| {
            if ignore_case {
                line.to_lowercase().contains(&normalized)
            } else {
                line.contains(&normalized)
            }
        })
        .collect()
}

