/// Parse an environment snapshot; never mutate the process environment.
pub fn ignore_case_default(
    value: Result<String, std::env::VarError>,
) -> Result<bool, &'static str> {
    use std::env::VarError;
    match value {
        Ok(value) => match value.as_str() {
            "1" | "true" => Ok(true),
            "0" | "false" => Ok(false),
            _ => Err("IGNORE_CASE expects 1, true, 0 or false"),
        },
        Err(VarError::NotPresent) => Ok(false),
        Err(VarError::NotUnicode(_)) => {
            Err("IGNORE_CASE must be UTF-8")
        }
    }
}
