            assert_eq!(
                ignore_case_default(Ok(raw.into())),
                Ok(expected)
            );
        }
        assert_eq!(
            ignore_case_default(Err(std::env::VarError::NotPresent)),
            Ok(false)
        );
    }
    #[test]
    fn invalid_strings_are_rejected() {
        for value in ["", "TRUE", "yes", " true "] {
            assert!(ignore_case_default(Ok(value.into())).is_err());
        }
    }
