use std::io::{self, Write};

/// Write matching original lines, then flush the caller's writer.
/// A later error can leave earlier output visible: this is not atomic.
pub fn write_matches<W: Write>(
    query: &str,
    text: &str,
    output: &mut W,
) -> io::Result<usize> {
    let mut count = 0;
    for line in text.lines().filter(|line| line.contains(query)) {
        writeln!(output, "{line}")?;
        count += 1;
    }
    output.flush()?;
    Ok(count)
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn original_lines_and_empty_matches() {
        let mut output = Vec::new();
        assert_eq!(
            write_matches("rust", "Rust\nrust 🌱\n", &mut output)
                .unwrap(),
            1
        );
        assert_eq!(output, "rust 🌱\n".as_bytes());
        let mut empty = Vec::new();
        assert_eq!(
            write_matches("missing", "rust", &mut empty).unwrap(),
            0
        );
        assert!(empty.is_empty());
    }
    struct Fails {
        kind: io::ErrorKind,
        flush_only: bool,
    }
    impl Write for Fails {
        fn write(&mut self, bytes: &[u8]) -> io::Result<usize> {
            if self.flush_only {
                Ok(bytes.len())
            } else {
                Err(io::Error::from(self.kind))
            }
        }
        fn flush(&mut self) -> io::Result<()> {
            Err(io::Error::from(self.kind))
        }
    }
    #[test]
    fn write_and_flush_errors_propagate() {
        for flush_only in [false, true] {
            let mut output = Fails {
                kind: io::ErrorKind::Other,
                flush_only,
            };
            let error =
                write_matches("rust", "rust", &mut output).unwrap_err();
            assert_eq!(error.kind(), io::ErrorKind::Other);
        }
    }
    #[test]
    fn broken_pipe_keeps_its_kind_for_caller_policy() {
        let mut output = Fails {
            kind: io::ErrorKind::BrokenPipe,
            flush_only: false,
        };
        assert_eq!(
            write_matches("rust", "rust", &mut output)
                .unwrap_err()
                .kind(),
            io::ErrorKind::BrokenPipe
        );
    }
}

use std::{env, fs, io, process::ExitCode};
use streamgrep::write_matches;

fn main() -> ExitCode {
    let args: Vec<_> = env::args_os().skip(1).collect();
    if args.len() != 2 {
        eprintln!("usage: streamgrep QUERY FILE");
        return ExitCode::from(2);
    }
    let Some(query) = args[0].to_str() else {
        eprintln!("query must be UTF-8");
        return ExitCode::from(2);
    };
    // The path stays an OsString; only the query requires UTF-8.
    let text = match fs::read_to_string(&args[1]) {
        Ok(text) => text,
        Err(error) => {
            eprintln!("read error: {error}");
            return ExitCode::FAILURE;
        }
    };
    let stdout = io::stdout();
    let mut output = stdout.lock();
    match write_matches(query, &text, &mut output) {
        Ok(_) => ExitCode::SUCCESS,
        Err(error) => {
            eprintln!("write error: {error}");
            ExitCode::FAILURE
        }
    }
}

