        Err(error) => {
            eprintln!("read error: {error}");
            return ExitCode::FAILURE;
        }
    };
    let stdout = io::stdout();
    let mut output = stdout.lock();
    match write_matches(query, &text, &mut output) {
        Ok(_) => ExitCode::SUCCESS,
        // Deliberate CLI policy: a downstream reader closing early is success.
        Err(error) if pipe_closed(error.kind()) => ExitCode::SUCCESS,
        Err(error) => {
            eprintln!("write error: {error}");
            ExitCode::FAILURE
        }
    }
}

fn pipe_closed(kind: io::ErrorKind) -> bool {
    kind == io::ErrorKind::BrokenPipe
}
#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn only_broken_pipe_is_an_accepted_write_error() {
        assert!(pipe_closed(io::ErrorKind::BrokenPipe));
        for kind in [
            io::ErrorKind::PermissionDenied,
            io::ErrorKind::WriteZero,
            io::ErrorKind::Other,
            io::ErrorKind::Interrupted,
        ] {
            assert!(!pipe_closed(kind));
        }
    }
}

