    }
}

pub fn search_lines<'text, 'query, I>(
    query: &'query str,
    lines: I,
) -> impl Iterator<Item = &'text str> + use<'text, 'query, I>
where
    I: Iterator<Item = &'text str>,
{
    lines.filter(move |line| line.contains(query))
}

