use std::io::{self, BufRead, Write};
const MAX_LIMIT: usize = 1_048_576;

fn emit<W: Write>(
    query: &str,
    bytes: &[u8],
    output: &mut W,
) -> io::Result<bool> {
    let text = std::str::from_utf8(bytes).map_err(|error| {
        io::Error::new(io::ErrorKind::InvalidData, error)
    })?;
    let text = match text.strip_suffix('\n') {
        Some(line) => line.strip_suffix('\r').unwrap_or(line),
        None => text,
    };
    if text.contains(query) {
        writeln!(output, "{text}")?;
        Ok(true)
    } else {
        Ok(false)
    }
}

/// Limit counts bytes including CR/LF terminators. Output may be partial.
pub fn search<R: BufRead, W: Write>(
    query: &str,
    input: &mut R,
    output: &mut W,
    limit: usize,
) -> io::Result<usize> {
    if limit == 0 || limit > MAX_LIMIT {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "line limit must be 1..=1048576 bytes",
        ));
    }
    let mut line = Vec::new();
    let mut matches = 0;
    loop {
        let available = input.fill_buf()?;
        if available.is_empty() {
            if !line.is_empty() && emit(query, &line, output)? {
                matches += 1;
            }
            output.flush()?;
            return Ok(matches);
        }
        let take = available
            .iter()
            .position(|&byte| byte == b'\n')
            .map_or(available.len(), |index| index + 1);
        if take > limit - line.len() {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "line byte limit exceeded",
            ));
        }
        line.extend_from_slice(&available[..take]);
        input.consume(take);
        if line.last() == Some(&b'\n') {
            if emit(query, &line, output)? {
                matches += 1;
            }
            line.clear();
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::io::{BufReader, Cursor, Read};
    #[test]
    fn chunks_utf8_crlf_and_final_line() {
        let mut input = BufReader::with_capacity(
            1,
            Cursor::new("rust 🌱\r\nlast rust"),
        );
        let mut output = Vec::new();
        assert_eq!(
            search("rust", &mut input, &mut output, 32).unwrap(),
            2
        );
        assert_eq!(output, "rust 🌱\nlast rust\n".as_bytes());
    }
    #[test]
    fn empty_and_blank_lines() {
        let mut output = Vec::new();
        assert_eq!(
            search("", &mut Cursor::new(b""), &mut output, 4).unwrap(),
            0
        );
        assert_eq!(
            search("", &mut Cursor::new(b"\n\r\n"), &mut output, 4)
                .unwrap(),
            2
        );
        assert_eq!(output, b"\n\n");
    }
    #[test]
    fn byte_limit_includes_terminators() {
        let mut output = Vec::new();
        assert_eq!(
            search("rust", &mut Cursor::new(b"rust\n"), &mut output, 5)
                .unwrap(),
            1
        );
        assert_eq!(
            search(
                "rust",
                &mut Cursor::new(b"rust\r\n"),
                &mut Vec::new(),
                5
            )
            .unwrap_err()
            .kind(),
            io::ErrorKind::InvalidData
        );
        for limit in [0, MAX_LIMIT + 1] {
            assert_eq!(
                search(
                    "x",
                    &mut Cursor::new(b"x"),
                    &mut Vec::new(),
                    limit
                )
                .unwrap_err()
                .kind(),
                io::ErrorKind::InvalidInput
            );
        }
    }
    #[test]
    fn final_standalone_cr_is_content() {
        let mut output = Vec::new();
        search("", &mut Cursor::new(b"rust\r"), &mut output, 8)
            .unwrap();
        assert_eq!(output, b"rust\r\n");
    }
    #[test]
    fn invalid_utf8_is_not_silently_skipped() {
        assert_eq!(
            search(
                "",
                &mut Cursor::new([255, b'\n']),
                &mut Vec::new(),
                8
            )
            .unwrap_err()
            .kind(),
            io::ErrorKind::InvalidData
        );
    }
    pub struct FailsAfterLine {
        pub consumed: usize,
    }
    impl Read for FailsAfterLine {
        fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
            let available = self.fill_buf()?;
            let size = available.len().min(buf.len());
            buf[..size].copy_from_slice(&available[..size]);
            self.consume(size);
            Ok(size)
        }
    }
    impl BufRead for FailsAfterLine {
        fn fill_buf(&mut self) -> io::Result<&[u8]> {
            if self.consumed == 5 {
                Err(io::Error::new(
                    io::ErrorKind::Other,
                    "injected read failure",
                ))
            } else {
                Ok(&b"rust\n"[self.consumed..])
            }
        }
        fn consume(&mut self, amount: usize) {
            assert!(amount <= 5 - self.consumed);
            self.consumed += amount;
        }
    }
    #[test]
    fn later_read_error_keeps_partial_output_and_returns_error() {
        let mut output = Vec::new();
        let error = search(
            "rust",
            &mut FailsAfterLine { consumed: 0 },
            &mut output,
            8,
        )
        .unwrap_err();
        assert_eq!(error.kind(), io::ErrorKind::Other);
        assert_eq!(output, b"rust\n");
    }
    struct Fails {
        flush_only: bool,
    }
    impl Write for Fails {
        fn write(&mut self, bytes: &[u8]) -> io::Result<usize> {
            if self.flush_only {
                Ok(bytes.len())
            } else {
                Err(io::Error::from(io::ErrorKind::WriteZero))
            }
        }
        fn flush(&mut self) -> io::Result<()> {
            Err(io::Error::from(io::ErrorKind::Other))
        }
    }
    #[test]
    fn write_and_flush_errors_are_not_success() {
        for flush_only in [false, true] {
            assert!(
                search(
                    "rust",
                    &mut Cursor::new(b"rust\n"),
                    &mut Fails { flush_only },
                    8
                )
                .is_err()
            );
        }
    }
}

