    let Some(query) =
        args.next().and_then(|arg| arg.into_string().ok())
    else {
        eprintln!("usage: streamlines QUERY FILE");
        return ExitCode::from(2);
    };
    let Some(path) = args.next() else {
        eprintln!("usage: streamlines QUERY FILE");
        return ExitCode::from(2);
    };
    if args.next().is_some() {
        eprintln!("usage: streamlines QUERY FILE");
        return ExitCode::from(2);
    }
    let file = match File::open(path) {
        Ok(file) => file,
        Err(error) => {
            eprintln!("open error: {error}");
            return ExitCode::FAILURE;
        }
    };
    let mut input = BufReader::with_capacity(16_384, file);
    let stdout = io::stdout();
    let mut output = stdout.lock();
    match streamlines::search(&query, &mut input, &mut output, 8_192) {
        Ok(_) => ExitCode::SUCCESS,
        Err(error) => {
            eprintln!("stream error: {error}");
            ExitCode::FAILURE
        }
    }
}

