    }
    #[test]
    fn not_found_and_method() {
        assert!(
            text(b"GET /other HTTP/1.1\r\nHost: x\r\n\r\n")
                .starts_with("HTTP/1.1 404")
        );
        assert!(
            text(b"POST / HTTP/1.1\r\nHost: x\r\n\r\n")
                .contains("Allow: GET, HEAD\r\n")
        );
    }
