                .starts_with("HTTP/1.1 400")
        );
    }
}

/// Recognizable HEAD requests never transmit bodies, including error replies.
pub fn reply(header: &[u8]) -> Vec<u8> {
    reply_with_slow(header, || {
        std::thread::sleep(Duration::from_millis(200))
    })
}
pub fn reply_with_slow(header: &[u8], slow: impl FnOnce()) -> Vec<u8> {
    let mut result = reply_representation(header, slow);
    let method = header
        .split(|b| b.is_ascii_whitespace())
        .find(|part| !part.is_empty());
    if method == Some(b"HEAD".as_slice()) {
        let end =
            result.windows(4).position(|w| w == b"\r\n\r\n").unwrap();
        result.truncate(end + 4);
    }
    result
}

const PAGE_LIMIT: u64 = 65_536;
fn read_html(mut input: impl std::io::Read) -> std::io::Result<String> {
    let mut bytes = Vec::new();
    std::io::Read::read_to_end(
        &mut std::io::Read::take(&mut input, PAGE_LIMIT + 1),
        &mut bytes,
    )?;
    if bytes.len() as u64 > PAGE_LIMIT {
        return Err(std::io::Error::new(
            std::io::ErrorKind::InvalidData,
            "HTML page too large",
        ));
    }
    String::from_utf8(bytes).map_err(|error| {
        std::io::Error::new(std::io::ErrorKind::InvalidData, error)
    })
}
