};
fn self_check() -> io::Result<()> {
    let server =
        Server::start(TcpListener::bind("127.0.0.1:0")?, 2, 4)?;
    let mut client = TcpStream::connect_timeout(
        &server.address(),
        Duration::from_secs(2),
    )?;
    client.set_read_timeout(Some(Duration::from_secs(2)))?;
    client.write_all(b"GET / HTTP/1.1\r\nHost: x\r\n\r\n")?;
    let mut response = String::new();
    client.read_to_string(&mut response)?;
    drop(client);
    let stats = server.finish()?;
    if !response.ends_with(include_str!("../assets/hello.html"))
        || stats.dispatched != 1
    {
        return Err(io::Error::other("owned server self-check failed"));
    }
    let stdout = io::stdout();
    let mut output = stdout.lock();
    writeln!(output, "Owned server checks passed")?;
    output.flush()
}
fn main() -> io::Result<()> {
    let args: Vec<_> = env::args().skip(1).collect();
    if args == ["--self-check"] {
        return self_check();
    }
    if args != ["--serve-for-five"] {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "use --self-check or --serve-for-five",
        ));
    }
    let server =
        Server::start(TcpListener::bind("127.0.0.1:7878")?, 4, 8)?;
    {
        let stdout = io::stdout();
        let mut output = stdout.lock();
        writeln!(
            output,
            "Serving for five seconds at {}",
            server.address()
        )?;
        output.flush()?;
    }
    thread::sleep(Duration::from_secs(5));
    let stats = server.finish()?;
    let stdout = io::stdout();
    let mut output = stdout.lock();
    writeln!(output, "Drained: {stats:?}")?;
    output.flush()
}

use bounded_http::{http, pool::Pool, serve};
use std::{
    io::{Read, Write},
