};
fn exchange(request: &[u8]) -> String {
    let listener = TcpListener::bind("127.0.0.1:0").unwrap();
    let mut client = TcpStream::connect_timeout(
        &listener.local_addr().unwrap(),
        Duration::from_secs(2),
    )
    .unwrap();
    client
        .set_read_timeout(Some(Duration::from_secs(2)))
        .unwrap();
    let server = thread::spawn(move || serve(listener, 1));
    let result = (|| -> std::io::Result<String> {
        client.write_all(request)?;
        let mut response = String::new();
        client.read_to_string(&mut response)?;
        Ok(response)
    })();
    drop(client);
    server.join().unwrap().unwrap();
    result.unwrap()
}
#[test]
fn actual_html_get_head_and_not_found() {
    let get = exchange(b"GET / HTTP/1.1\r\nHost: x\r\n\r\n");
    assert!(get.ends_with(include_str!("../assets/hello.html")));
    let head = exchange(b"HEAD / HTTP/1.1\r\nHost: x\r\n\r\n");
    assert_eq!(
        head,
        get.split_once("\r\n\r\n").unwrap().0.to_owned() + "\r\n\r\n"
    );
    let missing = exchange(b"GET /missing HTTP/1.1\r\nHost: x\r\n\r\n");
    assert!(missing.starts_with("HTTP/1.1 404"));
    assert!(missing.ends_with(include_str!("../assets/404.html")));
}
struct Release(Option<mpsc::Sender<()>>);
impl Drop for Release {
    fn drop(&mut self) {
        if let Some(sender) = self.0.take() {
            let _ = sender.send(());
        }
    }
}
fn compare(workers: usize) {
    let pool = Pool::new(workers, 8).unwrap();
    let (release_tx, release_rx) = mpsc::channel();
    // Declared after pool: unwinding releases the gate before joining workers.
    let release = Release(Some(release_tx));
    let (entered_tx, entered_rx) = mpsc::channel();
    let (slow_tx, slow_rx) = mpsc::channel();
    pool.try_execute(move || {
        let mut gate_ok = false;
        let response = http::reply_with_slow(
            b"GET /sleep HTTP/1.1\r\nHost: x\r\n\r\n",
            || {
                let _ = entered_tx.send(());
                gate_ok = release_rx
                    .recv_timeout(Duration::from_secs(5))
                    .is_ok();
            },
        );
        let status_ok = response.starts_with(b"HTTP/1.1 200");
        let _ = slow_tx.send((gate_ok, status_ok));
    })
    .unwrap();
    entered_rx.recv_timeout(Duration::from_secs(2)).unwrap();
    let (fast_tx, fast_rx) = mpsc::channel();
    pool.try_execute(move || {
        let _ = fast_tx
            .send(http::reply(b"GET / HTTP/1.1\r\nHost: x\r\n\r\n"));
    })
    .unwrap();
    if workers == 1 {
        assert!(matches!(
            fast_rx.try_recv(),
            Err(mpsc::TryRecvError::Empty)
        ));
        drop(release);
        assert!(
            fast_rx
                .recv_timeout(Duration::from_secs(2))
                .unwrap()
                .starts_with(b"HTTP/1.1 200")
        );
    } else {
        assert!(
            fast_rx
                .recv_timeout(Duration::from_secs(2))
                .unwrap()
                .starts_with(b"HTTP/1.1 200")
        );
        drop(release);
    }
    drop(pool);
    assert_eq!(slow_rx.recv().unwrap(), (true, true));
}
#[test]
fn one_worker_queues_fast_work_behind_slow_callback() {
    compare(1);
}
#[test]
fn two_workers_complete_fast_work_before_slow_release() {
    compare(2);
}

use crate::{http, pool::Pool};
use std::{
    io,
    net::{SocketAddr, TcpListener},
    sync::{
        Arc,
        atomic::{AtomicBool, AtomicUsize, Ordering},
    },
    thread::{self, JoinHandle},
    time::Duration,
};
struct State {
    stop: AtomicBool,
    accepted: AtomicUsize,
}
#[derive(Clone)]
pub struct StopToken(Arc<State>);
impl StopToken {
    pub fn stop(&self) {
        self.0.stop.store(true, Ordering::Release);
    }
}
#[derive(Debug)]
pub struct Stats {
    pub accepted: usize,
    pub dispatched: usize,
    pub rejected: usize,
}
pub struct Server {
    state: Arc<State>,
    handle: Option<JoinHandle<io::Result<Stats>>>,
    address: SocketAddr,
}
impl Server {
    pub fn start(
        listener: TcpListener,
        workers: usize,
        capacity: usize,
    ) -> io::Result<Self> {
        let address = listener.local_addr()?;
        listener.set_nonblocking(true)?;
        let pool = Pool::new(workers, capacity)?;
        let state = Arc::new(State {
            stop: AtomicBool::new(false),
            accepted: AtomicUsize::new(0),
        });
        let shared = state.clone();
        let handle = thread::Builder::new()
            .name("owned-accept".into())
            .spawn(move || {
                let mut stats = Stats {
                    accepted: 0,
                    dispatched: 0,
                    rejected: 0,
                };
                while !shared.stop.load(Ordering::Acquire) {
                    match listener.accept() {
                        Ok((stream, _)) => {
                            // Stop racing with accept closes this socket without dispatch.
                            if shared.stop.load(Ordering::Acquire) {
                                break;
                            }
                            stats.accepted += 1;
                            shared
                                .accepted
                                .fetch_add(1, Ordering::Relaxed);
                            // Do not depend on platform inheritance of nonblocking flags.
                            stream.set_nonblocking(false)?;
                            if pool
                                .try_execute(move || {
                                    let _ = http::handle(stream);
                                })
                                .is_ok()
                            {
                                stats.dispatched += 1;
                            } else {
                                stats.rejected += 1;
                            }
                        }
                        Err(error)
                            if error.kind()
                                == io::ErrorKind::WouldBlock =>
                        {
                            thread::sleep(Duration::from_millis(5))
                        }
                        Err(error)
                            if error.kind()
                                == io::ErrorKind::Interrupted =>
                        {
                            continue;
                        }
                        Err(error) => return Err(error),
                    }
                }
                drop(pool); // Drain accepted jobs and join before reporting completion.
                Ok(stats)
            })?;
        Ok(Self {
            state,
            handle: Some(handle),
            address,
        })
    }
    pub fn address(&self) -> SocketAddr {
        self.address
    }
    pub fn stop_token(&self) -> StopToken {
        StopToken(self.state.clone())
    }
    pub fn accepted(&self) -> usize {
        self.state.accepted.load(Ordering::Relaxed)
    }
    pub fn finish(mut self) -> io::Result<Stats> {
        self.state.stop.store(true, Ordering::Release);
        self.handle
            .take()
            .unwrap()
            .join()
            .map_err(|_| io::Error::other("accept thread panicked"))?
    }
}
impl Drop for Server {
    fn drop(&mut self) {
        self.state.stop.store(true, Ordering::Release);
        if let Some(handle) = self.handle.take() {
            let _ = handle.join();
        }
    }
}
