use std::{
    io::{self, Write},
    net::TcpStream,
    time::{Duration, Instant},
};
trait TimedWrite: Write {
    fn set_remaining(&mut self, remaining: Duration) -> io::Result<()>;
}
impl TimedWrite for TcpStream {
    fn set_remaining(&mut self, remaining: Duration) -> io::Result<()> {
        self.set_write_timeout(Some(remaining))
    }
}
pub fn write_response(
    writer: &mut TcpStream,
    bytes: &[u8],
    budget: Duration,
) -> io::Result<()> {
    let started = Instant::now();
    write_elapsed(writer, bytes, budget, || started.elapsed())
}
fn write_elapsed(
    writer: &mut impl TimedWrite,
    mut bytes: &[u8],
    budget: Duration,
    mut elapsed: impl FnMut() -> Duration,
) -> io::Result<()> {
    while !bytes.is_empty() {
        let remaining = budget.saturating_sub(elapsed());
        if remaining.is_zero() {
            return Err(io::Error::new(
                io::ErrorKind::TimedOut,
                "response deadline",
            ));
        }
        writer.set_remaining(remaining)?;
        match writer.write(bytes) {
            Ok(0) => {
                return Err(io::Error::new(
                    io::ErrorKind::WriteZero,
                    "response made no progress",
                ));
            }
            Ok(count) => bytes = &bytes[count..],
            Err(error)
                if error.kind() == io::ErrorKind::Interrupted =>
            {
                continue;
            }
            Err(error) => return Err(error),
        }
    }
    if elapsed() > budget {
        return Err(io::Error::new(
            io::ErrorKind::TimedOut,
            "response completed after deadline",
        ));
    }
    Ok(())
}
#[cfg(test)]
mod tests {
    use super::*;
    #[derive(Default)]
    struct Partial {
        remaining: Vec<Duration>,
        output: Vec<u8>,
        interrupted: bool,
        zero: bool,
        setting_fails: bool,
    }
    impl Write for Partial {
        fn write(&mut self, bytes: &[u8]) -> io::Result<usize> {
            if self.interrupted {
                self.interrupted = false;
                return Err(io::Error::from(
                    io::ErrorKind::Interrupted,
                ));
            }
            if self.zero {
                return Ok(0);
            }
            self.output.push(bytes[0]);
            Ok(1)
        }
        fn flush(&mut self) -> io::Result<()> {
            Ok(())
        }
    }
    impl TimedWrite for Partial {
        fn set_remaining(
            &mut self,
            remaining: Duration,
        ) -> io::Result<()> {
            if self.setting_fails {
                return Err(io::Error::from(
                    io::ErrorKind::PermissionDenied,
                ));
            }
            self.remaining.push(remaining);
            Ok(())
        }
    }
    #[test]
    fn partial_writes_share_one_budget() {
        let mut writer = Partial::default();
        let mut time = 0;
        let error = write_elapsed(
            &mut writer,
            b"abcd",
            Duration::from_millis(10),
            || {
                let now = Duration::from_millis(time);
                time += 4;
                now
            },
        )
        .unwrap_err();
        assert_eq!(error.kind(), io::ErrorKind::TimedOut);
        assert_eq!(writer.output, b"abc");
        assert_eq!(
            writer.remaining,
            [10, 6, 2].map(Duration::from_millis)
        );
    }
    #[test]
    fn interrupted_write_does_not_reset_budget() {
        let mut writer = Partial {
            interrupted: true,
            ..Default::default()
        };
        let mut time = 0;
        write_elapsed(
            &mut writer,
            b"a",
            Duration::from_millis(10),
            || {
                let now = Duration::from_millis(time);
                time += 3;
                now
            },
        )
        .unwrap();
        assert_eq!(writer.output, b"a");
        assert_eq!(
            writer.remaining,
            [10, 7].map(Duration::from_millis)
        );
    }
    #[test]
    fn zero_progress_and_late_success_are_errors() {
        let mut writer = Partial {
            zero: true,
            ..Default::default()
        };
        assert_eq!(
            write_elapsed(
                &mut writer,
                b"x",
                Duration::from_secs(1),
                || Duration::ZERO
            )
            .unwrap_err()
            .kind(),
            io::ErrorKind::WriteZero
        );
        let mut writer = Partial::default();
        let mut called = false;
        assert_eq!(
            write_elapsed(
                &mut writer,
                b"x",
                Duration::from_millis(1),
                || {
                    let result = if called { 2 } else { 0 };
                    called = true;
                    Duration::from_millis(result)
                }
            )
            .unwrap_err()
            .kind(),
            io::ErrorKind::TimedOut
        );
        assert_eq!(writer.output, b"x"); // A late error does not undo bytes already sent.
    }
    #[test]
    fn failed_timeout_configuration_prevents_writing() {
        let mut writer = Partial {
            setting_fails: true,
            ..Default::default()
        };
        assert_eq!(
            write_elapsed(
                &mut writer,
                b"x",
                Duration::from_secs(1),
                || Duration::ZERO
            )
            .unwrap_err()
            .kind(),
            io::ErrorKind::PermissionDenied
        );
        assert!(writer.output.is_empty());
    }
}

