    let elapsed = started.elapsed();
    assert!(matches!(
        error.kind(),
        io::ErrorKind::WouldBlock | io::ErrorKind::TimedOut
    ));
    assert!(
        elapsed < Duration::from_secs(2),
        "scoped local timeout regression exceeded two seconds"
    );
    println!(
        "backpressure: prefilled={prefilled} bytes, payload={} bytes, elapsed={} us, kind={:?}",
        payload.len(),
        elapsed.as_micros(),
        error.kind()
    );
    drop(client); // The peer deliberately remains open and unread through the write.
}

