    assert_eq!(count.get(), 1);
    let taken = r.pop().unwrap();
    assert_eq!(count.get(), 1);
    drop(taken);
    assert_eq!(count.get(), 2);
    assert!(r.push(Probe(count.clone())).is_ok());
