#ifndef TEACH_BUFFER_H
#define TEACH_BUFFER_H
#include <stddef.h>
#include <stdint.h>
/* Caller retains exclusive access to stats until release. */
typedef struct { size_t allocated; size_t released; } teacher_stats;
typedef struct teacher_buffer teacher_buffer;
/* Borrow input only during call. Always set *out=NULL on failure.
   0=success, 1=invalid bytes (0xff), 2=allocation failure, 3=bad arguments.
   Stats counts buffer handles, not individual malloc calls. */
int teacher_make(const uint8_t *input, size_t len, teacher_stats *stats,
                 teacher_buffer **out);
const uint8_t *teacher_data(const teacher_buffer *buffer);
size_t teacher_len(const teacher_buffer *buffer);
/* Accept NULL; free only buffers created by teacher_make, exactly once. */
void teacher_release(teacher_buffer *buffer);
#endif

#include "buffer.h"
#include <stdlib.h>
struct teacher_buffer { uint8_t *data; size_t len; teacher_stats *stats; };
void teacher_release(teacher_buffer *buffer) {
    if (!buffer) return;
    free(buffer->data);
    buffer->stats->released += 1;
    free(buffer);
}
int teacher_make(const uint8_t *input, size_t len, teacher_stats *stats,
                 teacher_buffer **out) {
    if (!out) return 3;
    *out = NULL;
    if (!stats || (!input && len)) return 3;
    teacher_buffer *buffer = malloc(sizeof *buffer);
    if (!buffer) return 2;
    buffer->data = NULL; buffer->len = len; buffer->stats = stats;
    stats->allocated += 1;
    if (len) {
        buffer->data = malloc(len);
        if (!buffer->data) { teacher_release(buffer); return 2; }
    }
    for (size_t i = 0; i < len; ++i) {
        uint8_t byte = input[i];
        if (byte == 0xff) { teacher_release(buffer); return 1; }
        buffer->data[i] = byte >= 'a' && byte <= 'z' ? byte - ('a' - 'A') : byte;
    }
    *out = buffer;
    return 0;
}
const uint8_t *teacher_data(const teacher_buffer *buffer) { return buffer->data; }
size_t teacher_len(const teacher_buffer *buffer) { return buffer->len; }

#include "buffer.h"
#include <assert.h>
#include <string.h>
int main(void) {
    teacher_stats stats = {0, 0};
    teacher_buffer *buffer = NULL;
    for (size_t i = 0; i < 1000; ++i) {
        assert(teacher_make((const uint8_t *)"hello", 5, &stats, &buffer) == 0);
        assert(teacher_len(buffer) == 5);
        assert(memcmp(teacher_data(buffer), "HELLO", 5) == 0);
        teacher_release(buffer); buffer = NULL;
        const uint8_t invalid[] = {'a', 'b', 0xff};
        assert(teacher_make(invalid, 3, &stats, &buffer) == 1);
        assert(buffer == NULL);
    }
    assert(teacher_make(NULL, 0, &stats, &buffer) == 0);
    assert(teacher_len(buffer) == 0);
    teacher_release(buffer);
    buffer = NULL;
    assert(teacher_make(NULL, 1, &stats, &buffer) == 3);
    assert(buffer == NULL);
    assert(teacher_make(NULL, 0, NULL, &buffer) == 3);
    assert(buffer == NULL);
    assert(teacher_make(NULL, 0, &stats, NULL) == 3);
    teacher_release(NULL);
    assert(stats.allocated == 2001 && stats.released == 2001);
    return 0;
}

use std::{marker::PhantomData, ptr::NonNull, rc::Rc};

#[repr(C)]
#[derive(Default, Debug)]
pub struct Context {
    allocated: usize,
    released: usize,
}
#[repr(C)]
struct ForeignBuffer {
    _opaque: [u8; 0],
}
unsafe extern "C" {
    fn teacher_make(
        input: *const u8,
        len: usize,
        stats: *mut Context,
        out: *mut *mut ForeignBuffer,
    ) -> std::ffi::c_int;
    fn teacher_data(buffer: *const ForeignBuffer) -> *const u8;
    fn teacher_len(buffer: *const ForeignBuffer) -> usize;
    fn teacher_release(buffer: *mut ForeignBuffer);
}
#[derive(Debug, PartialEq, Eq)]
pub enum Error {
    InvalidByte,
    Allocation,
    Contract,
}
/// Owns a C allocation and exclusively borrows its bookkeeping context.
///
/// The borrow prevents moving or dropping that context while C retains its address:
/// ```compile_fail
/// use foreign_buffer::Context;
/// let buffer = {
///     let mut context = Context::default();
///     context.make(b"hello").unwrap()
/// };
/// assert_eq!(buffer.as_bytes(), b"HELLO");
/// ```
///
/// A byte slice cannot outlive its foreign owner:
/// ```compile_fail
/// use foreign_buffer::Context;
/// let mut context = Context::default();
/// let bytes;
/// {
///     let buffer = context.make(b"hello").unwrap();
///     bytes = buffer.as_bytes();
/// }
/// assert_eq!(bytes, b"HELLO");
/// ```
///
/// Handles deliberately cannot move to another thread:
/// ```compile_fail
/// use foreign_buffer::Buffer;
/// fn requires_send<T: Send>() {}
/// requires_send::<Buffer<'static>>();
/// ```
pub struct Buffer<'a> {
    pointer: NonNull<ForeignBuffer>,
    context: PhantomData<&'a mut Context>,
    // This teaching C API is deliberately confined to the creating thread.
    thread: PhantomData<Rc<()>>,
}
impl Context {
    pub fn counts(&self) -> (usize, usize) {
        (self.allocated, self.released)
    }
    pub fn make<'a>(&'a mut self, input: &[u8]) -> Result<Buffer<'a>, Error> {
        let mut out = std::ptr::null_mut();
        // SAFETY: declaration matches buffer.h on the supported native targets;
        // input is readable for len bytes for this synchronous call, out is writable,
        // and the returned lifetime keeps this context exclusively borrowed.
        let status = unsafe { teacher_make(input.as_ptr(), input.len(), self, &mut out) };
        match status {
            0 => Ok(Buffer {
                pointer: NonNull::new(out).ok_or(Error::Contract)?,
                context: PhantomData,
                thread: PhantomData,
            }),
            1 => Err(Error::InvalidByte),
            2 => Err(Error::Allocation),
            _ => Err(Error::Contract),
        }
        // The C contract requires out=NULL on every failure and owns its cleanup.
        // A wrapper cannot repair arbitrary foreign memory corruption.
    }
}
impl Buffer<'_> {
    pub fn as_bytes(&self) -> &[u8] {
        // SAFETY: this private non-null handle was created by teacher_make and
        // remains live until Drop. C stores initialized bytes and never retains input.
        let len = unsafe { teacher_len(self.pointer.as_ptr()) };
        if len == 0 {
            return &[];
        } // C permits a NULL empty data pointer.
        // SAFETY: C promises data is non-null, initialized, immutable and readable
        // for len bytes. Rust slice lifetime is bounded by this owning handle.
        unsafe { std::slice::from_raw_parts(teacher_data(self.pointer.as_ptr()), len) }
    }
}
impl Drop for Buffer<'_> {
    fn drop(&mut self) {
        // SAFETY: no Clone/raw ownership escape exists. Call the matching C
        // destructor once; never reconstruct a Rust Vec from a C allocation.
        unsafe { teacher_release(self.pointer.as_ptr()) }
    }
}

