use proc_macro::{Delimiter, Spacing, TokenStream, TokenTree};
use std::iter::Peekable;

struct Field {
    name: String,
    ty: String,
}

/// Emit `compile_error!("...")` so the user sees a normal compiler diagnostic.
fn error(message: &str) -> TokenStream {
    format!("compile_error!({message:?});").parse().unwrap()
}

#[proc_macro_derive(Describe)]
pub fn derive_describe(input: TokenStream) -> TokenStream {
    match parse_struct(input) {
        Ok((name, fields)) => generate(&name, &fields),
        Err(message) => error(&message),
    }
}

/// Skip `#[...]` attributes and a `pub` / `pub(...)` visibility.
fn skip_attributes_and_visibility(tokens: &mut Peekable<impl Iterator<Item = TokenTree>>) {
    loop {
        match tokens.peek() {
            Some(TokenTree::Punct(p)) if p.as_char() == '#' => {
                tokens.next();
                tokens.next(); // the [...] group
            }
            Some(TokenTree::Ident(i)) if i.to_string() == "pub" => {
                tokens.next();
                if matches!(tokens.peek(), Some(TokenTree::Group(g)) if g.delimiter() == Delimiter::Parenthesis) {
                    tokens.next();
                }
            }
            _ => break,
        }
    }
}

fn parse_struct(input: TokenStream) -> Result<(String, Vec<Field>), String> {
    let mut tokens = input.into_iter().peekable();
    skip_attributes_and_visibility(&mut tokens);
    match tokens.next() {
        Some(TokenTree::Ident(i)) if i.to_string() == "struct" => {}
        _ => return Err("Describe can only be derived for structs".into()),
    }
    let name = match tokens.next() {
        Some(TokenTree::Ident(i)) => i.to_string(),
        _ => return Err("expected a struct name".into()),
    };
    let body = match tokens.next() {
        Some(TokenTree::Group(g)) if g.delimiter() == Delimiter::Brace => g,
        Some(TokenTree::Punct(p)) if p.as_char() == '<' => return Err("Describe does not support generic structs".into()),
        _ => return Err("Describe supports only structs with named fields".into()),
    };

    let mut fields = Vec::new();
    let mut inner = body.stream().into_iter().peekable();
    while inner.peek().is_some() {
        skip_attributes_and_visibility(&mut inner);
        let field_name = match inner.next() {
            Some(TokenTree::Ident(i)) => i.to_string(),
            _ => return Err("expected a field name".into()),
        };
        match inner.next() {
            Some(TokenTree::Punct(p)) if p.as_char() == ':' => {}
            _ => return Err(format!("expected `:` after field `{field_name}`")),
        }
        // The type runs to the next comma that is not nested inside angle brackets.
        // shortcut: `<`/`>` are plain punctuation in a TokenStream, so depth is counted by hand;
        // the `->` of fn pointer types is skipped. Upgrade to a real parser (syn) for exotic types.
        let mut ty = TokenStream::new();
        let (mut depth, mut after_dash) = (0i32, false);
        loop {
            let Some(tree) = inner.peek() else { break };
            let mut stop = false;
            if let TokenTree::Punct(p) = tree {
                let c = p.as_char();
                if c == '>' && after_dash {
                    // part of `->`, not a closing angle bracket
                } else if c == '<' {
                    depth += 1;
                } else if c == '>' {
                    depth -= 1;
                } else if c == ',' && depth == 0 {
                    stop = true;
                }
                after_dash = c == '-' && p.spacing() == Spacing::Joint;
            } else {
                after_dash = false;
            }
            if stop {
                break;
            }
            ty.extend([inner.next().unwrap()]);
        }
        inner.next(); // the separating comma, if any
        // TokenStream::to_string puts spaces around angle brackets ("Vec < u8 >"); tidy them up.
        let ty = ty.to_string().replace(" < ", "<").replace(" >", ">");
        fields.push(Field { name: field_name, ty });
    }
    Ok((name, fields))
}

fn generate(name: &str, fields: &[Field]) -> TokenStream {
    let names: Vec<String> = fields.iter().map(|f| format!("{:?}", f.name)).collect();
    let described: Vec<String> = fields.iter().map(|f| format!("{}: {}", f.name, f.ty)).collect();
    let description = format!("{name} {{ {} }}", described.join(", "));
    format!(
        "impl {name} {{ \
            pub const FIELDS: &'static [&'static str] = &[{}]; \
            pub fn describe() -> &'static str {{ {description:?} }} \
        }}",
        names.join(", ")
    )
    .parse()
    .unwrap()
}

