use proc_macro::{Delimiter, Group, Ident, Literal, Punct, Spacing, Span, TokenStream, TokenTree};

type Diagnostic = (Span, String);

/// `compile_error!("message");` whose every token carries `span`, so rustc points at that source token.
fn spanned_error(span: Span, message: &str) -> TokenStream {
    let mut literal = Literal::string(message);
    literal.set_span(span);
    let mut group = Group::new(Delimiter::Parenthesis, TokenStream::from(TokenTree::Literal(literal)));
    group.set_span(span);
    let mut tokens = vec![
        TokenTree::Ident(Ident::new("compile_error", span)),
        TokenTree::Punct(Punct::new('!', Spacing::Alone)),
        TokenTree::Group(group),
        TokenTree::Punct(Punct::new(';', Spacing::Alone)),
    ];
    for token in &mut tokens {
        token.set_span(span);
    }
    tokens.into_iter().collect()
}

/// Retry a function that returns `Result` up to `times` attempts in total.
#[proc_macro_attribute]
pub fn retry(attr: TokenStream, item: TokenStream) -> TokenStream {
    match expand(attr, item.clone()) {
        Ok(expanded) => expanded,
        Err((span, message)) => {
            // Report the problem and keep the original item, so rustc does not add a cascade of
            // "cannot find function" errors on top of ours.
            let mut out = spanned_error(span, &message);
            out.extend(item);
            out
        }
    }
}

/// Parse `times = N`.
fn parse_times(attr: TokenStream) -> Result<u32, Diagnostic> {
    let mut tokens = attr.into_iter();
    let name = match tokens.next() {
        Some(TokenTree::Ident(ident)) => ident,
        Some(other) => return Err((other.span(), "expected `times = N`".into())),
        None => return Err((Span::call_site(), "expected `times = N`".into())),
    };
    if name.to_string() != "times" {
        return Err((name.span(), format!("unknown option `{name}`, expected `times`")));
    }
    match tokens.next() {
        Some(TokenTree::Punct(p)) if p.as_char() == '=' => {}
        Some(other) => return Err((other.span(), "expected `=` after `times`".into())),
        None => return Err((name.span(), "expected `= N` after `times`".into())),
    }
    let literal = match tokens.next() {
        Some(TokenTree::Literal(literal)) => literal,
        Some(other) => return Err((other.span(), "expected an integer literal".into())),
        None => return Err((name.span(), "expected an integer after `=`".into())),
    };
    let times: u32 = literal
        .to_string()
        .parse()
        .map_err(|_| (literal.span(), "times must be a positive integer literal".to_string()))?;
    if times == 0 {
        return Err((literal.span(), "times must be at least 1".into()));
    }
    if let Some(extra) = tokens.next() {
        return Err((extra.span(), "unexpected tokens after `times = N`".into()));
    }
    Ok(times)
}

fn expand(attr: TokenStream, item: TokenStream) -> Result<TokenStream, Diagnostic> {
    let times = parse_times(attr)?;
    let tokens: Vec<TokenTree> = item.into_iter().collect();

    // Attributes, visibility and qualifiers come before `fn`; groups hide any nested `fn`.
    let Some(fn_at) = tokens.iter().position(|t| matches!(t, TokenTree::Ident(i) if i.to_string() == "fn")) else {
        let span = tokens.iter().find(|t| matches!(t, TokenTree::Ident(_))).map_or(Span::call_site(), TokenTree::span);
        return Err((span, "#[retry] can only be applied to functions".into()));
    };
    let body_at = tokens.len() - 1;
    let body = match &tokens[body_at] {
        TokenTree::Group(g) if g.delimiter() == Delimiter::Brace => g.clone(),
        other => return Err((other.span(), "expected a function with a body".into())),
    };
    // Find the `->` (a joint `-` followed by `>`) that introduces the return type.
    let arrow = (fn_at..body_at).find(|&i| {
        matches!(&tokens[i], TokenTree::Punct(p) if p.as_char() == '-' && p.spacing() == Spacing::Joint)
            && matches!(tokens.get(i + 1), Some(TokenTree::Punct(p)) if p.as_char() == '>')
    });
    let Some(arrow) = arrow else {
        return Err((tokens[fn_at].span(), "#[retry] needs a function that returns a Result".into()));
    };

    // fn name(args) -> Ret { let mut attempt = 0; loop { match (|| -> Ret { body })() { ... } } }
    let mut closure: TokenStream = "|| ->".parse().unwrap();
    closure.extend(tokens[arrow + 2..body_at].iter().cloned());
    closure.extend([TokenTree::Group(body)]);

    let mut attempt: TokenStream = "let __result =".parse().unwrap();
    attempt.extend([
        TokenTree::Group(Group::new(Delimiter::Parenthesis, closure)),
        TokenTree::Group(Group::new(Delimiter::Parenthesis, TokenStream::new())),
    ]);
    attempt.extend(
        format!(
            "; match __result {{ Ok(v) => return Ok(v), \
             Err(e) => {{ __attempt += 1; if __attempt >= {times} {{ return Err(e); }} }} }}"
        )
        .parse::<TokenStream>()
        .unwrap(),
    );

    let mut new_body: TokenStream = "let mut __attempt: u32 = 0; loop".parse().unwrap();
    new_body.extend([TokenTree::Group(Group::new(Delimiter::Brace, attempt))]);

    let mut out: TokenStream = tokens[..body_at].iter().cloned().collect();
    out.extend([TokenTree::Group(Group::new(Delimiter::Brace, new_body))]);
    Ok(out)
}

use retry_macro::retry;
use std::cell::Cell;

thread_local! {
    static CALLS: Cell<u32> = const { Cell::new(0) };
}

fn reset() {
    CALLS.with(|c| c.set(0));
}

fn calls() -> u32 {
    CALLS.with(Cell::get)
}

/// Fails for the first `fail_first` calls, then succeeds with the call number.
#[retry(times = 3)]
fn flaky(fail_first: u32) -> Result<u32, String> {
    let call = CALLS.with(|c| {
        c.set(c.get() + 1);
        c.get()
    });
    if call <= fail_first { Err(format!("attempt {call} failed")) } else { Ok(call) }
}

fn main() {
    reset();
    println!("flaky(2) = {:?} after {} calls", flaky(2), calls());
    reset();
    println!("flaky(5) = {:?} after {} calls", flaky(5), calls());
    reset();
    println!("flaky(0) = {:?} after {} calls", flaky(0), calls());
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn succeeds_when_a_later_attempt_works() {
        reset();
        assert_eq!(flaky(2), Ok(3));
        assert_eq!(calls(), 3);
    }

    #[test]
    fn gives_up_after_exactly_times_attempts_and_returns_the_last_error() {
        reset();
        assert_eq!(flaky(10), Err("attempt 3 failed".to_string()));
        assert_eq!(calls(), 3);
    }
}

