            "; match __result {{ Ok(v) => return Ok(v), \
             Err(e) => {{ __attempt += 1; if __attempt >= {times} {{ return Err(e); }} }} }}"
        )
        .parse::<TokenStream>()
        .unwrap(),
    );

    let mut new_body: TokenStream = "let mut __attempt: u32 = 0; loop".parse().unwrap();
    new_body.extend([TokenTree::Group(Group::new(Delimiter::Brace, attempt))]);

    let mut out: TokenStream = tokens[..body_at].iter().cloned().collect();
    out.extend([TokenTree::Group(Group::new(Delimiter::Brace, new_body))]);
    Ok(out)
}

use retry_macro::retry;
use std::cell::Cell;

thread_local! {
    static CALLS: Cell<u32> = const { Cell::new(0) };
}

fn reset() {
    CALLS.with(|c| c.set(0));
}

fn calls() -> u32 {
    CALLS.with(Cell::get)
}

/// Fails for the first `fail_first` calls, then succeeds with the call number.
#[retry(times = 3)]
fn flaky(fail_first: u32) -> Result<u32, String> {
    let call = CALLS.with(|c| {
        c.set(c.get() + 1);
        c.get()
    });
    if call <= fail_first { Err(format!("attempt {call} failed")) } else { Ok(call) }
}

/// With no arguments, `#[retry]` means three attempts.
#[retry]
fn default_attempts() -> Result<(), String> {
    let call = CALLS.with(|c| {
        c.set(c.get() + 1);
        c.get()
    });
    Err(format!("failure {call}"))
}

fn main() {
    reset();
    println!("flaky(2) = {:?} after {} calls", flaky(2), calls());
    reset();
    println!("flaky(5) = {:?} after {} calls", flaky(5), calls());
    reset();
    println!("flaky(0) = {:?} after {} calls", flaky(0), calls());
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn bare_retry_defaults_to_three_attempts() {
        reset();
        assert_eq!(default_attempts(), Err("failure 3".to_string()));
        assert_eq!(calls(), 3);
    }

    #[test]
    fn succeeds_when_a_later_attempt_works() {
        reset();
        assert_eq!(flaky(2), Ok(3));
        assert_eq!(calls(), 3);
    }

    #[test]
    fn gives_up_after_exactly_times_attempts_and_returns_the_last_error() {
        reset();
        assert_eq!(flaky(10), Err("attempt 3 failed".to_string()));
        assert_eq!(calls(), 3);
    }
}

