fn pair_mut<T>(items: &mut [T], i: usize, j: usize) -> Option<(&mut T, &mut T)> {
    if i == j || i >= items.len() || j >= items.len() {
        return None;
    }
    let (low, high) = if i < j { (i, j) } else { (j, i) };
    let (left, right) = items.split_at_mut(high);
    let (a, b) = (&mut left[low], &mut right[0]);
    // Return the references in the order the caller asked for.
    Some(if i < j { (a, b) } else { (b, a) })
}

fn main() {
    let mut prices = [10, 20, 30, 40];
    if let Some((a, b)) = pair_mut(&mut prices, 3, 1) {
        std::mem::swap(a, b);
    }
    assert_eq!(prices, [10, 40, 30, 20]);
    assert!(pair_mut(&mut prices, 2, 2).is_none());
    assert!(pair_mut(&mut prices, 0, 9).is_none());
    let (x, y) = pair_mut(&mut prices, 0, 2).unwrap();
    *x += 1;
    *y += 2;
    println!("prices = {prices:?}");
}

