use std::cell::Cell;
use std::rc::Rc;

impl<T> Arena<T> {
    /// Needs `&mut self`: exclusive access proves no reference into the arena is still alive.
    fn clear(&mut self) {
        let chunks = self.chunks.get_mut();
        let mut keep = chunks.pop().unwrap(); // the newest, largest chunk
        chunks.clear(); // drops the older chunks and their values
        keep.clear(); // drops the values but keeps the capacity
        chunks.push(keep);
    }
}

struct Noisy(Rc<Cell<usize>>);

impl Drop for Noisy {
    fn drop(&mut self) {
        self.0.set(self.0.get() + 1);
    }
}

fn main() {
    let drops = Rc::new(Cell::new(0));
    let mut arena = Arena::new();
    for _ in 0..20 {
        arena.alloc(Noisy(Rc::clone(&drops)));
    }
    let capacity_before = arena.chunk_capacities();
    arena.clear();
    println!("len {} after clear, {} values dropped, chunk capacities {:?} -> {:?}", arena.len(), drops.get(), capacity_before, arena.chunk_capacities());
    assert_eq!((arena.len(), drops.get()), (0, 20));
    arena.alloc(Noisy(Rc::clone(&drops)));
    drop(arena);
    assert_eq!(drops.get(), 21);
    println!("total drops after reuse and drop: {}", drops.get());
}

