        self.len += 1;
        if let Some(index) = self.free_head {
            let entry = &mut self.entries[index as usize];
            self.free_head = entry.next_free.take();
            entry.value = Some(value);
            return Key { index, generation: entry.generation };
        }
        self.entries.push(Entry { generation: 0, value: Some(value), next_free: None });
        Key { index: (self.entries.len() - 1) as u32, generation: 0 }
    }

    fn get(&self, key: Key) -> Option<&T> {
        let entry = self.entries.get(key.index as usize)?;
        if entry.generation == key.generation { entry.value.as_ref() } else { None }
    }

    fn get_mut(&mut self, key: Key) -> Option<&mut T> {
        let entry = self.entries.get_mut(key.index as usize)?;
        if entry.generation == key.generation { entry.value.as_mut() } else { None }
    }

    fn remove(&mut self, key: Key) -> Option<T> {
        let entry = self.entries.get_mut(key.index as usize)?;
        if entry.generation != key.generation {
            return None;
        }
        let value = entry.value.take()?;
        self.len -= 1;
        // A slot whose generation counter is exhausted is retired instead of reused, so a stale key
        // can never match a recycled slot after the counter wraps.
        if let Some(next) = entry.generation.checked_add(1) {
            entry.generation = next;
            entry.next_free = self.free_head;
            self.free_head = Some(key.index);
        }
        Some(value)
    }

    fn len(&self) -> usize {
        self.len
    }
}

impl<T> Slab<T> {
    fn iter(&self) -> impl Iterator<Item = (Key, &T)> {
        self.entries.iter().enumerate().filter_map(|(index, entry)| {
            entry.value.as_ref().map(|value| (Key { index: index as u32, generation: entry.generation }, value))
        })
    }
}

fn main() {
    let mut slab = Slab::new();
    let keys: Vec<Key> = (0..10).map(|i| slab.insert(i * 10)).collect();
    for key in keys.iter().step_by(3) {
        slab.remove(*key);
    }
    slab.insert(999);
    let items: Vec<(Key, &i32)> = slab.iter().collect();
    assert_eq!(items.len(), slab.len());
    for (key, value) in &items {
        assert_eq!(slab.get(*key), Some(*value));
    }
    assert!(!items.iter().any(|(_, v)| **v == 0 || **v == 30));
    println!("live values: {:?}", items.iter().map(|(_, v)| **v).collect::<Vec<_>>());
    let _ = slab.get_mut(keys[1]);
}

