use std::mem::{align_of_val, size_of, size_of_val};

trait Named {
    fn name(&self) -> &'static str;
}

trait Pricer: Named {
    fn price(&self, x: i64) -> i64;

    /// Generic helper: exempt from dyn compatibility with `where Self: Sized`.
    fn price_all<F: Fn(i64) -> i64>(&self, xs: &[i64], adjust: F) -> Vec<i64>
    where
        Self: Sized,
    {
        xs.iter().map(|&x| adjust(self.price(x))).collect()
    }
}

struct Flat;
struct Linear(i64);
struct Table(Vec<i64>);

impl Named for Flat {
    fn name(&self) -> &'static str {
        "flat"
    }
}
impl Named for Linear {
    fn name(&self) -> &'static str {
        "linear"
    }
}
impl Named for Table {
    fn name(&self) -> &'static str {
        "table"
    }
}

impl Pricer for Flat {
    fn price(&self, _x: i64) -> i64 {
        100
    }
}
impl Pricer for Linear {
    fn price(&self, x: i64) -> i64 {
        self.0 * x
    }
}
impl Pricer for Table {
    fn price(&self, x: i64) -> i64 {
        self.0.get(x as usize).copied().unwrap_or(0)
    }
}

fn total_static<P: Pricer>(pricer: &P, xs: &[i64]) -> i64 {
    xs.iter().map(|&x| pricer.price(x)).sum()
}

fn total_dyn(pricer: &dyn Pricer, xs: &[i64]) -> i64 {
    xs.iter().map(|&x| pricer.price(x)).sum()
}

fn main() {
    println!("&u8 = {} bytes, &[u8] = {}, &str = {}", size_of::<&u8>(), size_of::<&[u8]>(), size_of::<&str>());
    println!("&dyn Pricer = {} bytes, Box<dyn Pricer> = {}, Box<Linear> = {}", size_of::<&dyn Pricer>(), size_of::<Box<dyn Pricer>>(), size_of::<Box<Linear>>());

    let pricers: Vec<Box<dyn Pricer>> = vec![Box::new(Flat), Box::new(Linear(3)), Box::new(Table(vec![5, 6, 7]))];
    for pricer in &pricers {
        println!("{:>6}: concrete size {:>2}, align {}, price(2) = {}", pricer.name(), size_of_val(&**pricer), align_of_val(&**pricer), pricer.price(2));
    }

    let xs = [1, 2, 3];
    let linear = Linear(4);
    println!("static dispatch total = {}, dynamic dispatch total = {}", total_static(&linear, &xs), total_dyn(&linear, &xs));
    println!("generic helper on a concrete type: {:?}", linear.price_all(&xs, |p| p + 1));

    let as_pricer: &dyn Pricer = &Flat;
    let as_named: &dyn Named = as_pricer; // trait upcasting, stable since Rust 1.86
    println!("upcast to Named: {}", as_named.name());
}

