use std::borrow::Cow;
use std::collections::HashMap;
use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};

/// Trim and upper-case a ticker; allocate only if the text actually has to change.
fn normalize(symbol: &str) -> Cow<'_, str> {
    let clean = symbol.trim() == symbol && !symbol.bytes().any(|b| b.is_ascii_lowercase());
    if clean { Cow::Borrowed(symbol) } else { Cow::Owned(symbol.trim().to_ascii_uppercase()) }
}

fn count_upper<S: AsRef<str>>(text: S) -> usize {
    text.as_ref().chars().filter(char::is_ascii_uppercase).count()
}

fn sum_all<T: AsRef<[i64]>>(values: T) -> i64 {
    values.as_ref().iter().sum()
}

fn hash_of<T: Hash + ?Sized>(value: &T) -> u64 {
    let mut hasher = DefaultHasher::new();
    value.hash(&mut hasher);
    hasher.finish()
}

fn label(cow: &Cow<str>) -> &'static str {
    if matches!(cow, Cow::Borrowed(_)) { "borrowed" } else { "owned" }
}

fn main() {
    let inputs = ["AAPL", " aapl ", "msft", "GOOG", "  XOM"];
    let normalized: Vec<Cow<str>> = inputs.iter().map(|s| normalize(s)).collect();
    for (input, result) in inputs.iter().zip(&normalized) {
        println!("{input:>8?} -> {result:<5} ({})", label(result));
    }
    let owned = normalized.iter().filter(|c| matches!(c, Cow::Owned(_))).count();
    println!("{} of {} inputs needed an allocation", owned, inputs.len());

    let mut cow: Cow<str> = Cow::Borrowed("buy");
    println!("before to_mut: {}", label(&cow));
    cow.to_mut().push_str(" 100");
    println!("after to_mut: {} -> {cow}", label(&cow));

    println!("AsRef<str> accepts &str, String, Box<str>: {} {} {}", count_upper("AaBb"), count_upper(String::from("XYz")), count_upper(Box::<str>::from("QQ")));
    println!("AsRef<[i64]> accepts Vec, array, slice: {} {} {}", sum_all(vec![1, 2, 3]), sum_all([10, 20]), sum_all(&[7, 8][..]));

