use std::borrow::Cow;

fn normalize(symbol: &str) -> Cow<'_, str> {
    let clean = symbol.trim() == symbol && !symbol.bytes().any(|b| b.is_ascii_lowercase());
    if clean { Cow::Borrowed(symbol) } else { Cow::Owned(symbol.trim().to_ascii_uppercase()) }
}

fn normalize_all<'a>(symbols: &[&'a str]) -> (Vec<Cow<'a, str>>, usize) {
    let normalized: Vec<Cow<str>> = symbols.iter().map(|s| normalize(s)).collect();
    let allocations = normalized.iter().filter(|c| matches!(c, Cow::Owned(_))).count();
    (normalized, allocations)
}

fn join_ids<I, S>(ids: I) -> String
where
    I: IntoIterator<Item = S>,
    S: AsRef<str>,
{
    ids.into_iter().map(|id| id.as_ref().to_owned()).collect::<Vec<_>>().join(",")
}

fn main() {
    let (clean, allocations) = normalize_all(&["AAPL", "MSFT", "GOOG"]);
    assert_eq!((clean.len(), allocations), (3, 0));
    let (mixed, allocations) = normalize_all(&["AAPL", "msft", " XOM "]);
    assert_eq!(allocations, 2);
    assert_eq!(mixed.iter().map(|c| c.as_ref()).collect::<Vec<_>>(), ["AAPL", "MSFT", "XOM"]);
    assert_eq!(join_ids(vec![String::from("a"), String::from("b")]), "a,b");
    assert_eq!(join_ids(["x", "y", "z"]), "x,y,z");
    assert_eq!(join_ids(&["p", "q"][..]), "p,q");
    println!("clean feed allocations: 0, mixed feed allocations: {allocations}");
}

