struct Pairwise<I: Iterator> {
    iter: I,
    prev: Option<I::Item>,
    primed: bool,
}

impl<I: Iterator> Iterator for Pairwise<I>
where
    I::Item: Clone,
{
    type Item = (I::Item, I::Item);

    fn next(&mut self) -> Option<Self::Item> {
        if !self.primed {
            self.prev = self.iter.next();
            self.primed = true;
        }
        let current = self.iter.next()?;
        let previous = self.prev.replace(current.clone())?;
        Some((previous, current))
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        let (low, high) = self.iter.size_hint();
        // Before priming, n inner items yield n - 1 pairs; afterwards each remaining item yields one.
        let adjust = |n: usize| if self.primed { n } else { n.saturating_sub(1) };
        (adjust(low), high.map(adjust))
    }
}

impl<I: ExactSizeIterator> ExactSizeIterator for Pairwise<I> where I::Item: Clone {}

/// Doubles every item; forwards both ends so `.rev()` and `.len()` keep working.
struct Doubled<I>(I);

impl<I: Iterator<Item = i64>> Iterator for Doubled<I> {
    type Item = i64;

    fn next(&mut self) -> Option<i64> {
        self.0.next().map(|x| x * 2)
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        self.0.size_hint()
    }
}

impl<I: DoubleEndedIterator<Item = i64>> DoubleEndedIterator for Doubled<I> {
    fn next_back(&mut self) -> Option<i64> {
        self.0.next_back().map(|x| x * 2)
    }
}

impl<I: ExactSizeIterator<Item = i64>> ExactSizeIterator for Doubled<I> {}

trait IterExt: Iterator + Sized {
    fn pairwise(self) -> Pairwise<Self>
    where
        Self::Item: Clone,
    {
        Pairwise { iter: self, prev: None, primed: false }
    }

    fn doubled(self) -> Doubled<Self>
    where
        Self: Iterator<Item = i64>,
    {
        Doubled(self)
    }
}

impl<I: Iterator> IterExt for I {}

fn main() {
    let prices = [100, 101, 99, 105];
    let changes: Vec<i64> = prices.iter().pairwise().map(|(a, b)| b - a).collect();
    println!("changes of {prices:?} = {changes:?}");
    println!("pairs: {:?}", (0..4).pairwise().collect::<Vec<_>>());

    let mut pairs = prices.iter().pairwise();
    println!("size_hint before the first item: {:?}, len = {}", pairs.size_hint(), pairs.len());
    pairs.next();
    println!("size_hint after one item: {:?}, len = {}", pairs.size_hint(), pairs.len());
    println!("empty: {:?}, single: {:?}", std::iter::empty::<i32>().pairwise().size_hint(), std::iter::once(1).pairwise().size_hint());
    println!("infinite source stays lazy: {:?}", (0u64..).pairwise().take(3).collect::<Vec<_>>());
    println!("infinite size_hint: {:?}", (0u64..).pairwise().size_hint().1);

    let doubled = vec![1i64, 2, 3].into_iter().doubled();
    println!("doubled len = {}, reversed = {:?}", doubled.len(), doubled.rev().collect::<Vec<_>>());
    let mut both = vec![1i64, 2, 3, 4, 5].into_iter().doubled();
    println!("from both ends: {:?} {:?} {:?}", both.next(), both.next_back(), both.len());

    for n in 0..8usize {
        let pairs = (0..n).pairwise();
        let (low, high) = pairs.size_hint();
        let actual = (0..n).pairwise().count();
        assert!(low <= actual && high.is_none_or(|h| actual <= h));
        assert_eq!(actual, n.saturating_sub(1));
    }
    println!("size_hint brackets the real count for every length 0..8: true");
}

