use std::any::Any;
use std::panic::{self, AssertUnwindSafe};
use std::sync::{Arc, Mutex};
use std::thread;

struct Guard(&'static str);

impl Drop for Guard {
    fn drop(&mut self) {
        println!("cleanup ran for {}", self.0);
    }
}

/// May unwind into a Rust caller through the C ABI; plain `extern "C"` would abort the process instead.
extern "C-unwind" fn may_panic(fail: bool) -> i32 {
    if fail {
        panic!("boom from an extern C-unwind function");
    }
    7
}

fn payload_text(payload: &(dyn Any + Send)) -> String {
    if let Some(text) = payload.downcast_ref::<&str>() {
        text.to_string()
    } else if let Some(text) = payload.downcast_ref::<String>() {
        text.clone()
    } else {
        "<non-string payload>".to_string()
    }
}

fn main() {
    panic::set_hook(Box::new(|_| {})); // keep the demo output deterministic

    let caught = panic::catch_unwind(|| {
        let _guard = Guard("inner scope");
        panic!("something broke");
    });
    println!("literal payload: {:?}", caught.map_err(|p| payload_text(&*p)));

    let caught = panic::catch_unwind(|| {
        let limit = 3;
        panic!("value {limit} is out of range");
    });
    println!("formatted payload: {:?}", caught.map_err(|p| payload_text(&*p)));

    println!("may_panic(false) = {:?}", panic::catch_unwind(|| may_panic(false)).map_err(|p| payload_text(&*p)));
    println!("may_panic(true) = {:?}", panic::catch_unwind(|| may_panic(true)).map_err(|p| payload_text(&*p)));

    let mut counter = 0;
    let outcome = panic::catch_unwind(AssertUnwindSafe(|| {
        counter += 1;
        panic!("after the increment");
    }));
    println!("state seen after a caught panic: counter = {counter}, panicked = {}", outcome.is_err());

    let shared = Arc::new(Mutex::new(vec![1]));
    let worker = Arc::clone(&shared);
    let joined = thread::spawn(move || {
        let mut data = worker.lock().unwrap();
        data.push(2);
        panic!("worker died while holding the lock");
    })
    .join();
    println!("join reports the panic: {}", joined.is_err());
    println!("mutex poisoned: {}", shared.is_poisoned());
    let recovered = shared.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
    println!("data recovered from the poisoned lock: {:?}", *recovered);

    let rethrown = panic::catch_unwind(|| {
        let first = panic::catch_unwind(|| panic!("original"));
        if let Err(payload) = first {
            panic::resume_unwind(payload);
        }
    });
    println!("resume_unwind keeps the original payload: {:?}", rethrown.map_err(|p| payload_text(&*p)));
}

