fn guarded<T>(task: impl FnOnce() -> T + UnwindSafe) -> Result<T, String> {
    panic::catch_unwind(task).map_err(|payload| payload_text(&*payload))
}

fn main() {
    panic::set_hook(Box::new(|_| {}));
    let first = guarded(|| 10 + 1);
    let second = guarded(|| {
        let _guard = Guard("task two");
        if 2 + 2 == 4 {
            panic!("task two failed");
        }
        0
    });
    let third = guarded(|| "third finished".len());
    println!("{first:?} / {second:?} / {third:?}");
    assert_eq!(first, Ok(11));
    assert_eq!(second, Err("task two failed".to_string()));
    assert_eq!(third, Ok(14));
}

