fn naive_sum(values: &[f64]) -> f64 {
    values.iter().sum()
}

fn kahan_sum(values: &[f64]) -> f64 {
    let mut sum = 0.0;
    let mut compensation = 0.0;
    for &v in values {
        let y = v - compensation;
        let t = sum + y;
        compensation = (t - sum) - y;
        sum = t;
    }
    sum
}

fn main() {
    let values = vec![0.1_f64; 1_000_000];
    let exact = 100_000.0;
    let naive = naive_sum(&values);
    let kahan = kahan_sum(&values);
    println!("naive within 1e-9: {}", (naive - exact).abs() < 1e-9);
    println!("kahan within 1e-9: {}", (kahan - exact).abs() < 1e-9);
}

