#[derive(Clone, Copy, Debug)]
enum Mode {
    Floor,
    Ceil,
    TowardZero,
    HalfUp,
    HalfEven,
}

fn round_div(n: i64, d: i64, mode: Mode) -> i64 {
    assert!(d > 0);
    let q = n.div_euclid(d);
    let r = n.rem_euclid(d);
    if r == 0 {
        return q;
    }
    match mode {
        Mode::Floor => q,
        Mode::Ceil => q + 1,
        Mode::TowardZero => if n < 0 { q + 1 } else { q },
        Mode::HalfUp => if 2 * r >= d { q + 1 } else { q },
        Mode::HalfEven => match (2 * r).cmp(&d) {
            std::cmp::Ordering::Less => q,
            std::cmp::Ordering::Greater => q + 1,
            std::cmp::Ordering::Equal => if q % 2 == 0 { q } else { q + 1 },
        },
    }
}

fn round_to_tick(price: i64, tick: i64, mode: Mode) -> i64 {
    round_div(price, tick, mode) * tick
}

fn main() {
    let modes = [Mode::Floor, Mode::Ceil, Mode::TowardZero, Mode::HalfUp, Mode::HalfEven];
    println!("x/2   floor ceil zero half-up half-even");
    for n in [-5, -3, -1, 1, 3, 5] {
        let cells: Vec<String> = modes.iter().map(|&m| format!("{:>5}", round_div(n, 2, m))).collect();
        println!("{:>4.1}{}", n as f64 / 2.0, cells.join(" "));
    }
    println!("price 10037 (100.37), tick 5: floor {}, ceil {}, half-up {}", round_to_tick(10_037, 5, Mode::Floor), round_to_tick(10_037, 5, Mode::Ceil), round_to_tick(10_037, 5, Mode::HalfUp));
    println!("tie at tick 10: 10035 -> half-up {}, half-even {}", round_to_tick(10_035, 10, Mode::HalfUp), round_to_tick(10_035, 10, Mode::HalfEven));
    println!("tie at tick 10: 10025 -> half-up {}, half-even {}", round_to_tick(10_025, 10, Mode::HalfUp), round_to_tick(10_025, 10, Mode::HalfEven));
    let halves = [1, 3, 5, 7];
    let up: i64 = halves.iter().map(|&x| round_div(x, 2, Mode::HalfUp)).sum();
    let even: i64 = halves.iter().map(|&x| round_div(x, 2, Mode::HalfEven)).sum();
    println!("sum of 0.5, 1.5, 2.5, 3.5: exact 8, half-up {up}, half-even {even}");
}

