#[derive(Default, Debug, Clone)]
struct Welford {
    n: u64,
    mean: f64,
    m2: f64,
}

impl Welford {
    fn push(&mut self, x: f64) {
        self.n += 1;
        let delta = x - self.mean;
        self.mean += delta / self.n as f64;
        self.m2 += delta * (x - self.mean);
    }

    fn variance(&self) -> Option<f64> {
        (self.n >= 2).then(|| self.m2 / (self.n - 1) as f64)
    }

    fn merge(&mut self, other: &Welford) {
        if other.n == 0 {
            return;
        }
        if self.n == 0 {
            *self = other.clone();
            return;
        }
        let (na, nb) = (self.n as f64, other.n as f64);
        let n = na + nb;
        let delta = other.mean - self.mean;
        self.mean += delta * nb / n;
        self.m2 += other.m2 + delta * delta * na * nb / n;
        self.n += other.n;
    }
}

fn naive_variance(xs: &[f64]) -> f64 {
    let n = xs.len() as f64;
    let sum: f64 = xs.iter().sum();
    let sum_sq: f64 = xs.iter().map(|x| x * x).sum();
    (sum_sq - sum * sum / n) / (n - 1.0)
}

fn main() {
    let xs: Vec<f64> = [4.0, 7.0, 13.0, 16.0].iter().map(|d| 1e9 + d).collect();
    let mut w = Welford::default();
    for &x in &xs {
        w.push(x);
    }
    println!("true variance = 30");
    println!("welford variance = {:.6}", w.variance().unwrap());
    println!("naive variance is off by more than 1: {}", (naive_variance(&xs) - 30.0).abs() > 1.0);

    let data: Vec<f64> = (0..1000).map(|i| 100.0 + ((i * 37) % 101) as f64 / 10.0).collect();
    let (mut whole, mut left, mut right) = (Welford::default(), Welford::default(), Welford::default());
    for (i, &x) in data.iter().enumerate() {
        whole.push(x);
        if i < 400 { left.push(x) } else { right.push(x) }
    }
    left.merge(&right);
    println!("merged mean matches single pass: {}", (left.mean - whole.mean).abs() < 1e-9);
    println!("merged variance matches single pass: {}", (left.variance().unwrap() - whole.variance().unwrap()).abs() < 1e-9);
    println!("variance after one sample: {:?}", Welford { n: 1, mean: 5.0, m2: 0.0 }.variance());
}

