#[derive(Default)]
struct Welford {
    n: u64,
    mean: f64,
    m2: f64,
}

impl Welford {
    fn push(&mut self, x: f64) {
        self.n += 1;
        let delta = x - self.mean;
        self.mean += delta / self.n as f64;
        self.m2 += delta * (x - self.mean);
    }

    fn std_dev(&self) -> Option<f64> {
        (self.n >= 2).then(|| (self.m2 / (self.n - 1) as f64).sqrt())
    }
}

fn streaming_zscores(values: &[f64]) -> Vec<Option<f64>> {
    let mut stats = Welford::default();
    let mut out = Vec::with_capacity(values.len());
    for &x in values {
        // Score against history only, then fold the new point in.
        out.push(stats.std_dev().filter(|s| *s > 0.0).map(|s| (x - stats.mean) / s));
        stats.push(x);
    }
