use std::collections::VecDeque;

struct Rolling {
    window: usize,
    values: VecDeque<i64>,
    sum: i128,
    sum_sq: i128,
}

impl Rolling {
    fn new(window: usize) -> Self {
        assert!(window >= 2);
        Rolling { window, values: VecDeque::with_capacity(window), sum: 0, sum_sq: 0 }
    }

    fn push(&mut self, x: i64) {
        if self.values.len() == self.window {
            let old = i128::from(self.values.pop_front().unwrap());
            self.sum -= old;
            self.sum_sq -= old * old;
        }
        let new = i128::from(x);
        self.values.push_back(x);
        self.sum += new;
        self.sum_sq += new * new;
    }

    fn ready(&self) -> bool {
        self.values.len() == self.window
    }

    fn mean(&self) -> Option<f64> {
        self.ready().then(|| self.sum as f64 / self.window as f64)
    }

    fn variance(&self) -> Option<f64> {
        self.ready().then(|| {
            let n = self.window as i128;
            (n * self.sum_sq - self.sum * self.sum) as f64 / (n * (n - 1)) as f64
        })
    }
}

struct Ema {
    alpha: f64,
    value: Option<f64>,
}

impl Ema {
    fn with_span(span: u32) -> Self {
        Ema { alpha: 2.0 / (f64::from(span) + 1.0), value: None }
    }

    fn update(&mut self, x: f64) -> f64 {
        let next = match self.value {
            None => x,
            Some(previous) => self.alpha * x + (1.0 - self.alpha) * previous,
        };
        self.value = Some(next);
        next
    }
}

fn main() {
    let prices = [100, 102, 101, 105, 107, 106, 110];
    let mut rolling = Rolling::new(3);
    for (i, &p) in prices.iter().enumerate() {
        rolling.push(p);
        println!("t={i} price={p} mean={:?} variance={:?}", rolling.mean().map(|m| (m * 1000.0).round() / 1000.0), rolling.variance().map(|v| (v * 1000.0).round() / 1000.0));
        if i >= 2 {
            let window = &prices[i - 2..=i];
            let mean = window.iter().sum::<i64>() as f64 / 3.0;
            let var = window.iter().map(|&x| (x as f64 - mean).powi(2)).sum::<f64>() / 2.0;
            assert!((rolling.mean().unwrap() - mean).abs() < 1e-12);
            assert!((rolling.variance().unwrap() - var).abs() < 1e-9);
        }
    }
    let mut ema = Ema::with_span(3);
    let series: Vec<String> = prices.iter().map(|&p| format!("{:.4}", ema.update(p as f64))).collect();
    println!("ema(span 3, alpha {}) = {}", ema.alpha, series.join(", "));
}

