use std::ops::{Index, IndexMut};

#[derive(Clone, Debug, PartialEq)]
struct Matrix {
    rows: usize,
    cols: usize,
    data: Vec<f64>,
}

impl Matrix {
    fn zeros(rows: usize, cols: usize) -> Matrix {
        Matrix { rows, cols, data: vec![0.0; rows * cols] }
    }

    fn from_rows(rows: &[&[f64]]) -> Matrix {
        let cols = rows[0].len();
        assert!(rows.iter().all(|r| r.len() == cols));
        Matrix { rows: rows.len(), cols, data: rows.iter().flat_map(|r| r.iter().copied()).collect() }
    }

    fn transpose(&self) -> Matrix {
        let mut t = Matrix::zeros(self.cols, self.rows);
        for r in 0..self.rows {
            for c in 0..self.cols {
                t[(c, r)] = self[(r, c)];
            }
        }
        t
    }

    fn mul(&self, other: &Matrix) -> Option<Matrix> {
        if self.cols != other.rows {
            return None;
        }
        let mut out = Matrix::zeros(self.rows, other.cols);
        for i in 0..self.rows {
            for k in 0..self.cols {
                let a = self[(i, k)];
                for j in 0..other.cols {
                    out[(i, j)] += a * other[(k, j)];
                }
            }
        }
        Some(out)
    }
}

impl Index<(usize, usize)> for Matrix {
    type Output = f64;
    fn index(&self, (r, c): (usize, usize)) -> &f64 {
        &self.data[r * self.cols + c]
    }
}

impl IndexMut<(usize, usize)> for Matrix {
    fn index_mut(&mut self, (r, c): (usize, usize)) -> &mut f64 {
        &mut self.data[r * self.cols + c]
    }
}

/// Solve a x = b by Gaussian elimination with partial pivoting.
fn solve(a: &Matrix, b: &[f64]) -> Option<Vec<f64>> {
    let n = a.rows;
    if a.cols != n || b.len() != n {
        return None;
    }
    let mut m = a.clone();
    let mut rhs = b.to_vec();
    for col in 0..n {
        let pivot = (col..n).max_by(|&i, &j| m[(i, col)].abs().total_cmp(&m[(j, col)].abs()))?;
        if m[(pivot, col)].abs() < 1e-12 {
            return None;
        }
        if pivot != col {
            for c in 0..n {
                let tmp = m[(col, c)];
                m[(col, c)] = m[(pivot, c)];
                m[(pivot, c)] = tmp;
            }
            rhs.swap(col, pivot);
        }
        for row in col + 1..n {
            let factor = m[(row, col)] / m[(col, col)];
            for c in col..n {
                let v = m[(col, c)];
                m[(row, c)] -= factor * v;
            }
            rhs[row] -= factor * rhs[col];
        }
    }
    let mut x = vec![0.0; n];
    for row in (0..n).rev() {
        let tail: f64 = (row + 1..n).map(|c| m[(row, c)] * x[c]).sum();
        x[row] = (rhs[row] - tail) / m[(row, row)];
    }
    Some(x)
}

fn main() {
    let a = Matrix::from_rows(&[&[2.0, 1.0, -1.0], &[-3.0, -1.0, 2.0], &[-2.0, 1.0, 2.0]]);
    let x = solve(&a, &[8.0, -11.0, -3.0]).unwrap();
    println!("solution = {:.6?}", x);

    let needs_pivot = Matrix::from_rows(&[&[0.0, 1.0], &[1.0, 0.0]]);
    println!("zero on the diagonal: {:.3?}", solve(&needs_pivot, &[3.0, 5.0]).unwrap());
    let singular = Matrix::from_rows(&[&[1.0, 2.0], &[2.0, 4.0]]);
    println!("singular matrix: {:?}", solve(&singular, &[1.0, 2.0]));
    println!("shape mismatch: {:?}", a.mul(&Matrix::zeros(2, 2)));

    let xs = [0.0, 1.0, 2.0, 3.0];
    let ys = [1.0, 3.0, 5.0, 7.0];
    let mut design = Matrix::zeros(4, 2);
    for (i, &v) in xs.iter().enumerate() {
        design[(i, 0)] = 1.0;
        design[(i, 1)] = v;
    }
    let xt = design.transpose();
    let xtx = xt.mul(&design).unwrap();
    let y_col = Matrix { rows: 4, cols: 1, data: ys.to_vec() };
    let xty = xt.mul(&y_col).unwrap();
    let beta = solve(&xtx, &xty.data).unwrap();
    println!("fit y = a + b x: a = {:.6}, b = {:.6}", beta[0], beta[1]);
}

