#[derive(Clone)]
struct Matrix {
    n: usize,
    data: Vec<f64>,
}

impl Matrix {
    fn square(rows: &[&[f64]]) -> Option<Matrix> {
        let n = rows.len();
        rows.iter().all(|r| r.len() == n).then(|| Matrix { n, data: rows.iter().flat_map(|r| r.iter().copied()).collect() })
    }
}

fn determinant(a: &Matrix) -> f64 {
    let n = a.n;
    let mut m = a.data.clone();
    let mut det = 1.0;
    for col in 0..n {
        let pivot = (col..n).max_by(|&i, &j| m[i * n + col].abs().total_cmp(&m[j * n + col].abs())).unwrap();
        if m[pivot * n + col].abs() < 1e-12 {
            return 0.0;
        }
        if pivot != col {
            for c in 0..n {
                m.swap(col * n + c, pivot * n + c);
            }
            det = -det;
        }
        det *= m[col * n + col];
        for row in col + 1..n {
            let factor = m[row * n + col] / m[col * n + col];
            for c in col..n {
                m[row * n + c] -= factor * m[col * n + c];
            }
        }
    }
    det
}

fn main() {
    let a = Matrix::square(&[&[2.0, 1.0, -1.0], &[-3.0, -1.0, 2.0], &[-2.0, 1.0, 2.0]]).unwrap();
    let swapped = Matrix::square(&[&[-3.0, -1.0, 2.0], &[2.0, 1.0, -1.0], &[-2.0, 1.0, 2.0]]).unwrap();
    assert!((determinant(&a) + 1.0).abs() < 1e-9);
    assert!((determinant(&swapped) - 1.0).abs() < 1e-9);
    assert!(Matrix::square(&[&[1.0, 2.0]]).is_none());
    println!("det = {:.3}, after swapping two rows = {:.3}", determinant(&a), determinant(&swapped));
}

