#[derive(Clone, Copy, Debug)]
struct Tick {
    ts: i64,
    price: i64,
    qty: u32,
}

#[derive(Clone, Debug, PartialEq)]
struct Bar {
    start: i64,
    open: i64,
    high: i64,
    low: i64,
    close: i64,
    volume: u64,
    ticks: u32,
}

const SECOND: i64 = 1_000_000_000;

fn resample(ticks: &[Tick], interval: i64) -> Result<Vec<Bar>, &'static str> {
    assert!(interval > 0);
    if !ticks.windows(2).all(|w| w[0].ts <= w[1].ts) {
        return Err("ticks must be sorted by timestamp");
    }
    let mut bars: Vec<Bar> = Vec::new();
    for tick in ticks {
        let start = tick.ts.div_euclid(interval) * interval;
        if bars.last().is_some_and(|b| b.start == start) {
            let bar = bars.last_mut().unwrap();
            bar.high = bar.high.max(tick.price);
            bar.low = bar.low.min(tick.price);
            bar.close = tick.price;
            bar.volume += u64::from(tick.qty);
            bar.ticks += 1;
            continue;
        }
        if let Some((prev_start, prev_close)) = bars.last().map(|b| (b.start, b.close)) {
            let mut gap = prev_start + interval;
            while gap < start {
                bars.push(Bar { start: gap, open: prev_close, high: prev_close, low: prev_close, close: prev_close, volume: 0, ticks: 0 });
                gap += interval;
            }
        }
        bars.push(Bar { start, open: tick.price, high: tick.price, low: tick.price, close: tick.price, volume: u64::from(tick.qty), ticks: 1 });
    }
    Ok(bars)
}

fn main() {
    let ticks = [
        Tick { ts: -SECOND / 2, price: 9_990, qty: 5 },
        Tick { ts: SECOND / 10, price: 10_000, qty: 10 },
        Tick { ts: SECOND * 4 / 10, price: 10_020, qty: 20 },
        Tick { ts: SECOND * 9 / 10, price: 9_995, qty: 15 },
        Tick { ts: SECOND * 32 / 10, price: 10_050, qty: 30 },
        Tick { ts: SECOND * 39 / 10, price: 10_040, qty: 5 },
    ];
    let bars = resample(&ticks, SECOND).unwrap();
    println!("sec  open  high   low close vol ticks");
    for b in &bars {
        println!("{:>3} {:>5} {:>5} {:>5} {:>5} {:>3} {:>5}", b.start / SECOND, b.open, b.high, b.low, b.close, b.volume, b.ticks);
    }
    let synthetic = bars.iter().filter(|b| b.ticks == 0).count();
    println!("synthetic forward-filled bars: {synthetic}");
    println!("truncating division would put -0.5s in bucket {}", (-SECOND / 2) / SECOND);
    println!("div_euclid puts it in bucket {}", (-SECOND / 2).div_euclid(SECOND));
    let unsorted = [Tick { ts: 5, price: 1, qty: 1 }, Tick { ts: 1, price: 1, qty: 1 }];
    println!("unsorted input: {:?}", resample(&unsorted, SECOND).map(|b| b.len()));
}

