                        j += 2;
                    }
                    Some(b'"') => break,
                    Some(_) => j += 1,
                }
            }
            let raw = &line[start..j];
            fields.push(if escaped { Cow::Owned(raw.replace("\"\"", "\"")) } else { Cow::Borrowed(raw) });
            i = j + 1;
            match bytes.get(i) {
                None => break,
                Some(b',') => i += 1,
                Some(_) => return Err(CsvError::StrayQuote { line: line_no, column: i + 1 }),
            }
        } else {
            let end = line[i..].find(',').map_or(line.len(), |p| i + p);
            let raw = &line[i..end];
            if let Some(p) = raw.find('"') {
                return Err(CsvError::StrayQuote { line: line_no, column: i + p + 1 });
            }
            fields.push(Cow::Borrowed(raw));
            if end == line.len() {
                break;
            }
            i = end + 1;
        }
    }
    Ok(fields)
}

struct Records<'a> {
    lines: std::iter::Enumerate<std::str::Lines<'a>>,
    expected: Option<usize>,
    failed: bool,
}

impl<'a> Records<'a> {
    fn new(text: &'a str) -> Self {
        Records { lines: text.lines().enumerate(), expected: None, failed: false }
    }
}

impl<'a> Iterator for Records<'a> {
    type Item = Result<Vec<Cow<'a, str>>, CsvError>;

    fn next(&mut self) -> Option<Self::Item> {
        if self.failed {
            return None;
        }
        let (index, line) = self.lines.next()?;
        let result = parse_line(line, index + 1).and_then(|fields| match self.expected {
            Some(n) if n != fields.len() => Err(CsvError::WrongFieldCount { line: index + 1, expected: n, found: fields.len() }),
            _ => {
                self.expected.get_or_insert(fields.len());
                Ok(fields)
            }
        });
        self.failed = result.is_err();
        Some(result)
    }
}

fn main() {
    let text = "a,b\n1,\"x,y\"\n2,z\n3\n4,w\n";
    let mut records = Records::new(text);
    let header = records.next().unwrap().unwrap();
    println!("header = {header:?}");
    let rows: Vec<_> = records.by_ref().take(2).collect();
    println!("first two rows = {rows:?}");
    println!("next = {:?}", records.next());
    println!("after the error = {:?}", records.next());
}

