use serde::{Deserialize, Deserializer, Serialize, Serializer};
use std::fmt;

const SCALE: i64 = 10_000;

/// A price in units of 1/10,000, written in JSON as an exact decimal string.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Price(pub i64);

impl Price {
    pub fn parse(text: &str) -> Result<Price, String> {
        let (negative, body) = match text.strip_prefix('-') {
            Some(rest) => (true, rest),
            None => (false, text),
        };
        let (whole, fraction) = body.split_once('.').unwrap_or((body, ""));
        if whole.is_empty() || fraction.len() > 4 {
            return Err(format!("invalid price {text:?}: need digits and at most 4 decimals"));
        }
        if !whole.bytes().chain(fraction.bytes()).all(|b| b.is_ascii_digit()) {
            return Err(format!("invalid price {text:?}: digits only"));
        }
        let whole: i64 = whole.parse().map_err(|_| format!("price {text:?} is too large"))?;
        let padded = format!("{fraction:0<4}");
        let units = whole
            .checked_mul(SCALE)
            .and_then(|w| w.checked_add(padded.parse::<i64>().unwrap()))
            .ok_or_else(|| format!("price {text:?} is too large"))?;
        Ok(Price(if negative { -units } else { units }))
    }
}

impl fmt::Display for Price {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        let sign = if self.0 < 0 { "-" } else { "" };
        let magnitude = self.0.unsigned_abs();
        write!(f, "{sign}{}.{:04}", magnitude / SCALE as u64, magnitude % SCALE as u64)
    }
}

impl Serialize for Price {
    fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        serializer.collect_str(self)
    }
}

impl<'de> Deserialize<'de> for Price {
    fn deserialize<D: Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        let text = String::deserialize(deserializer)?;
        Price::parse(&text).map_err(serde::de::Error::custom)
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Side {
    Buy,
    Sell,
}

#[derive(Debug, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Quote {
    pub symbol: String,
    pub bid: Price,
    pub ask: Price,
    pub ts_ns: i64,
    pub side: Side,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub venue: Option<String>,
}

fn main() {
    let quote = Quote {
        symbol: "AAPL".into(),
        bid: Price::parse("189.49").unwrap(),
        ask: Price::parse("189.5").unwrap(),
        ts_ns: 1_760_000_000_000_000_000,
        side: Side::Buy,
        venue: None,
    };
    let json = serde_json::to_string(&quote).unwrap();
    println!("{json}");
    let back: Quote = serde_json::from_str(&json).unwrap();
    println!("round trip equal: {}", back == quote);

    let with_venue = Quote { venue: Some("XNAS".into()), ..back };
    println!("{}", serde_json::to_string(&with_venue).unwrap());

    let unknown = r#"{"symbol":"AAPL","bid":"1.0","ask":"1.1","ts_ns":1,"side":"sell","colour":"red"}"#;
    let error = serde_json::from_str::<Quote>(unknown).unwrap_err().to_string();
    println!("unknown field rejected: {}", error.contains("unknown field `colour`"));

    let too_precise = r#"{"symbol":"X","bid":"1.23456","ask":"1.1","ts_ns":1,"side":"buy"}"#;
    println!("excess precision rejected: {}", serde_json::from_str::<Quote>(too_precise).is_err());
    let wrong_case = r#"{"symbol":"X","bid":"1","ask":"1","ts_ns":1,"side":"Buy"}"#;
    println!("wrong enum case rejected: {}", serde_json::from_str::<Quote>(wrong_case).is_err());
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn price_round_trips_through_text() {
        for text in ["0.0000", "189.5000", "-12.3400", "9999.9999"] {
            assert_eq!(Price::parse(text).unwrap().to_string(), text);
        }
    }

    #[test]
    fn quote_round_trips_and_omits_missing_venue() {
        let quote = Quote { symbol: "MSFT".into(), bid: Price(4_112_000), ask: Price(4_112_500), ts_ns: 5, side: Side::Sell, venue: None };
        let json = serde_json::to_string(&quote).unwrap();
        assert!(!json.contains("venue"));
        assert_eq!(serde_json::from_str::<Quote>(&json).unwrap(), quote);
    }

    #[test]
    fn invalid_input_is_rejected() {
        assert!(Price::parse("1.23456").is_err());
        assert!(Price::parse("abc").is_err());
        assert!(serde_json::from_str::<Quote>(r#"{"symbol":"X"}"#).is_err());
    }
}

