use std::hint::black_box;
use std::time::Instant;

fn sum_squares(n: u64) -> u64 {
    (1..=n).map(|x| x * x).fold(0u64, |a, b| a.wrapping_add(b))
}

struct Summary {
    min: u128,
    median: u128,
    max: u128,
    checksum: u64,
}

fn measure<F: FnMut() -> u64>(warmup: usize, runs: usize, mut work: F) -> Summary {
    let mut checksum = 0u64;
    for _ in 0..warmup {
        checksum = checksum.wrapping_add(black_box(work()));
    }
    let mut samples = Vec::with_capacity(runs);
    for _ in 0..runs {
        let start = Instant::now();
        let result = black_box(work());
        samples.push(start.elapsed().as_nanos());
        checksum = checksum.wrapping_add(result);
    }
    samples.sort_unstable();
    Summary { min: samples[0], median: samples[samples.len() / 2], max: samples[samples.len() - 1], checksum }
}

fn main() {
    let n = black_box(10_000u64);
    let summary = measure(3, 11, || sum_squares(black_box(n)));
    assert!(summary.min <= summary.median && summary.median <= summary.max);
    println!("one run = {}", sum_squares(n));
    println!("checksum over 3 warm-up + 11 timed runs = {}", summary.checksum);
    println!("min <= median <= max: true");
}

