use std::hint::black_box;

fn sum_squares(n: u64) -> u64 {
    (1..=n).map(|x| x * x).fold(0u64, |a, b| a.wrapping_add(b))
}

fn checksum_of_runs<F: FnMut() -> u64>(runs: usize, mut f: F) -> u64 {
    let mut total = 0u64;
    for _ in 0..runs {
        total = total.wrapping_add(black_box(f()));
    }
    total
}

fn main() {
    let n = black_box(1_000u64);
    let once = checksum_of_runs(5, || sum_squares(black_box(n)));
    let twice = checksum_of_runs(10, || sum_squares(black_box(n)));
    assert_eq!(twice, once * 2);
    println!("5 runs = {once}, 10 runs = {twice}");
}

