fn matmul_naive(a: &[i64], b: &[i64], n: usize) -> Vec<i64> {
    let mut c = vec![0i64; n * n];
    for i in 0..n {
        for j in 0..n {
            let mut sum = 0;
            for k in 0..n {
                sum += a[i * n + k] * b[k * n + j];
            }
            c[i * n + j] = sum;
        }
    }
    c
}

fn matmul_ikj(a: &[i64], b: &[i64], n: usize) -> Vec<i64> {
    let mut c = vec![0i64; n * n];
    for i in 0..n {
        for k in 0..n {
            let aik = a[i * n + k];
            for j in 0..n {
                c[i * n + j] += aik * b[k * n + j];
            }
        }
    }
    c
}

fn matmul_tiled(a: &[i64], b: &[i64], n: usize, tile: usize) -> Vec<i64> {
    let mut c = vec![0i64; n * n];
    for ii in (0..n).step_by(tile) {
        for kk in (0..n).step_by(tile) {
            for jj in (0..n).step_by(tile) {
                for i in ii..(ii + tile).min(n) {
                    for k in kk..(kk + tile).min(n) {
                        let aik = a[i * n + k];
                        for j in jj..(jj + tile).min(n) {
                            c[i * n + j] += aik * b[k * n + j];
                        }
                    }
                }
            }
        }
    }
    c
}

fn checksum(c: &[i64]) -> i64 {
    c.iter().enumerate().map(|(i, v)| v * (i as i64 + 1)).sum()
}

fn main() {
    let n = 10;
    let tile = 4;
    let a: Vec<i64> = (0..n * n).map(|x| ((x / n * 7 + x % n * 3) % 11) as i64 - 5).collect();
    let b: Vec<i64> = (0..n * n).map(|x| ((x / n * 5 + x % n * 2) % 13) as i64 - 6).collect();
    let naive = matmul_naive(&a, &b, n);
    let ikj = matmul_ikj(&a, &b, n);
    let tiled = matmul_tiled(&a, &b, n, tile);
    assert_eq!(naive, ikj);
    assert_eq!(naive, tiled);
    println!("checksum = {}", checksum(&naive));
    println!("naive: b is read with a stride of {} bytes", n * size_of::<i64>());
    println!("ikj: b is read with a stride of {} bytes", size_of::<i64>());
    println!("tile blocks per dimension = {}", (0..n).step_by(tile).count());
    println!("tile = 32 working set = {} bytes", 3 * 32 * 32 * size_of::<i64>());
}

