fn matmul_naive(a: &[i64], b: &[i64], n: usize) -> Vec<i64> {
    let mut c = vec![0i64; n * n];
    for i in 0..n {
        for j in 0..n {
            for k in 0..n {
                c[i * n + j] += a[i * n + k] * b[k * n + j];
            }
        }
    }
    c
}

fn transpose(m: &[i64], n: usize) -> Vec<i64> {
    let mut t = vec![0i64; n * n];
    for r in 0..n {
        for c in 0..n {
            t[c * n + r] = m[r * n + c];
        }
    }
    t
}

fn matmul_bt(a: &[i64], bt: &[i64], n: usize) -> Vec<i64> {
    let mut c = vec![0i64; n * n];
    for i in 0..n {
        for j in 0..n {
            // Row i of a and row j of bt are both contiguous.
            c[i * n + j] = (0..n).map(|k| a[i * n + k] * bt[j * n + k]).sum();
        }
    }
    c
}

fn main() {
    let n = 5;
    let a: Vec<i64> = (0..n * n).map(|x| (x % 7) as i64 - 3).collect();
    let b: Vec<i64> = (0..n * n).map(|x| (x % 4) as i64 + 1).collect();
    let bt = transpose(&b, n);
    assert_eq!(matmul_naive(&a, &b, n), matmul_bt(&a, &bt, n));
    println!("transposed multiply matches: true, trace = {}", (0..n).map(|i| matmul_bt(&a, &bt, n)[i * n + i]).sum::<i64>());
}

