fn dot_scalar(a: &[i32], b: &[i32]) -> i32 {
    a.iter().zip(b).map(|(x, y)| x * y).sum()
}

#[cfg(target_arch = "aarch64")]
fn dot_fast(a: &[i32], b: &[i32]) -> i32 {
    use std::arch::aarch64::{vaddvq_s32, vdupq_n_s32, vld1q_s32, vmlaq_s32};
    assert_eq!(a.len(), b.len());
    let chunks = a.len() / 4;
    // SAFETY: each load reads four i32 starting at i * 4, and i < len / 4,
    // so every load ends at or before 4 * chunks <= len for both slices.
    let mut total = unsafe {
        let mut acc = vdupq_n_s32(0);
        for i in 0..chunks {
            let x = vld1q_s32(a.as_ptr().add(i * 4));
            let y = vld1q_s32(b.as_ptr().add(i * 4));
            acc = vmlaq_s32(acc, x, y);
        }
        vaddvq_s32(acc)
    };
    for i in chunks * 4..a.len() {
        total += a[i] * b[i];
    }
    total
}

#[cfg(not(target_arch = "aarch64"))]
fn dot_fast(a: &[i32], b: &[i32]) -> i32 {
    dot_scalar(a, b)
}

fn main() {
    for len in [0usize, 1, 3, 4, 5, 19, 64] {
        let a: Vec<i32> = (0..len as i32).map(|i| i + 1).collect();
        let b: Vec<i32> = (0..len as i32).map(|i| i % 5 - 2).collect();
        assert_eq!(dot_fast(&a, &b), dot_scalar(&a, &b), "length {len}");
    }
    let a: Vec<i32> = (1..=19).collect();
    let b: Vec<i32> = (0..19).map(|i| i % 5 - 1).collect();
    println!("dot = {}", dot_fast(&a, &b));
    println!("tail elements for len 19 with 4 lanes = {}", 19 % 4);
    println!("fast path matches scalar for every tested length: true");
}

