use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
use std::thread;

fn publish_and_consume() -> u64 {
    let data = AtomicU64::new(0);
    let ready = AtomicBool::new(false);
    thread::scope(|s| {
        s.spawn(|| {
            data.store(42, Ordering::Relaxed);
            // Release: everything above becomes visible to a reader that sees `true`.
            ready.store(true, Ordering::Release);
        });
        let consumer = s.spawn(|| {
            while !ready.load(Ordering::Acquire) {
                std::hint::spin_loop();
            }
            data.load(Ordering::Relaxed)
        });
        consumer.join().unwrap()
    })
}

fn cas_max(cell: &AtomicU64, candidate: u64) {
    let mut current = cell.load(Ordering::Relaxed);
    while candidate > current {
        match cell.compare_exchange_weak(current, candidate, Ordering::Relaxed, Ordering::Relaxed) {
            Ok(_) => break,
            Err(actual) => current = actual,
        }
    }
}

fn main() {
    for _ in 0..200 {
        assert_eq!(publish_and_consume(), 42);
    }
    println!("consumer always saw {}", publish_and_consume());

    let counter = AtomicU64::new(0);
    thread::scope(|s| {
        for _ in 0..4 {
            s.spawn(|| {
                for _ in 0..25_000 {
                    counter.fetch_add(1, Ordering::Relaxed);
                }
            });
        }
    });
    println!("relaxed counter total = {}", counter.load(Ordering::Relaxed));

    let manual = AtomicU64::new(0);
    let builtin = AtomicU64::new(0);
    thread::scope(|s| {
        for t in 0..8u64 {
            let (manual, builtin) = (&manual, &builtin);
            s.spawn(move || {
                for i in 0..1000u64 {
                    let value = (t * 1000 + i) * 7919 % 10_007;
                    cas_max(manual, value);
                    builtin.fetch_max(value, Ordering::Relaxed);
                }
            });
        }
    });
    assert_eq!(manual.load(Ordering::Relaxed), builtin.load(Ordering::Relaxed));
    println!("max from CAS loop = {}", manual.load(Ordering::Relaxed));
}

