struct RingModel<T> {
    slots: Vec<Option<T>>,
    head: usize,
    len: usize,
}

impl<T> RingModel<T> {
    fn new(capacity: usize) -> Self {
        RingModel { slots: (0..capacity).map(|_| None).collect(), head: 0, len: 0 }
    }

    fn push(&mut self, value: T) -> Result<(), T> {
        if self.len == self.slots.len() {
            return Err(value);
        }
        let index = (self.head + self.len) % self.slots.len();
        self.slots[index] = Some(value);
        self.len += 1;
        Ok(())
    }

    fn pop(&mut self) -> Option<T> {
        if self.len == 0 {
            return None;
        }
        let value = self.slots[self.head].take();
        self.head = (self.head + 1) % self.slots.len();
        self.len -= 1;
        value
    }
}

fn main() {
    let mut ring = RingModel::new(4);
    for i in 0..4 {
        assert_eq!(ring.push(i), Ok(()));
    }
    assert_eq!(ring.push(4), Err(4));
    let mut seen = Vec::new();
    let mut next = 4;
    for _ in 0..20 {
        seen.push(ring.pop().unwrap());
        assert_eq!(ring.push(next), Ok(()));
        next += 1;
    }
    while let Some(value) = ring.pop() {
        seen.push(value);
    }
    assert_eq!(seen, (0..24).collect::<Vec<_>>());
    println!("FIFO preserved across {} items with capacity 4", seen.len());
}

