use std::alloc::{GlobalAlloc, Layout, System};
use std::sync::atomic::{AtomicUsize, Ordering};

struct Counting;

static ALLOCATIONS: AtomicUsize = AtomicUsize::new(0);

// SAFETY: every method forwards to System unchanged, so System's contract holds;
// the only addition is a relaxed counter increment.
unsafe impl GlobalAlloc for Counting {
    unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
        ALLOCATIONS.fetch_add(1, Ordering::Relaxed);
        unsafe { System.alloc(layout) }
    }

    unsafe fn dealloc(&self, ptr: *mut u8, layout: Layout) {
        unsafe { System.dealloc(ptr, layout) }
    }

    unsafe fn realloc(&self, ptr: *mut u8, layout: Layout, new_size: usize) -> *mut u8 {
        ALLOCATIONS.fetch_add(1, Ordering::Relaxed);
        unsafe { System.realloc(ptr, layout, new_size) }
    }
}

#[global_allocator]
static GLOBAL: Counting = Counting;

fn allocations_during<R>(work: impl FnOnce() -> R) -> (R, usize) {
    let before = ALLOCATIONS.load(Ordering::Relaxed);
    let result = work();
    (result, ALLOCATIONS.load(Ordering::Relaxed) - before)
}

use std::fmt::Write;
use std::hint::black_box;

#[derive(Debug, PartialEq)]
struct Order {
    buy: bool,
    qty: u32,
    price: i64,
}

fn parse_order(line: &str) -> Option<Order> {
    let mut parts = line.split_ascii_whitespace();
    let side = parts.next()?;
    let qty = parts.next()?.parse().ok()?;
    let price = parts.next()?.parse().ok()?;
    Some(Order { buy: side == "BUY", qty, price })
}

fn render(order: &Order, out: &mut String) {
    out.clear();
    write!(out, "{} {}@{}", if order.buy { "B" } else { "S" }, order.qty, order.price).unwrap();
}

fn main() {
    let lines: Vec<String> = (0..1000)
        .map(|i| format!("{} {} {}", if i % 2 == 0 { "BUY" } else { "SELL" }, 1 + i % 9, 10_000 + i))
        .collect();
    let mut out = String::with_capacity(64);

    let ((notional, last), hot_allocations) = allocations_during(|| {
        let mut notional = 0i64;
        for line in &lines {
            let order = parse_order(line).unwrap();
            notional += i64::from(order.qty) * order.price;
            render(&order, &mut out);
        }
        (notional, out.len())
    });
    println!("notional = {notional}, last rendered length = {last}");
    println!("hot path allocations = {hot_allocations}");

    let (_, naive_allocations) = allocations_during(|| {
        for line in &lines {
            let words: Vec<String> = line.split(' ').map(String::from).collect();
            black_box(words);
        }
    });
    println!("naive path allocates at least once per line: {}", naive_allocations >= lines.len());
    println!("rendered sample = {out}");
}

