unsafe impl GlobalAlloc for Counting {
    unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
        ALLOCATIONS.fetch_add(1, Ordering::Relaxed);
        unsafe { System.alloc(layout) }
    }

    unsafe fn dealloc(&self, ptr: *mut u8, layout: Layout) {
        unsafe { System.dealloc(ptr, layout) }
    }

    unsafe fn realloc(&self, ptr: *mut u8, layout: Layout, new_size: usize) -> *mut u8 {
        ALLOCATIONS.fetch_add(1, Ordering::Relaxed);
        unsafe { System.realloc(ptr, layout, new_size) }
    }
}

#[global_allocator]
static GLOBAL: Counting = Counting;

fn allocations_during<R>(work: impl FnOnce() -> R) -> (R, usize) {
    let before = ALLOCATIONS.load(Ordering::Relaxed);
    let result = work();
    (result, ALLOCATIONS.load(Ordering::Relaxed) - before)
}

fn frame_grow(prices: &[i64]) -> usize {
    let mut v = Vec::new();
    for p in prices {
        v.push(*p);
    }
    v.len()
}

fn frame_presized(prices: &[i64]) -> usize {
    let mut v = Vec::with_capacity(prices.len());
    for p in prices {
        v.push(*p);
    }
    v.len()
}

fn frame_reused(prices: &[i64], scratch: &mut Vec<i64>) -> usize {
    scratch.clear();
    scratch.extend_from_slice(prices);
    scratch.len()
}

fn main() {
    let prices: Vec<i64> = (0..1000).collect();
    let (_, grow) = allocations_during(|| frame_grow(&prices));
    let (_, presized) = allocations_during(|| frame_presized(&prices));
    let mut scratch = Vec::with_capacity(prices.len());
    let (_, reused) = allocations_during(|| {
        for _ in 0..100 {
            frame_reused(&prices, &mut scratch);
        }
    });
    println!("grow-from-empty allocates more than once: {}", grow > 1);
    println!("with_capacity allocations = {presized}");
    println!("reused buffer allocations over 100 frames = {reused}");
}

