/// Sum of 1^2 + 2^2 + ... + n^2 by iteration.
pub fn sum_squares(n: u64) -> u64 {
    (1..=n).map(|x| x * x).sum()
}

/// Same value from the closed form n(n+1)(2n+1)/6, with a u128 intermediate so
/// the multiplication cannot overflow for any u64 input that fits the answer.
pub fn sum_squares_closed(n: u64) -> u64 {
    let n = u128::from(n);
    (n * (n + 1) * (2 * n + 1) / 6) as u64
}

/// Four squares per step; the remaining 0-3 values are added one at a time.
pub fn sum_squares_chunks(n: u64) -> u64 {
    let mut total = 0u64;
    let mut x = 1u64;
    while x + 3 <= n {
        total += x * x + (x + 1) * (x + 1) + (x + 2) * (x + 2) + (x + 3) * (x + 3);
        x += 4;
    }
    while x <= n {
        total += x * x;
        x += 1;
    }
    total
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn implementations_agree() {
        for n in [0, 1, 2, 10, 1_000, 100_000] {
            assert_eq!(sum_squares(n), sum_squares_closed(n), "n = {n}");
        }
    }

    #[test]
    fn chunked_version_agrees_including_remainders() {
        for n in 0..=40 {
            assert_eq!(sum_squares_chunks(n), sum_squares(n), "n = {n}");
        }
    }

    #[test]
    fn known_value() {
        assert_eq!(sum_squares_closed(10_000), 333_383_335_000);
    }
}

use bench_lab::{sum_squares, sum_squares_chunks, sum_squares_closed};
use criterion::{BenchmarkId, Criterion, Throughput, criterion_group, criterion_main};
use std::hint::black_box;

fn bench_sums(c: &mut Criterion) {
    let mut group = c.benchmark_group("sum_squares");
    for n in [1_000u64, 100_000] {
        group.throughput(Throughput::Elements(n));
        group.bench_with_input(BenchmarkId::new("iterator", n), &n, |b, &n| {
            b.iter(|| sum_squares(black_box(n)))
        });
        group.bench_with_input(BenchmarkId::new("chunks", n), &n, |b, &n| {
            b.iter(|| sum_squares_chunks(black_box(n)))
        });
        group.bench_with_input(BenchmarkId::new("closed_form", n), &n, |b, &n| {
            b.iter(|| sum_squares_closed(black_box(n)))
        });
    }
    group.finish();
}

criterion_group!(benches, bench_sums);
criterion_main!(benches);

