#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Side {
    Buy,
    Sell,
}

#[derive(Debug, PartialEq)]
enum Message<'a> {
    Add { ts: u64, id: u64, side: Side, shares: u32, stock: &'a str, price: u32 },
    Cancel { ts: u64, id: u64, shares: u32 },
    Execute { ts: u64, id: u64, shares: u32, match_id: u64 },
}

#[derive(Debug, PartialEq)]
enum ParseError {
    Truncated { needed: usize, have: usize },
    UnknownType(u8),
    BadSide(u8),
    BadSymbol,
}

fn frame_len(kind: u8) -> Option<usize> {
    match kind {
        b'A' => Some(34),
        b'X' => Some(21),
        b'E' => Some(29),
        _ => None,
    }
}

fn be_u32(frame: &[u8], at: usize) -> u32 {
    u32::from_be_bytes(frame[at..at + 4].try_into().unwrap())
}

fn be_u64(frame: &[u8], at: usize) -> u64 {
    u64::from_be_bytes(frame[at..at + 8].try_into().unwrap())
}

/// Parse one frame from the front of `buf`; returns the message and bytes consumed.
fn parse(buf: &[u8]) -> Result<(Message<'_>, usize), ParseError> {
    let kind = *buf.first().ok_or(ParseError::Truncated { needed: 1, have: 0 })?;
    let len = frame_len(kind).ok_or(ParseError::UnknownType(kind))?;
    if buf.len() < len {
        return Err(ParseError::Truncated { needed: len, have: buf.len() });
    }
    let frame = &buf[..len];
    let (ts, id) = (be_u64(frame, 1), be_u64(frame, 9));
    let message = match kind {
        b'A' => {
            let side = match frame[17] {
                b'B' => Side::Buy,
                b'S' => Side::Sell,
                other => return Err(ParseError::BadSide(other)),
            };
            let stock = std::str::from_utf8(&frame[22..30])
                .ok()
                .filter(|s| s.is_ascii())
                .ok_or(ParseError::BadSymbol)?
                .trim_end_matches(' ');
            Message::Add { ts, id, side, shares: be_u32(frame, 18), stock, price: be_u32(frame, 30) }
        }
        b'X' => Message::Cancel { ts, id, shares: be_u32(frame, 17) },
        _ => Message::Execute { ts, id, shares: be_u32(frame, 17), match_id: be_u64(frame, 21) },
    };
    Ok((message, len))
}

/// Decode every complete frame; returns the messages, the unconsumed tail and any corruption error.
fn parse_all(mut buf: &[u8]) -> (Vec<Message<'_>>, &[u8], Option<ParseError>) {
    let mut messages = Vec::new();
    while !buf.is_empty() {
        match parse(buf) {
            Ok((message, used)) => {
                messages.push(message);
                buf = &buf[used..];
            }
            Err(ParseError::Truncated { .. }) => return (messages, buf, None),
            Err(error) => return (messages, buf, Some(error)),
        }
    }
    (messages, buf, None)
}

fn encode_add(ts: u64, id: u64, side: u8, shares: u32, stock: &str, price: u32) -> Vec<u8> {
    let mut frame = vec![b'A'];
    frame.extend(ts.to_be_bytes());
    frame.extend(id.to_be_bytes());
    frame.push(side);
    frame.extend(shares.to_be_bytes());
    let mut symbol = [b' '; 8];
    symbol[..stock.len()].copy_from_slice(stock.as_bytes());
    frame.extend(symbol);
    frame.extend(price.to_be_bytes());
    frame
}

fn encode_cancel(ts: u64, id: u64, shares: u32) -> Vec<u8> {
    let mut frame = vec![b'X'];
    frame.extend(ts.to_be_bytes());
    frame.extend(id.to_be_bytes());
    frame.extend(shares.to_be_bytes());
    frame
}

fn encode_execute(ts: u64, id: u64, shares: u32, match_id: u64) -> Vec<u8> {
    let mut frame = vec![b'E'];
    frame.extend(ts.to_be_bytes());
    frame.extend(id.to_be_bytes());
    frame.extend(shares.to_be_bytes());
    frame.extend(match_id.to_be_bytes());
    frame
}

fn main() {
    let mut stream = encode_add(1_000, 7, b'B', 300, "AAPL", 1_895_000);
    stream.extend(encode_cancel(1_050, 7, 100));
    stream.extend(encode_execute(1_090, 7, 200, 555));
    let second_add = encode_add(1_100, 8, b'S', 50, "MSFT", 4_112_500);
    stream.extend(&second_add[..10]);

    let (messages, tail, error) = parse_all(&stream);
    for message in &messages {
        println!("{message:?}");
    }
    println!("tail = {} bytes, error = {error:?}", tail.len());

    let mut buffer = tail.to_vec();
    buffer.extend(&second_add[10..]);
    let (more, tail, error) = parse_all(&buffer);
    println!("after the next read: {more:?}, tail = {} bytes, error = {error:?}", tail.len());

    println!("unknown type: {:?}", parse(b"Z0000").map(|_| ()));
    println!("bad side: {:?}", parse(&encode_add(1, 1, b'?', 1, "X", 1)).map(|_| ()));
    println!("empty buffer: {:?}", parse(&[]).map(|_| ()));
    println!("Add frame is {} bytes, Cancel {}, Execute {}", frame_len(b'A').unwrap(), frame_len(b'X').unwrap(), frame_len(b'E').unwrap());
}

