use std::collections::BTreeMap;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Side {
    Bid,
    Ask,
}

#[derive(Debug, PartialEq)]
enum BookError {
    OutOfRange,
    OffTick,
    Insufficient,
}

struct DenseBook {
    base: i64,
    tick: i64,
    bids: Vec<u64>,
    asks: Vec<u64>,
    best_bid: Option<usize>,
    best_ask: Option<usize>,
}

impl DenseBook {
    fn new(base: i64, tick: i64, levels: usize) -> Self {
        DenseBook { base, tick, bids: vec![0; levels], asks: vec![0; levels], best_bid: None, best_ask: None }
    }

    fn index(&self, price: i64) -> Result<usize, BookError> {
        let offset = price - self.base;
        if offset < 0 || offset / self.tick >= self.bids.len() as i64 {
            return Err(BookError::OutOfRange);
        }
        if offset % self.tick != 0 {
            return Err(BookError::OffTick);
        }
        Ok((offset / self.tick) as usize)
    }

    fn price(&self, index: usize) -> i64 {
        self.base + index as i64 * self.tick
    }

    fn add(&mut self, side: Side, price: i64, qty: u64) -> Result<(), BookError> {
        let i = self.index(price)?;
        match side {
            Side::Bid => {
                self.bids[i] += qty;
                if self.best_bid.is_none_or(|b| i > b) {
                    self.best_bid = Some(i);
                }
            }
            Side::Ask => {
                self.asks[i] += qty;
                if self.best_ask.is_none_or(|a| i < a) {
                    self.best_ask = Some(i);
                }
            }
        }
        Ok(())
    }

    fn reduce(&mut self, side: Side, price: i64, qty: u64) -> Result<(), BookError> {
        let i = self.index(price)?;
        let level = if side == Side::Bid { &mut self.bids[i] } else { &mut self.asks[i] };
        if *level < qty {
            return Err(BookError::Insufficient);
        }
        *level -= qty;
        if *level == 0 {
            match side {
                Side::Bid if self.best_bid == Some(i) => {
                    self.best_bid = (0..i).rev().find(|&j| self.bids[j] > 0);
                }
                Side::Ask if self.best_ask == Some(i) => {
                    self.best_ask = (i + 1..self.asks.len()).find(|&j| self.asks[j] > 0);
                }
                _ => {}
            }
        }
        Ok(())
    }

    fn best_bid(&self) -> Option<(i64, u64)> {
        self.best_bid.map(|i| (self.price(i), self.bids[i]))
    }

    fn best_ask(&self) -> Option<(i64, u64)> {
        self.best_ask.map(|i| (self.price(i), self.asks[i]))
    }
}

/// Simple ordered-map reference model used to check the array book.
#[derive(Default)]
struct Model {
    bids: BTreeMap<i64, u64>,
    asks: BTreeMap<i64, u64>,
}

impl Model {
    fn apply(&mut self, side: Side, price: i64, qty: i64) {
        let book = if side == Side::Bid { &mut self.bids } else { &mut self.asks };
        let level = book.entry(price).or_insert(0);
        *level = (*level as i64 + qty) as u64;
        if *level == 0 {
            book.remove(&price);
        }
    }
}

fn main() {
    let mut book = DenseBook::new(9_000, 5, 400);
    book.add(Side::Bid, 10_000, 5).unwrap();
    book.add(Side::Bid, 9_990, 10).unwrap();
    book.add(Side::Ask, 10_010, 4).unwrap();
    book.add(Side::Ask, 10_050, 8).unwrap();
    println!("best bid = {:?}, best ask = {:?}", book.best_bid(), book.best_ask());
    book.reduce(Side::Bid, 10_000, 5).unwrap();
    println!("after the top bid empties: {:?}", book.best_bid());
    book.reduce(Side::Ask, 10_010, 4).unwrap();
    println!("after the top ask empties: {:?}", book.best_ask());
    println!("off tick: {:?}", book.add(Side::Bid, 10_003, 1));
    println!("below the range: {:?}", book.add(Side::Bid, 8_995, 1));
    println!("above the range: {:?}", book.add(Side::Ask, 11_000, 1));
    println!("over-reduce: {:?}", book.reduce(Side::Bid, 9_990, 11));

    let mut dense = DenseBook::new(10_000, 1, 200);
    let mut model = Model::default();
    let mut state = 0x9E37_79B9_7F4A_7C15u64;
    let mut next = move || {
        state ^= state << 13;
        state ^= state >> 7;
        state ^= state << 17;
        state
    };
    for _ in 0..10_000 {
        let r = next();
        let side = if r & 1 == 0 { Side::Bid } else { Side::Ask };
        // Bids live below 10_100 and asks at or above it, so the book never crosses.
        let price = if side == Side::Bid { 10_000 + (r >> 8) as i64 % 100 } else { 10_100 + (r >> 8) as i64 % 100 };
        let existing = if side == Side::Bid { dense.bids[(price - 10_000) as usize] } else { dense.asks[(price - 10_000) as usize] };
        if (r >> 40) % 3 == 0 && existing > 0 {
            let qty = 1 + (r >> 20) % existing;
            dense.reduce(side, price, qty).unwrap();
            model.apply(side, price, -(qty as i64));
        } else {
            let qty = 1 + (r >> 20) % 50;
            dense.add(side, price, qty).unwrap();
            model.apply(side, price, qty as i64);
        }
        assert_eq!(dense.best_bid(), model.bids.last_key_value().map(|(p, q)| (*p, *q)));
        assert_eq!(dense.best_ask(), model.asks.first_key_value().map(|(p, q)| (*p, *q)));
    }
    println!("array book agrees with the BTreeMap model after 10000 random operations: true");
    println!("array memory for 200 levels: {} bytes per side", dense.bids.len() * size_of::<u64>());
}

