#[derive(Clone, Copy, PartialEq)]
enum Side {
    Bid,
    Ask,
}

struct Book {
    base: i64,
    bids: Vec<u64>,
    asks: Vec<u64>,
}

impl Book {
    fn depth(&self, side: Side, n: usize) -> Vec<(i64, u64)> {
        let at = |i: usize| self.base + i as i64;
        match side {
            Side::Bid => (0..self.bids.len()).rev().filter(|&i| self.bids[i] > 0).take(n).map(|i| (at(i), self.bids[i])).collect(),
            Side::Ask => (0..self.asks.len()).filter(|&i| self.asks[i] > 0).take(n).map(|i| (at(i), self.asks[i])).collect(),
        }
    }
}

fn main() {
    let mut book = Book { base: 90, bids: vec![0; 30], asks: vec![0; 30] };
    for (price, qty) in [(100, 5), (98, 7), (97, 9)] {
        book.bids[(price - 90) as usize] = qty;
    }
    for (price, qty) in [(101, 4), (103, 6)] {
        book.asks[(price - 90) as usize] = qty;
    }
    assert_eq!(book.depth(Side::Bid, 2), vec![(100, 5), (98, 7)]);
    assert_eq!(book.depth(Side::Ask, 5), vec![(101, 4), (103, 6)]);
    println!("bids = {:?}, asks = {:?}", book.depth(Side::Bid, 3), book.depth(Side::Ask, 3));
}

