use std::collections::{BTreeMap, HashMap, VecDeque};

pub type Price = i64;
pub type Qty = u32;
pub type OrderId = u64;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Side {
    Buy,
    Sell,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Kind {
    Limit(Price),
    Market,
}

/// Time in force: Gtc rests the unfilled remainder, Ioc cancels it.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Tif {
    Gtc,
    Ioc,
}

#[derive(Clone, Copy, Debug)]
pub struct Order {
    pub id: OrderId,
    pub side: Side,
    pub kind: Kind,
    pub qty: Qty,
    pub tif: Tif,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Trade {
    pub taker: OrderId,
    pub maker: OrderId,
    pub price: Price,
    pub qty: Qty,
}

#[derive(Debug, PartialEq, Eq)]
pub enum Reject {
    /// The id belongs to an order that is still resting. Ids of filled or cancelled orders may be reused.
    DuplicateId,
    ZeroQuantity,
}

#[derive(Debug, Default, PartialEq, Eq)]
pub struct Outcome {
    pub trades: Vec<Trade>,
    /// Quantity left resting on the book (Gtc limit orders only).
    pub resting: Option<Qty>,
    /// Quantity cancelled because it could not trade and may not rest.
    pub cancelled: Qty,
}

struct Resting {
    id: OrderId,
    qty: Qty,
}

type Levels = BTreeMap<Price, VecDeque<Resting>>;

#[derive(Default)]
pub struct Engine {
    bids: Levels,
    asks: Levels,
    index: HashMap<OrderId, (Side, Price)>,
}

/// Trade the taker against the best prices of `book` until it is filled or no price is acceptable.
fn match_against(
    book: &mut Levels,
    index: &mut HashMap<OrderId, (Side, Price)>,
    taker: &Order,
    limit: Option<Price>,
    remaining: &mut Qty,
    trades: &mut Vec<Trade>,
) {
    while *remaining > 0 {
        let best = match taker.side {
            Side::Buy => book.keys().next().copied(),
            Side::Sell => book.keys().next_back().copied(),
        };
        let Some(price) = best else { break };
        let acceptable = limit.is_none_or(|l| match taker.side {
            Side::Buy => price <= l,
            Side::Sell => price >= l,
        });
        if !acceptable {
            break;
        }
        let queue = book.get_mut(&price).expect("best price has a queue");
        while *remaining > 0 {
            let Some(front) = queue.front_mut() else { break };
            let qty = (*remaining).min(front.qty);
            trades.push(Trade { taker: taker.id, maker: front.id, price, qty });
            front.qty -= qty;
            *remaining -= qty;
            if front.qty == 0 {
                index.remove(&front.id);
                queue.pop_front();
            }
        }
        if queue.is_empty() {
            book.remove(&price);
        }
    }
}

impl Engine {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn best_bid(&self) -> Option<Price> {
        self.bids.keys().next_back().copied()
    }

    pub fn best_ask(&self) -> Option<Price> {
        self.asks.keys().next().copied()
    }

    /// Total quantity resting at a price on one side.
    pub fn depth_at(&self, side: Side, price: Price) -> Qty {
        let levels = if side == Side::Buy { &self.bids } else { &self.asks };
        levels.get(&price).map_or(0, |q| q.iter().map(|o| o.qty).sum())
    }

    pub fn submit(&mut self, order: Order) -> Result<Outcome, Reject> {
        if order.qty == 0 {
            return Err(Reject::ZeroQuantity);
        }
        if self.index.contains_key(&order.id) {
            return Err(Reject::DuplicateId);
        }
        let limit = match order.kind {
            Kind::Limit(price) => Some(price),
            Kind::Market => None,
        };
        let mut remaining = order.qty;
        let mut trades = Vec::new();
        let opposite = if order.side == Side::Buy { &mut self.asks } else { &mut self.bids };
        match_against(opposite, &mut self.index, &order, limit, &mut remaining, &mut trades);

        let mut outcome = Outcome { trades, resting: None, cancelled: 0 };
        if remaining > 0 {
            match (order.kind, order.tif) {
                (Kind::Limit(price), Tif::Gtc) => {
                    let levels = if order.side == Side::Buy { &mut self.bids } else { &mut self.asks };
                    levels.entry(price).or_default().push_back(Resting { id: order.id, qty: remaining });
                    self.index.insert(order.id, (order.side, price));
                    outcome.resting = Some(remaining);
                }
                _ => outcome.cancelled = remaining,
            }
        }
        Ok(outcome)
    }

    /// Cancel a resting order; returns false if the id is not resting.
    pub fn cancel(&mut self, id: OrderId) -> bool {
        let Some((side, price)) = self.index.remove(&id) else { return false };
        let levels = if side == Side::Buy { &mut self.bids } else { &mut self.asks };
        let queue = levels.get_mut(&price).expect("indexed order has a level");
        queue.retain(|o| o.id != id);
        if queue.is_empty() {
            levels.remove(&price);
        }
        true
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn limit(id: OrderId, side: Side, price: Price, qty: Qty) -> Order {
        Order { id, side, kind: Kind::Limit(price), qty, tif: Tif::Gtc }
    }

    #[test]
    fn fifo_priority_within_a_level() {
        let mut engine = Engine::new();
        engine.submit(limit(1, Side::Sell, 101, 5)).unwrap();
        engine.submit(limit(2, Side::Sell, 101, 5)).unwrap();
        let outcome = engine.submit(limit(3, Side::Buy, 101, 6)).unwrap();
        let makers: Vec<_> = outcome.trades.iter().map(|t| (t.maker, t.qty)).collect();
        assert_eq!(makers, vec![(1, 5), (2, 1)]);
    }

    #[test]
    fn trades_execute_at_the_resting_price() {
        let mut engine = Engine::new();
        engine.submit(limit(1, Side::Sell, 100, 5)).unwrap();
        let outcome = engine.submit(limit(2, Side::Buy, 105, 5)).unwrap();
        assert_eq!(outcome.trades, vec![Trade { taker: 2, maker: 1, price: 100, qty: 5 }]);
    }

    #[test]
    fn limit_price_is_inclusive_and_better_prices_come_first() {
        let mut engine = Engine::new();
        engine.submit(limit(1, Side::Sell, 102, 3)).unwrap();
        engine.submit(limit(2, Side::Sell, 101, 3)).unwrap();
        let outcome = engine.submit(limit(3, Side::Buy, 102, 6)).unwrap();
        let prices: Vec<_> = outcome.trades.iter().map(|t| t.price).collect();
        assert_eq!(prices, vec![101, 102]);
        assert_eq!(engine.best_ask(), None);
    }

    #[test]
    fn partial_fill_rests_the_remainder_and_updates_the_book() {
        let mut engine = Engine::new();
        engine.submit(limit(1, Side::Sell, 101, 4)).unwrap();
        let outcome = engine.submit(limit(2, Side::Buy, 101, 10)).unwrap();
        assert_eq!(outcome.resting, Some(6));
        assert_eq!(engine.best_bid(), Some(101));
        assert_eq!(engine.depth_at(Side::Buy, 101), 6);
        assert_eq!(engine.best_ask(), None);
    }

    #[test]
    fn ioc_and_market_remainders_are_cancelled_not_rested() {
        let mut engine = Engine::new();
        engine.submit(limit(1, Side::Sell, 101, 4)).unwrap();
        let ioc = Order { id: 2, side: Side::Buy, kind: Kind::Limit(101), qty: 10, tif: Tif::Ioc };
        let outcome = engine.submit(ioc).unwrap();
        assert_eq!((outcome.cancelled, outcome.resting), (6, None));
        let market = Order { id: 3, side: Side::Sell, kind: Kind::Market, qty: 5, tif: Tif::Gtc };
        let outcome = engine.submit(market).unwrap();
        assert_eq!((outcome.trades.len(), outcome.cancelled), (0, 5));
        assert_eq!(engine.best_bid(), None);
    }

    #[test]
    fn cancel_removes_only_the_named_order() {
        let mut engine = Engine::new();
        engine.submit(limit(1, Side::Buy, 100, 5)).unwrap();
        engine.submit(limit(2, Side::Buy, 100, 7)).unwrap();
        assert!(engine.cancel(1));
        assert!(!engine.cancel(1));
        assert_eq!(engine.depth_at(Side::Buy, 100), 7);
        assert!(engine.cancel(2));
        assert_eq!(engine.best_bid(), None);
    }

    #[test]
    fn invalid_orders_are_rejected() {
        let mut engine = Engine::new();
        assert_eq!(engine.submit(limit(1, Side::Buy, 100, 0)).unwrap_err(), Reject::ZeroQuantity);
        engine.submit(limit(1, Side::Buy, 100, 5)).unwrap();
        assert_eq!(engine.submit(limit(1, Side::Sell, 200, 5)).unwrap_err(), Reject::DuplicateId);
    }
}

use matching_engine::{Engine, Kind, Order, Side, Tif};

fn show(label: &str, outcome: &matching_engine::Outcome) {
    println!("{label}");
    for t in &outcome.trades {
        println!("  trade taker={} maker={} {}@{}", t.taker, t.maker, t.qty, t.price);
    }
    println!("  resting={:?} cancelled={}", outcome.resting, outcome.cancelled);
}

fn main() {
    let mut engine = Engine::new();
    for (id, price, qty) in [(1, 101, 5), (2, 101, 7), (3, 102, 4)] {
        engine.submit(Order { id, side: Side::Sell, kind: Kind::Limit(price), qty, tif: Tif::Gtc }).unwrap();
    }
    let buy = Order { id: 4, side: Side::Buy, kind: Kind::Limit(101), qty: 9, tif: Tif::Gtc };
    show("buy limit 9 @ 101", &engine.submit(buy).unwrap());
    let market = Order { id: 5, side: Side::Buy, kind: Kind::Market, qty: 10, tif: Tif::Gtc };
    show("buy market 10", &engine.submit(market).unwrap());
    println!("best bid = {:?}, best ask = {:?}", engine.best_bid(), engine.best_ask());
}

use matching_engine::{Engine, Kind, Order, OrderId, Price, Qty, Side, Tif};

fn limit(id: OrderId, side: Side, price: Price, qty: Qty) -> Order {
    Order { id, side, kind: Kind::Limit(price), qty, tif: Tif::Gtc }
}

/// Deterministic pseudo-random flow; checks quantity conservation and that the book never crosses.
#[test]
fn random_flow_conserves_quantity_and_never_crosses() {
    let mut engine = Engine::new();
    let mut state = 0x2545_F491_4F6C_DD1Du64;
    let mut next = move || {
        state ^= state << 13;
        state ^= state >> 7;
        state ^= state << 17;
        state
    };
    let (mut submitted, mut traded, mut cancelled, mut resting) = (0u64, 0u64, 0u64, 0u64);
    for id in 1..=2000u64 {
        let r = next();
        let side = if r & 1 == 0 { Side::Buy } else { Side::Sell };
        let price = 95 + (r >> 8) as i64 % 11;
        let qty = 1 + (r >> 20) as u32 % 20;
        let outcome = engine.submit(limit(id, side, price, qty)).unwrap();
        submitted += u64::from(qty);
        let filled: u64 = outcome.trades.iter().map(|t| u64::from(t.qty)).sum();
        traded += filled;
        cancelled += u64::from(outcome.cancelled);
        // Each trade consumes quantity from both the taker and a maker.
        resting = resting + u64::from(outcome.resting.unwrap_or(0)) - filled;
        if let (Some(bid), Some(ask)) = (engine.best_bid(), engine.best_ask()) {
            assert!(bid < ask, "book crossed: {bid} >= {ask}");
        }
    }
    let on_book: u64 = (90..=110)
        .map(|p| u64::from(engine.depth_at(Side::Buy, p)) + u64::from(engine.depth_at(Side::Sell, p)))
        .sum();
    assert_eq!(on_book, resting);
    assert_eq!(submitted, 2 * traded + cancelled + on_book);
}

