use matching_engine::{Engine, Kind, Order, OrderId, Price, Qty, Side, Tif};

fn limit(id: OrderId, side: Side, price: Price, qty: Qty) -> Order {
    Order { id, side, kind: Kind::Limit(price), qty, tif: Tif::Gtc }
}

/// Deterministic pseudo-random flow; checks quantity conservation and that the book never crosses.
#[test]
fn random_flow_conserves_quantity_and_never_crosses() {
    let mut engine = Engine::new();
    let mut state = 0x2545_F491_4F6C_DD1Du64;
    let mut next = move || {
        state ^= state << 13;
        state ^= state >> 7;
        state ^= state << 17;
        state
    };
    let (mut submitted, mut traded, mut cancelled, mut resting) = (0u64, 0u64, 0u64, 0u64);
    for id in 1..=2000u64 {
        let r = next();
        let side = if r & 1 == 0 { Side::Buy } else { Side::Sell };
        let price = 95 + (r >> 8) as i64 % 11;
        let qty = 1 + (r >> 20) as u32 % 20;
        let outcome = engine.submit(limit(id, side, price, qty)).unwrap();
        submitted += u64::from(qty);
        let filled: u64 = outcome.trades.iter().map(|t| u64::from(t.qty)).sum();
        traded += filled;
        cancelled += u64::from(outcome.cancelled);
        // Each trade consumes quantity from both the taker and a maker.
        resting = resting + u64::from(outcome.resting.unwrap_or(0)) - filled;
        if let (Some(bid), Some(ask)) = (engine.best_bid(), engine.best_ask()) {
            assert!(bid < ask, "book crossed: {bid} >= {ask}");
        }
    }
    let on_book: u64 = (90..=110)
        .map(|p| u64::from(engine.depth_at(Side::Buy, p)) + u64::from(engine.depth_at(Side::Sell, p)))
        .sum();
    assert_eq!(on_book, resting);
    assert_eq!(submitted, 2 * traded + cancelled + on_book);
}

#[test]
fn fill_or_kill_trades_everything_or_nothing() {
    let mut engine = Engine::new();
    engine.submit(limit(1, Side::Sell, 101, 4)).unwrap();
    engine.submit(limit(2, Side::Sell, 102, 4)).unwrap();
    let fok = |id, qty| Order { id, side: Side::Buy, kind: Kind::Limit(102), qty, tif: Tif::Fok };
    let rejected = engine.submit(fok(3, 9)).unwrap();
    assert!(rejected.trades.is_empty());
    assert_eq!(rejected.cancelled, 9);
    assert_eq!(engine.depth_at(Side::Sell, 101), 4);
    let filled = engine.submit(fok(4, 8)).unwrap();
    assert_eq!(filled.trades.iter().map(|t| t.qty).sum::<u32>(), 8);
    assert_eq!(engine.best_ask(), None);
}

