use std::collections::VecDeque;

#[derive(Default)]
struct Fifo {
    lots: VecDeque<(i64, i64)>,
    realized: i128,
}

impl Fifo {
    fn sell_long(&mut self, mut qty: i64, price: i64) {
        while qty > 0 {
            let lot = self.lots.front_mut().expect("selling more than held");
            let closed = qty.min(lot.0);
            self.realized += i128::from(price - lot.1) * i128::from(closed);
            lot.0 -= closed;
            qty -= closed;
            if lot.0 == 0 {
                self.lots.pop_front();
            }
        }
    }
}

#[derive(Default)]
struct Average {
    qty: i64,
    cost: i128,
    realized: i128,
}

impl Average {
    fn buy(&mut self, qty: i64, price: i64) {
        self.qty += qty;
        self.cost += i128::from(qty) * i128::from(price);
    }

    fn sell(&mut self, qty: i64, price: i64) {
        assert!(qty <= self.qty);
        let removed = self.cost * i128::from(qty) / i128::from(self.qty);
        self.realized += i128::from(qty) * i128::from(price) - removed;
        self.cost -= removed;
        self.qty -= qty;
    }
}

fn main() {
    let (mut fifo, mut avg) = (Fifo::default(), Average::default());
    for (qty, price) in [(10, 100), (5, 102)] {
        fifo.lots.push_back((qty, price));
        avg.buy(qty, price);
    }
    fifo.sell_long(12, 105);
    avg.sell(12, 105);
    println!("after selling 12: fifo realized {}, average realized {}", fifo.realized, avg.realized);
    assert_eq!((fifo.realized, avg.realized), (56, 52));
    fifo.sell_long(3, 104);
    avg.sell(3, 104);
    assert_eq!(fifo.realized, avg.realized);
    println!("flat: fifo total {}, average total {}", fifo.realized, avg.realized);
}

