use std::f64::consts::PI;

fn pdf(x: f64) -> f64 {
    (-0.5 * x * x).exp() / (2.0 * PI).sqrt()
}

/// Standard normal CDF, Abramowitz & Stegun 26.2.17 (absolute error below 7.5e-8).
fn cdf(x: f64) -> f64 {
    let t = 1.0 / (1.0 + 0.231_641_9 * x.abs());
    let poly = t * (0.319_381_530 + t * (-0.356_563_782 + t * (1.781_477_937 + t * (-1.821_255_978 + t * 1.330_274_429))));
    let upper = pdf(x) * poly;
    if x >= 0.0 { 1.0 - upper } else { upper }
}

#[derive(Clone, Copy)]
struct Contract {
    spot: f64,
    strike: f64,
    rate: f64,
    vol: f64,
    years: f64,
}

impl Contract {
    fn d1(&self) -> f64 {
        ((self.spot / self.strike).ln() + (self.rate + 0.5 * self.vol * self.vol) * self.years) / (self.vol * self.years.sqrt())
    }

    fn d2(&self) -> f64 {
        self.d1() - self.vol * self.years.sqrt()
    }

    fn discount(&self) -> f64 {
        (-self.rate * self.years).exp()
    }

    fn call(&self) -> f64 {
        self.spot * cdf(self.d1()) - self.strike * self.discount() * cdf(self.d2())
    }

    fn put(&self) -> f64 {
        self.strike * self.discount() * cdf(-self.d2()) - self.spot * cdf(-self.d1())
    }

    fn call_delta(&self) -> f64 {
        cdf(self.d1())
    }

    fn gamma(&self) -> f64 {
        pdf(self.d1()) / (self.spot * self.vol * self.years.sqrt())
    }

    /// Price change per 1.00 (100 percentage points) of volatility.
    fn vega(&self) -> f64 {
        self.spot * pdf(self.d1()) * self.years.sqrt()
    }
}

fn implied_vol(target: f64, template: Contract) -> Option<f64> {
    let intrinsic = (template.spot - template.strike * template.discount()).max(0.0);
    if target < intrinsic || target >= template.spot {
        return None;
    }
    let (mut low, mut high) = (1e-4, 5.0);
    for _ in 0..100 {
        let mid = 0.5 * (low + high);
        let price = Contract { vol: mid, ..template }.call();
        if price < target {
            low = mid;
        } else {
            high = mid;
        }
    }
    Some(0.5 * (low + high))
}

fn main() {
    let c = Contract { spot: 100.0, strike: 100.0, rate: 0.05, vol: 0.2, years: 1.0 };
    println!("call = {:.4}, put = {:.4}", c.call(), c.put());
    println!("call matches the reference 10.4506: {}", (c.call() - 10.450_584).abs() < 1e-4);
    println!("put-call parity holds: {}", (c.call() - c.put() - (c.spot - c.strike * c.discount())).abs() < 1e-9);
    println!("delta = {:.4}, gamma = {:.4}, vega = {:.4}", c.call_delta(), c.gamma(), c.vega());

    let h = 0.01;
    let up = Contract { spot: c.spot + h, ..c };
    let down = Contract { spot: c.spot - h, ..c };
    let fd_delta = (up.call() - down.call()) / (2.0 * h);
    let fd_gamma = (up.call() - 2.0 * c.call() + down.call()) / (h * h);
    println!("finite-difference delta agrees: {}", (fd_delta - c.call_delta()).abs() < 1e-4);
    println!("finite-difference gamma agrees: {}", (fd_gamma - c.gamma()).abs() < 1e-3);
    let fd_vega = (Contract { vol: c.vol + 1e-4, ..c }.call() - Contract { vol: c.vol - 1e-4, ..c }.call()) / 2e-4;
    println!("finite-difference vega agrees: {}", (fd_vega - c.vega()).abs() < 1e-2);

    println!("cdf(0) = {:.4}, cdf(1.96) = {:.4}, cdf(-1.96) = {:.4}", cdf(0.0), cdf(1.96), cdf(-1.96));
    let market_price = Contract { vol: 0.3, ..c }.call();
    let iv = implied_vol(market_price, c).unwrap();
    println!("implied vol recovered from the price: {iv:.4}");
    println!("price below intrinsic value: {:?}", implied_vol(1.0, Contract { strike: 80.0, ..c }));
}

