/// Mean and standard error of a set of independent observations.
fn mean_and_se(values: &[f64]) -> (f64, f64) {
    let n = values.len() as f64;
    let mean = values.iter().sum::<f64>() / n;
    let variance = values.iter().map(|v| (v - mean).powi(2)).sum::<f64>() / (n - 1.0);
    (mean, (variance / n).sqrt())
}

fn main() {
    let c = Contract { spot: 100.0, strike: 100.0, rate: 0.05, vol: 0.2, years: 1.0 };
    let exact = c.black_scholes_call();
    println!("Black-Scholes call = {exact:.4}");

    let mut rng = Rng(0x0DDB_1A5E_5BAD_5EED);
    let mut plain = Vec::with_capacity(200_000);
    for _ in 0..100_000 {
        let (z1, z2) = rng.normal_pair();
        plain.push(c.discounted_call_payoff(z1));
        plain.push(c.discounted_call_payoff(z2));
    }
    let (plain_mean, plain_se) = mean_and_se(&plain);

    let mut rng = Rng(0x0DDB_1A5E_5BAD_5EED);
    let mut paired = Vec::with_capacity(100_000);
    for _ in 0..50_000 {
        let (z1, z2) = rng.normal_pair();
        for z in [z1, z2] {
            paired.push(0.5 * (c.discounted_call_payoff(z) + c.discounted_call_payoff(-z)));
        }
    }
    let (anti_mean, anti_se) = mean_and_se(&paired);
    println!("plain:      {plain_mean:.3} +/- {plain_se:.3} ({} payoffs)", plain.len());
    println!("antithetic: {anti_mean:.3} +/- {anti_se:.3} ({} payoffs)", paired.len() * 2);
    println!("plain within 4 se of exact: {}", (plain_mean - exact).abs() < 4.0 * plain_se);
    println!("antithetic within 4 se of exact: {}", (anti_mean - exact).abs() < 4.0 * anti_se);
    println!("antithetic standard error is smaller: {}", anti_se < plain_se);

    let mut rng = Rng(7);
    let finite = (0..100_000).all(|_| {
        let (a, b) = rng.normal_pair();
        a.is_finite() && b.is_finite()
    });
    println!("all Box-Muller outputs finite: {finite}");
}

