fn sorted(pnls: &[i64]) -> Vec<i64> {
    let mut v = pnls.to_vec();
    v.sort_unstable();
    v
}

/// Nearest-rank VaR: the k-th worst outcome with k = ceil(n * (1 - confidence)).
/// `confidence_bp` is in basis points, so 95% is 9500. The result is a positive loss.
fn var_nearest_rank(pnls: &[i64], confidence_bp: u32) -> i64 {
    assert!(!pnls.is_empty() && (1..10_000).contains(&confidence_bp));
    let n = pnls.len() as u64;
    let k = (n * u64::from(10_000 - confidence_bp)).div_ceil(10_000).max(1) as usize;
    -sorted(pnls)[k - 1]
}

/// Expected shortfall: the average loss over the k worst outcomes, rounded half away from zero.
fn expected_shortfall(pnls: &[i64], confidence_bp: u32) -> i64 {
    let n = pnls.len() as u64;
    let k = (n * u64::from(10_000 - confidence_bp)).div_ceil(10_000).max(1) as usize;
    let tail: i128 = sorted(pnls)[..k].iter().map(|&x| -i128::from(x)).sum();
    let k = k as i128;
    ((2 * tail + k) / (2 * k)) as i64
}

fn sample_pnls() -> Vec<i64> {
    let mut pnls: Vec<i64> = (0..250).map(|i| (i * 7919) % 201 - 100).collect();
    pnls[17] = -400;
    pnls[123] = -250;
    pnls
}

fn main() {
    let pnls = sample_pnls();
    println!("observations = {}, worst = {}, best = {}", pnls.len(), pnls.iter().min().unwrap(), pnls.iter().max().unwrap());
    for confidence in [9000, 9500, 9900] {
        let n = pnls.len() as u64;
        let k = (n * u64::from(10_000 - confidence)).div_ceil(10_000);
        println!(
            "{}%: tail size {k}, VaR = {}, ES = {}",
            confidence / 100,
            var_nearest_rank(&pnls, confidence),
            expected_shortfall(&pnls, confidence)
        );
    }
    for confidence in [9000, 9500, 9900] {
        assert!(expected_shortfall(&pnls, confidence) >= var_nearest_rank(&pnls, confidence));
    }
    assert!(var_nearest_rank(&pnls, 9900) >= var_nearest_rank(&pnls, 9500));
    println!("ES >= VaR and higher confidence means a larger VaR: true");

    let mut changed = pnls.clone();
    changed[5] = -300;
    println!("99% VaR after one more bad day: {} -> {}", var_nearest_rank(&pnls, 9900), var_nearest_rank(&changed, 9900));
    println!("95% VaR after one more bad day: {} -> {}", var_nearest_rank(&pnls, 9500), var_nearest_rank(&changed, 9500));
    let ranked = |bp: u32| (100u64 * u64::from(10_000 - bp)).div_ceil(10_000);
    println!("n = 100: tail sizes at 90/95/99% = {}/{}/{}", ranked(9000), ranked(9500), ranked(9900));
}

