const SUB_BITS: u32 = 3;
const SUB: usize = 1 << SUB_BITS; // 8 sub-buckets per power of two => relative error <= 1/8
const BUCKETS: usize = (64 - SUB_BITS as usize) * SUB; // exact 0..8, then 8 slices per power of two up to 2^63
/// Larger values are clamped: 2^63 - 1 ns is about 292 years.
const MAX_TRACKABLE: u64 = u64::MAX >> 1;

struct Histogram {
    counts: [u64; BUCKETS],
    total: u64,
    min: u64,
    max: u64,
}

fn bucket_of(value: u64) -> usize {
    if value < SUB as u64 {
        return value as usize;
    }
    let exponent = 63 - value.leading_zeros();
    let sub = ((value >> (exponent - SUB_BITS)) & (SUB as u64 - 1)) as usize;
    (exponent - SUB_BITS + 1) as usize * SUB + sub
}

fn bucket_range(index: usize) -> (u64, u64) {
    if index < SUB {
        return (index as u64, index as u64 + 1);
    }
    let exponent = (index / SUB) as u32 + SUB_BITS - 1;
    let sub = (index % SUB) as u64;
    let width = 1u64 << (exponent - SUB_BITS);
    let lower = (SUB as u64 + sub) << (exponent - SUB_BITS);
    (lower, lower + width)
}

impl Histogram {
    fn new() -> Self {
        Histogram { counts: [0; BUCKETS], total: 0, min: u64::MAX, max: 0 }
    }

    /// Constant work and no allocation: safe to call on a hot path.
    fn record(&mut self, value: u64) {
        let value = value.min(MAX_TRACKABLE);
        self.counts[bucket_of(value)] += 1;
        self.total += 1;
        self.min = self.min.min(value);
        self.max = self.max.max(value);
    }

    /// Value at or below which `per_10000` / 10,000 of the samples fall (9990 = p99.9, 10_000 = max).
    fn percentile(&self, per_10000: u64) -> Option<u64> {
        if self.total == 0 {
            return None;
        }
        let target = (self.total * per_10000).div_ceil(10_000).max(1);
        let mut seen = 0;
        for (index, &count) in self.counts.iter().enumerate() {
            seen += count;
            if seen >= target {
                let (_, upper) = bucket_range(index);
                return Some((upper - 1).min(self.max));
            }
        }
        Some(self.max)
    }

    fn merge(&mut self, other: &Histogram) {
        for (mine, theirs) in self.counts.iter_mut().zip(&other.counts) {
            *mine += theirs;
        }
        self.total += other.total;
        self.min = self.min.min(other.min);
        self.max = self.max.max(other.max);
    }
}

fn main() {
    // Every value maps into the range reported for its bucket, and the range is narrow.
    for v in (0..5_000u64).chain([1 << 20, (1 << 20) + 12_345, 1 << 40, u64::MAX >> 1]) {
        let (low, high) = bucket_range(bucket_of(v));
        assert!(low <= v && v < high, "value {v}");
        assert!(v < 8 || (high - low) * 8 <= low, "bucket too wide for {v}");
    }
    println!("buckets = {BUCKETS}, histogram size = {} bytes", size_of::<Histogram>());
    println!("exact below 8: {}, value 100 -> range {:?}", (0..8).all(|v| bucket_range(bucket_of(v)) == (v, v + 1)), bucket_range(bucket_of(100)));

    let mut h = Histogram::new();
    for i in 1..=10_000u64 {
        h.record(i * 100);
    }
    for _ in 0..10 {
        h.record(5_000_000);
    }
    println!("samples = {}, min = {}, max = {}", h.total, h.min, h.max);
    for (label, p) in [("p50", 5000), ("p90", 9000), ("p99", 9900), ("p99.9", 9990), ("p99.99", 9999)] {
        let reported = h.percentile(p).unwrap();
        println!("{label:>6} = {reported}");
    }
    let exact_p50 = 500_000u64;
    let reported_p50 = h.percentile(5000).unwrap();
    println!("p50 within the 12.5% bound: {}", reported_p50 >= exact_p50 && reported_p50 as f64 <= exact_p50 as f64 * 1.125);
    println!("p100 is the exact maximum: {}", h.percentile(10_000) == Some(5_000_000));

    let (mut left, mut right, mut whole) = (Histogram::new(), Histogram::new(), Histogram::new());
    for i in 1..=2_000u64 {
        let v = i * 37 % 9_001;
        if i % 2 == 0 { left.record(v) } else { right.record(v) }
        whole.record(v);
    }
    left.merge(&right);
    println!("merged histogram equals the single-histogram result: {}", left.counts == whole.counts && left.total == whole.total);
    println!("empty histogram percentile: {:?}", Histogram::new().percentile(5000));
    let mut clamp = Histogram::new();
    clamp.record(u64::MAX);
    println!("u64::MAX is clamped to {} (2^63 - 1): {}", clamp.max, clamp.max == (1u64 << 63) - 1);
}

