use std::collections::VecDeque;

/// One price bar; all prices are integer ticks.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Bar {
    pub ts: i64,
    pub open: i64,
    pub high: i64,
    pub low: i64,
    pub close: i64,
}

pub trait Strategy {
    /// Called after a bar closes. Returns the target position to hold from the NEXT bar's open.
    fn on_bar(&mut self, bar: &Bar, position: i64) -> i64;
}

#[derive(Clone, Copy, Debug, Default)]
pub struct Costs {
    /// Ticks paid against us on every fill (buys fill higher, sells lower).
    pub slippage_ticks: i64,
    /// Fixed fee charged per fill, in the same tick-quantity units as PnL.
    pub fee_per_fill: i64,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Fill {
    pub ts: i64,
    pub qty: i64,
    pub price: i64,
}

#[derive(Debug)]
pub struct Report {
    pub fills: Vec<Fill>,
    /// Mark-to-market equity after each bar's close, net of fees.
    pub equity: Vec<i128>,
    pub position: i64,
    pub fees: i128,
}

/// Event loop. A decision made at a bar's close fills at the next bar's open, never earlier.
pub fn run<S: Strategy>(bars: &[Bar], strategy: &mut S, costs: Costs) -> Report {
    let mut cash: i128 = 0;
    let mut position: i64 = 0;
    let mut fees: i128 = 0;
    let mut pending: Option<i64> = None;
    let mut fills = Vec::new();
    let mut equity = Vec::with_capacity(bars.len());
    for bar in bars {
        if let Some(target) = pending.take() {
            let qty = target - position;
            if qty != 0 {
                let price = if qty > 0 { bar.open + costs.slippage_ticks } else { bar.open - costs.slippage_ticks };
                cash -= i128::from(qty) * i128::from(price);
                fees += i128::from(costs.fee_per_fill);
                position = target;
                fills.push(Fill { ts: bar.ts, qty, price });
            }
        }
        equity.push(cash + i128::from(position) * i128::from(bar.close) - fees);
        pending = Some(strategy.on_bar(bar, position));
    }
    Report { fills, equity, position, fees }
}

pub struct BuyAndHold;

impl Strategy for BuyAndHold {
    fn on_bar(&mut self, _bar: &Bar, _position: i64) -> i64 {
        1
    }
}

/// Long one unit while the fast moving average is above the slow one, flat otherwise.
pub struct SmaCross {
    fast: usize,
    slow: usize,
    closes: VecDeque<i64>,
}

impl SmaCross {
    pub fn new(fast: usize, slow: usize) -> Self {
        assert!(0 < fast && fast < slow);
        SmaCross { fast, slow, closes: VecDeque::with_capacity(slow + 1) }
    }
}

impl Strategy for SmaCross {
    fn on_bar(&mut self, bar: &Bar, _position: i64) -> i64 {
        self.closes.push_back(bar.close);
        if self.closes.len() > self.slow {
            self.closes.pop_front();
        }
        if self.closes.len() < self.slow {
            return 0;
        }
        let slow_sum: i64 = self.closes.iter().sum();
        let fast_sum: i64 = self.closes.iter().rev().take(self.fast).sum();
        // fast mean > slow mean  <=>  fast_sum * slow > slow_sum * fast (exact, no division)
        if fast_sum * self.slow as i64 > slow_sum * self.fast as i64 { 1 } else { 0 }
    }
}

impl Report {
    /// Largest peak-to-trough fall of the equity curve; never negative.
    pub fn max_drawdown(&self) -> i128 {
        let mut peak = i128::MIN;
        let mut worst = 0;
        for &e in &self.equity {
            peak = peak.max(e);
            worst = worst.max(peak - e);
        }
        worst
    }
}

