use std::collections::BTreeMap;
use std::sync::mpsc::{Receiver, SyncSender};
use std::thread::{self, JoinHandle};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Side {
    Bid,
    Ask,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Update {
    Add { seq: u64, side: Side, price: i64, qty: u64 },
    Reduce { seq: u64, side: Side, price: i64, qty: u64 },
    /// Last message of a session: the consumer stops cleanly after it.
    Shutdown { seq: u64 },
}

impl Update {
    pub fn seq(&self) -> u64 {
        match *self {
            Update::Add { seq, .. } | Update::Reduce { seq, .. } | Update::Shutdown { seq } => seq,
        }
    }
}

#[derive(Default)]
pub struct Book {
    bids: BTreeMap<i64, u64>,
    asks: BTreeMap<i64, u64>,
    pub bad_reduces: usize,
}

impl Book {
    fn levels(&mut self, side: Side) -> &mut BTreeMap<i64, u64> {
        if side == Side::Bid { &mut self.bids } else { &mut self.asks }
    }

    pub fn apply(&mut self, update: &Update) {
        match *update {
            Update::Add { side, price, qty, .. } => *self.levels(side).entry(price).or_insert(0) += qty,
            Update::Reduce { side, price, qty, .. } => {
                let levels = self.levels(side);
                match levels.get_mut(&price) {
                    Some(level) if *level >= qty => {
                        *level -= qty;
                        if *level == 0 {
                            levels.remove(&price);
                        }
                    }
                    _ => self.bad_reduces += 1,
                }
            }
            Update::Shutdown { .. } => {}
        }
    }

    pub fn best_bid(&self) -> Option<(i64, u64)> {
        self.bids.last_key_value().map(|(p, q)| (*p, *q))
    }

    pub fn best_ask(&self) -> Option<(i64, u64)> {
        self.asks.first_key_value().map(|(p, q)| (*p, *q))
    }
}

#[derive(Debug, PartialEq, Eq)]
pub struct Summary {
    pub applied: usize,
    /// (expected sequence number, received sequence number) for every discontinuity.
    pub gaps: Vec<(u64, u64)>,
    pub best_bid: Option<(i64, u64)>,
    pub best_ask: Option<(i64, u64)>,
    /// True only if a Shutdown message arrived; false if the sender vanished or `limit` was hit.
    pub clean_shutdown: bool,
    /// Reduce messages that matched no resting quantity; they are counted, never applied.
    pub bad_reduces: usize,
}

/// Send every update, stopping quietly if the receiver is gone. Returns how many were sent.
pub fn spawn_producer(updates: Vec<Update>, tx: SyncSender<Update>) -> JoinHandle<usize> {
    thread::spawn(move || {
        let mut sent = 0;
        for update in updates {
            if tx.send(update).is_err() {
                break; // consumer hung up: stop instead of panicking
            }
            sent += 1;
        }
        sent
    })
}

/// Apply updates from `rx` until Shutdown, disconnection, or `limit` applied updates.
pub fn consume(rx: Receiver<Update>, limit: Option<usize>) -> Summary {
    let mut book = Book::default();
    let mut next_seq = None;
    let mut gaps = Vec::new();
    let mut applied = 0;
    let mut clean_shutdown = false;
    while limit.is_none_or(|l| applied < l) {
        let Ok(update) = rx.recv() else { break };
        let seq = update.seq();
        if let Some(expected) = next_seq {
            if seq != expected {
                gaps.push((expected, seq));
            }
        }
        next_seq = Some(seq + 1);
        if matches!(update, Update::Shutdown { .. }) {
            clean_shutdown = true;
            break;
        }
        book.apply(&update);
        applied += 1;
    }
    Summary { applied, gaps, best_bid: book.best_bid(), best_ask: book.best_ask(), clean_shutdown, bad_reduces: book.bad_reduces }
}

use feed_lab::{Side, Update, consume, spawn_producer};
use std::sync::mpsc::sync_channel;

fn main() {
    let mut updates = Vec::new();
    let mut seq = 1;
    for i in 0..1000u64 {
        if i == 600 {
            seq += 2; // simulate two lost packets
        }
        let (side, price) = if i % 2 == 0 { (Side::Bid, 9_900 + (i % 10) as i64) } else { (Side::Ask, 10_000 + (i % 10) as i64) };
        updates.push(if i % 7 == 6 {
            // Reduce what the previous update added, so every reduce is valid.
            let Update::Add { side, price, .. } = updates[updates.len() - 1] else { unreachable!() };
            Update::Reduce { seq, side, price, qty: 1 }
        } else {
            Update::Add { seq, side, price, qty: 1 + i % 5 }
        });
        seq += 1;
    }
    updates.push(Update::Shutdown { seq });
    let total = updates.len();

    let (tx, rx) = sync_channel(16);
    let producer = spawn_producer(updates, tx);
    let summary = consume(rx, None);
    let sent = producer.join().unwrap();

    println!("sent {sent} of {total} messages");
    println!("applied = {}, gaps = {:?}", summary.applied, summary.gaps);
    println!("best bid = {:?}, best ask = {:?}", summary.best_bid, summary.best_ask);
    println!("clean shutdown = {}", summary.clean_shutdown);
}

use feed_lab::{Side, Summary, Update, consume, spawn_producer};
use std::sync::mpsc::sync_channel;

fn add(seq: u64, price: i64) -> Update {
    Update::Add { seq, side: Side::Bid, price, qty: 10 }
}

fn run(updates: Vec<Update>, capacity: usize) -> (Summary, usize) {
    let (tx, rx) = sync_channel(capacity);
    let producer = spawn_producer(updates, tx);
    let summary = consume(rx, None);
    (summary, producer.join().unwrap())
}

#[test]
fn applies_everything_in_order_and_shuts_down_cleanly() {
    let updates = vec![add(1, 100), add(2, 101), Update::Reduce { seq: 3, side: Side::Bid, price: 101, qty: 10 }, Update::Shutdown { seq: 4 }];
    let (summary, sent) = run(updates, 4);
    assert_eq!(summary.applied, 3);
    assert!(summary.gaps.is_empty() && summary.clean_shutdown);
    assert_eq!(summary.best_bid, Some((100, 10)));
    assert_eq!(sent, 4);
}

#[test]
fn a_sequence_gap_is_reported_with_expected_and_received() {
    let (summary, _) = run(vec![add(1, 100), add(2, 100), add(4, 100), Update::Shutdown { seq: 5 }], 2);
    assert_eq!(summary.gaps, vec![(3, 4)]);
    assert_eq!(summary.applied, 3);
}

#[test]
fn a_vanished_sender_is_not_a_clean_shutdown() {
    let (summary, _) = run(vec![add(1, 100), add(2, 100)], 2);
    assert_eq!(summary.applied, 2);
    assert!(!summary.clean_shutdown);
}

#[test]
fn a_tiny_bounded_channel_still_delivers_every_update_without_deadlock() {
    let mut updates: Vec<Update> = (1..=1000).map(|seq| add(seq, 100 + (seq % 5) as i64)).collect();
    updates.push(Update::Shutdown { seq: 1001 });
    let (summary, sent) = run(updates, 1);
    assert_eq!(summary.applied, 1000);
    assert_eq!(sent, 1001);
    assert!(summary.clean_shutdown);
}

#[test]
fn a_consumer_that_hangs_up_stops_the_producer_without_a_panic() {
    let updates: Vec<Update> = (1..=10_000).map(|seq| add(seq, 100)).collect();
    let (tx, rx) = sync_channel(4);
    let producer = spawn_producer(updates, tx);
    let summary = consume(rx, Some(3));
    assert_eq!(summary.applied, 3);
    assert!(!summary.clean_shutdown);
    let sent = producer.join().expect("producer must not panic");
    assert!(sent < 10_000, "producer kept sending to a closed channel");
}

#[test]
fn an_invalid_reduce_is_counted_and_not_applied() {
    let reduce = |seq, price, qty| Update::Reduce { seq, side: Side::Bid, price, qty };
    let (summary, _) = run(vec![add(1, 100), reduce(2, 101, 5), reduce(3, 100, 99), Update::Shutdown { seq: 4 }], 4);
    assert_eq!(summary.bad_reduces, 2);
    assert_eq!(summary.best_bid, Some((100, 10)));
    assert_eq!(summary.applied, 3);
}

