use std::collections::{BTreeMap, HashMap, VecDeque};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Trade {
    pub taker: u64,
    pub maker: u64,
    pub price: i64,
    pub qty: u32,
}

/// What happened to one submitted limit order.
#[derive(Debug)]
pub struct Receipt {
    pub id: u64,
    pub trades: Vec<Trade>,
    /// Quantity left resting on the book after matching.
    pub rested: u32,
}

struct Resting {
    id: u64,
    qty: u32,
}

type Levels = BTreeMap<i64, VecDeque<Resting>>;

#[derive(Default)]
pub struct Book {
    bids: Levels,
    asks: Levels,
    index: HashMap<u64, (bool, i64)>,
    next_id: u64,
}

impl Book {
    pub fn new() -> Self {
        Book { next_id: 1, ..Book::default() }
    }

    pub fn best_bid(&self) -> Option<i64> {
        self.bids.keys().next_back().copied()
    }

    pub fn best_ask(&self) -> Option<i64> {
        self.asks.keys().next().copied()
    }

    /// Total resting quantity on both sides.
    pub fn resting_total(&self) -> u64 {
        self.bids.values().chain(self.asks.values()).flatten().map(|o| u64::from(o.qty)).sum()
    }

    /// Submit a good-till-cancelled limit order; it trades against better or equal prices first.
    pub fn submit(&mut self, buy: bool, price: i64, qty: u32) -> Receipt {
        let id = self.next_id;
        self.next_id += 1;
        let mut remaining = qty;
        let mut trades = Vec::new();
        let opposite = if buy { &mut self.asks } else { &mut self.bids };
        while remaining > 0 {
            let best = if buy { opposite.keys().next().copied() } else { opposite.keys().next_back().copied() };
            let Some(level_price) = best else { break };
            let acceptable = if buy { level_price <= price } else { level_price >= price };
            if !acceptable {
                break;
            }
            let queue = opposite.get_mut(&level_price).unwrap();
            while remaining > 0 {
                let Some(front) = queue.front_mut() else { break };
                let fill = remaining.min(front.qty);
                trades.push(Trade { taker: id, maker: front.id, price: level_price, qty: fill });
                front.qty -= fill;
                remaining -= fill;
                if front.qty == 0 {
                    self.index.remove(&front.id);
                    queue.pop_front();
                }
            }
            if queue.is_empty() {
                opposite.remove(&level_price);
            }
        }
        if remaining > 0 {
            let levels = if buy { &mut self.bids } else { &mut self.asks };
            levels.entry(price).or_default().push_back(Resting { id, qty: remaining });
            self.index.insert(id, (buy, price));
        }
        Receipt { id, trades, rested: remaining }
    }

    /// Cancel a resting order and return the quantity removed.
    pub fn cancel(&mut self, id: u64) -> Option<u32> {
        let (buy, price) = self.index.remove(&id)?;
        let levels = if buy { &mut self.bids } else { &mut self.asks };
        let queue = levels.get_mut(&price)?;
        let position = queue.iter().position(|o| o.id == id)?;
        let removed = queue.remove(position)?.qty;
        if queue.is_empty() {
            levels.remove(&price);
        }
        Some(removed)
    }
}

use prop_lab::Book;
use proptest::prelude::*;
use proptest::test_runner::RngSeed;

#[derive(Clone, Debug)]
enum Op {
    Submit { buy: bool, price: i64, qty: u32 },
    /// Index into the ids handed out so far (wrapped), so some cancels hit live orders.
    Cancel(usize),
}

fn op() -> impl Strategy<Value = Op> {
    prop_oneof![
        3 => (any::<bool>(), 95i64..=105, 1u32..=20).prop_map(|(buy, price, qty)| Op::Submit { buy, price, qty }),
        1 => (0usize..64).prop_map(Op::Cancel),
    ]
}

fn config() -> ProptestConfig {
    // Fixed seed and no persistence file: the checks must be reproducible and must not write to the project directory.
    ProptestConfig { cases: 256, failure_persistence: None, rng_seed: RngSeed::Fixed(0x5EED), ..ProptestConfig::default() }
}

proptest! {
    #![proptest_config(config())]

    #[test]
    fn the_book_is_never_crossed(ops in prop::collection::vec(op(), 1..200)) {
        let mut book = Book::new();
        let mut ids = 0u64;
        for op in ops {
            match op {
                Op::Submit { buy, price, qty } => { book.submit(buy, price, qty); ids += 1; }
                Op::Cancel(i) if ids > 0 => { book.cancel(i as u64 % ids + 1); }
                Op::Cancel(_) => {}
            }
            if let (Some(bid), Some(ask)) = (book.best_bid(), book.best_ask()) {
                prop_assert!(bid < ask, "crossed book: bid {} >= ask {}", bid, ask);
            }
        }
    }

    #[test]
    fn quantity_is_conserved(ops in prop::collection::vec(op(), 1..200)) {
        let mut book = Book::new();
        let (mut submitted, mut traded, mut cancelled, mut ids) = (0u64, 0u64, 0u64, 0u64);
        for op in ops {
            match op {
                Op::Submit { buy, price, qty } => {
                    let receipt = book.submit(buy, price, qty);
                    submitted += u64::from(qty);
                    traded += receipt.trades.iter().map(|t| u64::from(t.qty)).sum::<u64>();
                    ids += 1;
                }
                Op::Cancel(i) if ids > 0 => {
                    cancelled += u64::from(book.cancel(i as u64 % ids + 1).unwrap_or(0));
                }
                Op::Cancel(_) => {}
            }
        }
        // Each traded share left both a taker and a maker.
        prop_assert_eq!(submitted, 2 * traded + cancelled + book.resting_total());
    }

    #[test]
    fn trades_respect_the_takers_limit_and_fill_makers_in_arrival_order(
        setup in prop::collection::vec((any::<bool>(), 95i64..=105, 1u32..=20), 0..60),
        buy in any::<bool>(), price in 95i64..=105, qty in 1u32..=200,
    ) {
        let mut book = Book::new();
        for (b, p, q) in setup { book.submit(b, p, q); }
        let receipt = book.submit(buy, price, qty);
        for trade in &receipt.trades {
            if buy { prop_assert!(trade.price <= price); } else { prop_assert!(trade.price >= price); }
        }
        // Within one price level the makers must be filled oldest (lowest id) first.
        for pair in receipt.trades.windows(2) {
            if pair[0].price == pair[1].price {
                prop_assert!(pair[0].maker < pair[1].maker);
            }
        }
        let filled: u32 = receipt.trades.iter().map(|t| t.qty).sum();
        prop_assert_eq!(filled + receipt.rested, qty);
    }
}

#[test]
fn cancelling_an_unknown_id_is_a_no_op() {
    let mut book = Book::new();
    book.submit(true, 100, 5);
    assert_eq!(book.cancel(99), None);
    assert_eq!(book.resting_total(), 5);
}

