        self.bids.values().chain(self.asks.values()).flatten().map(|o| u64::from(o.qty)).sum()
    }

    /// Submit a good-till-cancelled limit order; it trades against better or equal prices first.
    pub fn submit(&mut self, buy: bool, price: i64, qty: u32) -> Receipt {
        let id = self.next_id;
        self.next_id += 1;
        let mut remaining = qty;
        let mut trades = Vec::new();
        let opposite = if buy { &mut self.asks } else { &mut self.bids };
        while remaining > 0 {
            let best = if buy { opposite.keys().next().copied() } else { opposite.keys().next_back().copied() };
            let Some(level_price) = best else { break };
            let acceptable = if buy { level_price <= price } else { level_price >= price };
            if !acceptable {
                break;
            }
            let queue = opposite.get_mut(&level_price).unwrap();
            while remaining > 0 {
                let Some(front) = queue.front_mut() else { break };
                let fill = remaining.min(front.qty);
                trades.push(Trade { taker: id, maker: front.id, price: level_price, qty: fill });
                front.qty -= fill;
                remaining -= fill;
                if front.qty == 0 {
                    self.index.remove(&front.id);
                    queue.pop_front();
                }
            }
            if queue.is_empty() {
                opposite.remove(&level_price);
            }
        }
        if remaining > 0 {
            let levels = if buy { &mut self.bids } else { &mut self.asks };
            levels.entry(price).or_default().push_back(Resting { id, qty: remaining });
            self.index.insert(id, (buy, price));
        }
        Receipt { id, trades, rested: remaining }
    }

    /// (is_bid, price, total quantity) for every level, bids first, each side in price order.
    pub fn snapshot(&self) -> Vec<(bool, i64, u32)> {
        let side = |levels: &Levels, is_bid: bool| -> Vec<(bool, i64, u32)> {
            levels.iter().map(|(price, queue)| (is_bid, *price, queue.iter().map(|o| o.qty).sum())).collect()
        };
        let mut out = side(&self.bids, true);
        out.extend(side(&self.asks, false));
        out
    }

    /// Cancel a resting order and return the quantity removed.
    pub fn cancel(&mut self, id: u64) -> Option<u32> {
        let (buy, price) = self.index.remove(&id)?;
        let levels = if buy { &mut self.bids } else { &mut self.asks };
        let queue = levels.get_mut(&price)?;
        let position = queue.iter().position(|o| o.id == id)?;
        let removed = queue.remove(position)?.qty;
        if queue.is_empty() {
            levels.remove(&price);
        }
        Some(removed)
    }
}

