//! Parser -> book -> strategy -> risk -> gateway, joined by bounded preallocated rings.

use std::collections::VecDeque;

pub const INBOUND_FRAME: usize = 10; // 'U' side:u8 price:u32 qty:u32 (big-endian)
pub const OUTBOUND_FRAME: usize = 18; // 'O' side:u8 price:u32 qty:u32 id:u64 (big-endian)
const PRICES: usize = 1024;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Side {
    Bid,
    Ask,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Update {
    pub side: Side,
    pub price: u32,
    pub qty: u32,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Intent {
    pub side: Side,
    pub price: u32,
    pub qty: u32,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Order {
    pub id: u64,
    pub side: Side,
    pub price: u32,
    pub qty: u32,
}

#[derive(Debug, PartialEq, Eq)]
pub enum PipelineError {
    BadType(u8),
    BadSide(u8),
    PriceOutOfRange(u32),
    TruncatedFrame,
}

/// Fixed-capacity FIFO; capacity is reserved once and the ring never grows.
pub struct Ring<T> {
    items: VecDeque<T>,
    capacity: usize,
}

impl<T> Ring<T> {
    pub fn with_capacity(capacity: usize) -> Self {
        Ring { items: VecDeque::with_capacity(capacity), capacity }
    }

    pub fn push(&mut self, item: T) -> Result<(), T> {
        if self.items.len() == self.capacity {
            return Err(item);
        }
        self.items.push_back(item);
        Ok(())
    }

    pub fn pop(&mut self) -> Option<T> {
        self.items.pop_front()
    }

    pub fn free(&self) -> usize {
        self.capacity - self.items.len()
    }

    /// Slots actually reserved by the allocator; must not change while running.
    pub fn reserved(&self) -> usize {
        self.items.capacity()
    }
}

/// Dense quantity-by-price book with absolute level updates (quantity 0 removes the level).
struct Book {
    bids: Vec<u32>,
    asks: Vec<u32>,
}

impl Book {
    fn set(&mut self, side: Side, price: u32, qty: u32) -> Result<(), PipelineError> {
        let slot = self.slot(side, price)?;
        *slot = qty;
        Ok(())
    }

    fn slot(&mut self, side: Side, price: u32) -> Result<&mut u32, PipelineError> {
        let levels = if side == Side::Bid { &mut self.bids } else { &mut self.asks };
        levels.get_mut(price as usize).ok_or(PipelineError::PriceOutOfRange(price))
    }

    fn best_bid(&self) -> Option<u32> {
        self.bids.iter().rposition(|&q| q > 0).map(|p| p as u32)
    }

    fn best_ask(&self) -> Option<u32> {
        self.asks.iter().position(|&q| q > 0).map(|p| p as u32)
    }
}

/// Quote one tick inside a wide market: improve the bid and the ask when the spread is 3+ ticks.
fn decide(bid: Option<u32>, ask: Option<u32>) -> [Option<Intent>; 2] {
    match (bid, ask) {
        (Some(bid), Some(ask)) if ask >= bid + 3 => [
            Some(Intent { side: Side::Bid, price: bid + 1, qty: 10 }),
            Some(Intent { side: Side::Ask, price: ask - 1, qty: 10 }),
        ],
        _ => [None, None],
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Reason {
    ZeroPrice = 0,
    QtyTooLarge = 1,
    ExposureLimit = 2,
}

struct Risk {
    max_qty: u32,
    max_exposure: u32,
    exposure: u32,
}

impl Risk {
    fn check(&mut self, intent: &Intent) -> Result<(), Reason> {
        if intent.price == 0 {
            return Err(Reason::ZeroPrice);
        }
        if intent.qty > self.max_qty {
            return Err(Reason::QtyTooLarge);
        }
        if self.exposure + intent.qty > self.max_exposure {
            return Err(Reason::ExposureLimit);
        }
        self.exposure += intent.qty;
        Ok(())
    }
}

pub struct Pipeline {
    updates: Ring<Update>,
    intents: Ring<Intent>,
    orders: Ring<Order>,
    book: Book,
    risk: Risk,
    outbound: Vec<u8>,
    next_id: u64,
    pub applied: usize,
    pub intents_generated: usize,
    pub approved: usize,
    pub rejected: [usize; 3],
}

impl Pipeline {
    pub fn new(ring_capacity: usize) -> Self {
        assert!(ring_capacity >= 2, "the intent ring must hold the two quotes one update can produce");
        Pipeline {
            updates: Ring::with_capacity(ring_capacity),
            intents: Ring::with_capacity(ring_capacity),
            orders: Ring::with_capacity(ring_capacity),
            book: Book { bids: vec![0; PRICES], asks: vec![0; PRICES] },
            risk: Risk { max_qty: 10, max_exposure: 25, exposure: 0 },
            outbound: Vec::with_capacity(1 << 16),
            next_id: 1,
            applied: 0,
            intents_generated: 0,
            approved: 0,
            rejected: [0; 3],
        }
    }

    /// Reserved slots of the three rings, for checking that nothing grows at run time.
    pub fn reserved(&self) -> [usize; 3] {
        [self.updates.reserved(), self.intents.reserved(), self.orders.reserved()]
    }

    pub fn outbound(&self) -> &[u8] {
        &self.outbound
    }

    pub fn best_prices(&self) -> (Option<u32>, Option<u32>) {
        (self.book.best_bid(), self.book.best_ask())
    }

    pub fn exposure(&self) -> u32 {
        self.risk.exposure
    }

    /// Consume whole inbound frames from `bytes`; returns bytes consumed so the caller keeps any partial tail.
    pub fn process(&mut self, bytes: &[u8]) -> Result<usize, PipelineError> {
        let mut offset = 0;
        while let Some(frame) = bytes.get(offset..offset + INBOUND_FRAME) {
            if frame[0] != b'U' {
                return Err(PipelineError::BadType(frame[0]));
            }
            let side = match frame[1] {
                b'B' => Side::Bid,
                b'S' => Side::Ask,
                other => return Err(PipelineError::BadSide(other)),
            };
            let update = Update {
                side,
                price: u32::from_be_bytes(frame[2..6].try_into().unwrap()),
                qty: u32::from_be_bytes(frame[6..10].try_into().unwrap()),
            };
            if self.updates.free() == 0 {
                self.pump()?;
            }
            self.updates.push(update).expect("pump made room");
            offset += INBOUND_FRAME;
        }
        self.pump()?;
        Ok(offset)
    }

    /// Run the stages back to front until nothing can move; a stage only runs if its output has room.
    fn pump(&mut self) -> Result<(), PipelineError> {
        loop {
            let mut progressed = false;
            if let Some(order) = self.orders.pop() {
                self.outbound.push(b'O');
                self.outbound.push(if order.side == Side::Bid { b'B' } else { b'S' });
                self.outbound.extend_from_slice(&order.price.to_be_bytes());
                self.outbound.extend_from_slice(&order.qty.to_be_bytes());
                self.outbound.extend_from_slice(&order.id.to_be_bytes());
                progressed = true;
            }
            if self.orders.free() >= 1 {
                if let Some(intent) = self.intents.pop() {
                    match self.risk.check(&intent) {
                        Ok(()) => {
                            let order = Order { id: self.next_id, side: intent.side, price: intent.price, qty: intent.qty };
                            self.next_id += 1;
                            self.orders.push(order).expect("space checked");
                            self.approved += 1;
                        }
                        Err(reason) => self.rejected[reason as usize] += 1,
                    }
                    progressed = true;
                }
            }
            if self.intents.free() >= 2 {
                if let Some(update) = self.updates.pop() {
                    self.book.set(update.side, update.price, update.qty)?;
                    for intent in decide(self.book.best_bid(), self.book.best_ask()).into_iter().flatten() {
                        self.intents.push(intent).expect("space checked");
                        self.intents_generated += 1;
                    }
                    self.applied += 1;
                    progressed = true;
                }
            }
            if !progressed {
                return Ok(());
            }
        }
    }
}

/// Decode the gateway's outbound bytes back into orders (the inverse of the encoding in `pump`).
pub fn decode_orders(bytes: &[u8]) -> Result<Vec<Order>, PipelineError> {
    bytes
        .chunks(OUTBOUND_FRAME)
        .map(|f| {
            if f.len() != OUTBOUND_FRAME {
                return Err(PipelineError::TruncatedFrame);
            }
            if f[0] != b'O' {
                return Err(PipelineError::BadType(f[0]));
            }
            let side = match f[1] {
                b'B' => Side::Bid,
                b'S' => Side::Ask,
                other => return Err(PipelineError::BadSide(other)),
            };
            Ok(Order {
                side,
                price: u32::from_be_bytes(f[2..6].try_into().unwrap()),
                qty: u32::from_be_bytes(f[6..10].try_into().unwrap()),
                id: u64::from_be_bytes(f[10..18].try_into().unwrap()),
            })
        })
        .collect()
}

use pipeline_lab::{INBOUND_FRAME, OUTBOUND_FRAME, Pipeline, PipelineError, decode_orders};

fn frame(side: u8, price: u32, qty: u32) -> Vec<u8> {
