struct Rng(u64);

impl Rng {
    fn next(&mut self) -> u64 {
        self.0 ^= self.0 << 13;
        self.0 ^= self.0 >> 7;
        self.0 ^= self.0 << 17;
        self.0
    }

    fn range(&mut self, low: i64, high: i64) -> i64 {
        low + (self.next() % (high - low + 1) as u64) as i64
    }
}

fn max_profit_brute(prices: &[i64]) -> i128 {
    let mut best = 0;
    for i in 0..prices.len() {
        for j in i + 1..prices.len() {
            best = best.max(i128::from(prices[j]) - i128::from(prices[i]));
        }
    }
    best
}

/// (profit, buy index, sell index); None when no profitable trade exists.
fn best_trade(prices: &[i64]) -> Option<(i128, usize, usize)> {
    let mut min_index = 0;
    let mut best: Option<(i128, usize, usize)> = None;
    for (j, &price) in prices.iter().enumerate() {
        let profit = i128::from(price) - i128::from(prices[min_index]);
        if profit > 0 && best.is_none_or(|(b, _, _)| profit > b) {
            best = Some((profit, min_index, j));
        }
        if price < prices[min_index] {
            min_index = j;
        }
    }
    best
}

fn max_profit(prices: &[i64]) -> i128 {
    best_trade(prices).map_or(0, |(profit, _, _)| profit)
}

fn max_drawdown(prices: &[i64]) -> i128 {
    let mut peak = i128::MIN;
    let mut worst = 0;
    for &price in prices {
        let price = i128::from(price);
        peak = peak.max(price);
        worst = worst.max(peak - price);
    }
    worst
}

