/// (best sum, start index, end index inclusive); None for an empty slice.
fn max_subarray(values: &[i64]) -> Option<(i128, usize, usize)> {
    let first = *values.first()?;
    let (mut best, mut best_range) = (i128::from(first), (0, 0));
    let (mut current, mut start) = (i128::from(first), 0);
    for (i, &v) in values.iter().enumerate().skip(1) {
        let v = i128::from(v);
        if current + v < v {
            current = v;
            start = i;
        } else {
            current += v;
        }
        if current > best {
            best = current;
            best_range = (start, i);
        }
    }
    Some((best, best_range.0, best_range.1))
}

fn max_subarray_brute(values: &[i64]) -> Option<i128> {
    let mut best: Option<i128> = None;
    for i in 0..values.len() {
        let mut sum = 0i128;
        for &v in &values[i..] {
            sum += i128::from(v);
            best = Some(best.map_or(sum, |b| b.max(sum)));
        }
    }
    best
}

fn main() {
    let pnl = [-2, 1, -3, 4, -1, 2, 1, -5, 4];
    let (sum, start, end) = max_subarray(&pnl).unwrap();
    println!("best stretch of {pnl:?} is [{start}..={end}] = {:?} with sum {sum}", &pnl[start..=end]);
    println!("all negative: {:?}", max_subarray(&[-5, -2, -9]));
    println!("empty: {:?}, single: {:?}", max_subarray(&[]), max_subarray(&[7]));
    let worst = max_subarray(&pnl.map(|x| -x)).unwrap();
    println!("worst stretch: [{}..={}] with sum {}", worst.1, worst.2, -worst.0);

    let mut rng = Rng(0xBEEF);
    for _ in 0..2000 {
        let n = rng.range(0, 30) as usize;
        let values: Vec<i64> = (0..n).map(|_| rng.range(-10, 10)).collect();
        assert_eq!(max_subarray(&values).map(|r| r.0), max_subarray_brute(&values));
        if let Some((sum, s, e)) = max_subarray(&values) {
            assert_eq!(values[s..=e].iter().map(|&v| i128::from(v)).sum::<i128>(), sum);
        }
    }
    println!("matches brute force and the reported range sums correctly on 2000 random arrays: true");
}

