use std::cmp::Reverse;
use std::collections::BinaryHeap;

#[derive(Default)]
struct RunningMedian {
    low: BinaryHeap<i64>,           // smaller half, max-heap
    high: BinaryHeap<Reverse<i64>>, // larger half, min-heap
}

impl RunningMedian {
    fn push(&mut self, value: i64) {
        self.low.push(value);
        let moved = self.low.pop().unwrap();
        self.high.push(Reverse(moved));
        if self.high.len() > self.low.len() {
            let Reverse(back) = self.high.pop().unwrap();
            self.low.push(back);
        }
        debug_assert!(self.invariants_hold());
    }

    /// Twice the median, so even-sized streams stay exact integers.
    fn median_x2(&self) -> Option<i128> {
        let low_top = i128::from(*self.low.peek()?);
        Some(match self.high.peek() {
            Some(Reverse(high_top)) if self.low.len() == self.high.len() => low_top + i128::from(*high_top),
            _ => 2 * low_top,
        })
    }

    fn invariants_hold(&self) -> bool {
        let sizes_ok = self.low.len() == self.high.len() || self.low.len() == self.high.len() + 1;
        let order_ok = match (self.low.peek(), self.high.peek()) {
            (Some(l), Some(Reverse(h))) => l <= h,
            _ => true,
        };
        sizes_ok && order_ok
    }
}

fn median_x2_of_sorted(sorted: &[i64]) -> i128 {
    let n = sorted.len();
    if n % 2 == 1 {
        2 * i128::from(sorted[n / 2])
    } else {
        i128::from(sorted[n / 2 - 1]) + i128::from(sorted[n / 2])
    }
}

fn main() {
    let mut m = RunningMedian::default();
    println!("empty: {:?}", m.median_x2());
    for v in [5, 15, 1, 3, 8, 7, 9, 10, 20, 2] {
        m.push(v);
        let x2 = m.median_x2().unwrap();
        println!("after {v:>2}: median = {}{}", x2 / 2, if x2 % 2 != 0 { ".5" } else { "" });
    }

    let mut rng = Rng(0xFACE);
    let mut m = RunningMedian::default();
    let mut seen = Vec::new();
    for _ in 0..1500 {
        let v = rng.range(-1000, 1000);
        m.push(v);
        seen.push(v);
        let mut sorted = seen.clone();
        sorted.sort_unstable();
        assert_eq!(m.median_x2().unwrap(), median_x2_of_sorted(&sorted));
        assert!(m.invariants_hold());
    }
    println!("matches sorting the whole prefix after every one of 1500 inserts: true");
}

