use std::collections::BinaryHeap;

struct KthSmallest {
    k: usize,
    heap: BinaryHeap<i64>,
}

impl KthSmallest {
    fn new(k: usize) -> Self {
        assert!(k >= 1);
        KthSmallest { k, heap: BinaryHeap::with_capacity(k + 1) }
    }

    fn push(&mut self, value: i64) -> Option<i64> {
        self.heap.push(value);
        if self.heap.len() > self.k {
            self.heap.pop();
        }
        (self.heap.len() == self.k).then(|| *self.heap.peek().unwrap())
    }
}

fn main() {
    let mut rng = Rng(99);
    for k in [1, 2, 5, 17] {
        let mut tracker = KthSmallest::new(k);
        let mut seen = Vec::new();
        for _ in 0..400 {
            let v = rng.range(-50, 50);
            seen.push(v);
            let mut sorted = seen.clone();
            sorted.sort_unstable();
            let expected = (seen.len() >= k).then(|| sorted[k - 1]);
            assert_eq!(tracker.push(v), expected);
        }
    }
    let mut third = KthSmallest::new(3);
    let answers: Vec<_> = [9, 4, 7, 1, 8].iter().map(|&v| third.push(v)).collect();
    println!("3rd smallest after each of [9, 4, 7, 1, 8]: {answers:?}");
