use std::collections::HashMap;
use std::hash::Hash;

const NONE: usize = usize::MAX;

struct Node<K, V> {
    key: K,
    value: V,
    prev: usize,
    next: usize,
}

/// O(1) get and put: a HashMap to find the node, a doubly linked list (indices into a Vec) for recency.
struct Lru<K, V> {
    map: HashMap<K, usize>,
    nodes: Vec<Node<K, V>>,
    head: usize, // most recently used
    tail: usize, // least recently used
    capacity: usize,
}

impl<K: Hash + Eq + Clone, V> Lru<K, V> {
    fn new(capacity: usize) -> Self {
        assert!(capacity > 0);
        Lru { map: HashMap::with_capacity(capacity), nodes: Vec::with_capacity(capacity), head: NONE, tail: NONE, capacity }
    }

    fn len(&self) -> usize {
        self.map.len()
    }

    fn unlink(&mut self, i: usize) {
        let (prev, next) = (self.nodes[i].prev, self.nodes[i].next);
        if prev != NONE { self.nodes[prev].next = next } else { self.head = next }
        if next != NONE { self.nodes[next].prev = prev } else { self.tail = prev }
    }

    fn push_front(&mut self, i: usize) {
        self.nodes[i].prev = NONE;
        self.nodes[i].next = self.head;
        if self.head != NONE {
            self.nodes[self.head].prev = i;
        }
        self.head = i;
        if self.tail == NONE {
            self.tail = i;
        }
    }

    fn get(&mut self, key: &K) -> Option<&V> {
        let i = *self.map.get(key)?;
        self.unlink(i);
        self.push_front(i);
        Some(&self.nodes[i].value)
    }

    /// Insert or update; returns the entry evicted to make room, if any.
    fn put(&mut self, key: K, value: V) -> Option<(K, V)> {
        if let Some(&i) = self.map.get(&key) {
            self.nodes[i].value = value;
            self.unlink(i);
            self.push_front(i);
            return None;
        }
        if self.map.len() == self.capacity {
            let slot = self.tail;
            self.unlink(slot);
            self.map.remove(&self.nodes[slot].key);
            let old = std::mem::replace(&mut self.nodes[slot], Node { key: key.clone(), value, prev: NONE, next: NONE });
            self.map.insert(key, slot);
            self.push_front(slot);
            return Some((old.key, old.value));
        }
        let slot = self.nodes.len();
        self.nodes.push(Node { key: key.clone(), value, prev: NONE, next: NONE });
        self.map.insert(key, slot);
        self.push_front(slot);
        None
    }

    fn keys_most_recent_first(&self) -> Vec<&K> {
        let mut out = Vec::with_capacity(self.map.len());
        let mut i = self.head;
        while i != NONE {
            out.push(&self.nodes[i].key);
            i = self.nodes[i].next;
        }
        out
    }
}

/// Slow but obviously correct model: a Vec ordered most recent first.
struct Model {
    entries: Vec<(u32, u32)>,
    capacity: usize,
}

impl Model {
    fn get(&mut self, key: u32) -> Option<u32> {
        let position = self.entries.iter().position(|e| e.0 == key)?;
        let entry = self.entries.remove(position);
        self.entries.insert(0, entry);
        Some(entry.1)
    }

    fn put(&mut self, key: u32, value: u32) -> Option<(u32, u32)> {
        if let Some(position) = self.entries.iter().position(|e| e.0 == key) {
            self.entries.remove(position);
            self.entries.insert(0, (key, value));
            return None;
        }
        self.entries.insert(0, (key, value));
        if self.entries.len() > self.capacity { self.entries.pop() } else { None }
    }
}

fn main() {
    let mut cache = Lru::new(2);
    cache.put("a", 1);
    cache.put("b", 2);
    println!("get a -> {:?}", cache.get(&"a"));
    println!("put c evicts {:?}", cache.put("c", 3));
    println!("get b -> {:?}", cache.get(&"b"));
    println!("order (most recent first): {:?}", cache.keys_most_recent_first());
    println!("update a keeps size: {:?}, len {}", cache.put("a", 10), cache.len());

    let mut one = Lru::new(1);
    one.put(1, "x");
    println!("capacity 1: put 2 evicts {:?}", one.put(2, "y"));

    let mut state = 0x1234_5678_9ABC_DEF1u64;
    let mut next = move || {
        state ^= state << 13;
        state ^= state >> 7;
        state ^= state << 17;
        state
    };
    for capacity in [1, 4, 7] {
        let mut real = Lru::new(capacity);
        let mut model = Model { entries: Vec::new(), capacity };
        for step in 0..5000u32 {
            let key = (next() % 8) as u32;
            if next() % 2 == 0 {
                assert_eq!(real.get(&key).copied(), model.get(key), "get {key} at step {step}");
            } else {
                assert_eq!(real.put(key, step), model.put(key, step), "put {key} at step {step}");
            }
            let real_order: Vec<u32> = real.keys_most_recent_first().into_iter().copied().collect();
            let model_order: Vec<u32> = model.entries.iter().map(|e| e.0).collect();
            assert_eq!(real_order, model_order);
        }
    }
    println!("matches the O(n) model for capacities 1, 4 and 7 over 5000 random steps: true");
}

