use std::collections::VecDeque;

/// `dominated(old, new)` is true when `old` can never again be the extreme once `new` has arrived.
fn window_extreme(values: &[i64], k: usize, dominated: impl Fn(i64, i64) -> bool) -> Vec<i64> {
    assert!(k >= 1, "window size must be at least 1");
    let mut deque: VecDeque<usize> = VecDeque::new();
    let mut out = Vec::with_capacity(values.len().saturating_sub(k - 1));
    for (i, &value) in values.iter().enumerate() {
        while deque.back().is_some_and(|&b| dominated(values[b], value)) {
            deque.pop_back();
        }
        deque.push_back(i);
        if deque.front().is_some_and(|&f| f + k <= i) {
            deque.pop_front();
        }
        if i + 1 >= k {
            out.push(values[*deque.front().unwrap()]);
        }
    }
    out
}

fn window_max(values: &[i64], k: usize) -> Vec<i64> {
    window_extreme(values, k, |old, new| old <= new)
}

