use std::collections::VecDeque;

fn window_max_counted(values: &[i64], k: usize) -> (Vec<i64>, usize) {
    let mut deque: VecDeque<usize> = VecDeque::new();
    let mut out = Vec::new();
    let mut operations = 0;
    for (i, &value) in values.iter().enumerate() {
        while deque.back().is_some_and(|&b| values[b] <= value) {
            deque.pop_back();
            operations += 1;
        }
        deque.push_back(i);
        operations += 1;
        if deque.front().is_some_and(|&f| f + k <= i) {
            deque.pop_front();
            operations += 1;
        }
        if i + 1 >= k {
            out.push(values[*deque.front().unwrap()]);
        }
    }
    (out, operations)
}

fn main() {
    let n = 1000;
    let decreasing: Vec<i64> = (0..n as i64).rev().collect();
    let increasing: Vec<i64> = (0..n as i64).collect();
    let (_, dec_ops) = window_max_counted(&decreasing, 50);
    let (_, inc_ops) = window_max_counted(&increasing, 50);
    assert!(dec_ops <= 3 * n && inc_ops <= 3 * n);
    println!("decreasing: {dec_ops} operations, increasing: {inc_ops} operations for n = {n}");
    let mut rng = Rng(5);
