use std::cmp::{Ordering, Reverse};
use std::collections::BinaryHeap;

#[derive(Clone, Copy, Debug, PartialEq)]
struct Scored {
    score: f64,
    index: usize,
}

impl Eq for Scored {}

impl PartialOrd for Scored {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for Scored {
    /// "Greater" means better: higher score first; for equal scores the earlier index wins.
    fn cmp(&self, other: &Self) -> Ordering {
        self.score.total_cmp(&other.score).then_with(|| other.index.cmp(&self.index))
    }
}

/// Indices of the k best scores, best first, and how many NaN scores were skipped.
fn top_k(scores: &[f64], k: usize) -> (Vec<usize>, usize) {
    let mut heap: BinaryHeap<Reverse<Scored>> = BinaryHeap::with_capacity(k + 1);
    let mut skipped = 0;
    for (index, &score) in scores.iter().enumerate() {
        if score.is_nan() {
            skipped += 1;
            continue;
        }
        let item = Scored { score, index };
        if heap.len() < k {
            heap.push(Reverse(item));
        } else if let Some(Reverse(worst)) = heap.peek() {
            if item > *worst {
                heap.pop();
                heap.push(Reverse(item));
            }
        }
    }
    let mut best: Vec<Scored> = heap.into_iter().map(|Reverse(s)| s).collect();
    best.sort_by(|a, b| b.cmp(a));
    (best.into_iter().map(|s| s.index).collect(), skipped)
}

fn top_k_brute(scores: &[f64], k: usize) -> Vec<usize> {
    let mut all: Vec<Scored> = scores.iter().enumerate().filter(|(_, s)| !s.is_nan()).map(|(index, &score)| Scored { score, index }).collect();
    all.sort_by(|a, b| b.cmp(a));
    all.into_iter().take(k).map(|s| s.index).collect()
}

fn main() {
    let scores = [0.5, 2.0, 2.0, f64::NAN, -1.0, 2.0, 1.5];
    println!("top 3: {:?}", top_k(&scores, 3));
    println!("top 0: {:?}", top_k(&scores, 0));
    println!("top 10 (more than exist): {:?}", top_k(&scores, 10));
    println!("ties keep the earliest index: {:?}", top_k(&[1.0, 1.0, 1.0, 1.0], 2));
    println!("infinity beats everything, NaN never ranks: {:?}", top_k(&[1.0, f64::INFINITY, f64::NAN], 2));

    let mut rng = Rng(0xA11CE);
    for _ in 0..3000 {
        let n = rng.range(0, 30) as usize;
        let k = rng.range(0, 8) as usize;
        let scores: Vec<f64> = (0..n).map(|_| if rng.range(0, 9) == 0 { f64::NAN } else { rng.range(0, 6) as f64 }).collect();
        let (fast, skipped) = top_k(&scores, k);
        assert_eq!(fast, top_k_brute(&scores, k));
        assert_eq!(skipped, scores.iter().filter(|s| s.is_nan()).count());
    }
    println!("matches the sort-everything oracle on 3000 random inputs with ties and NaN: true");
}

