fn top_k_per_group(items: &[(&str, i64)], k: usize) -> BTreeMap<String, Vec<i64>> {
    let mut heaps: BTreeMap<String, BinaryHeap<Reverse<i64>>> = BTreeMap::new();
    for &(group, score) in items {
