type Interval = (i64, i64); // half-open [start, end)

fn merge(mut intervals: Vec<Interval>) -> Vec<Interval> {
    intervals.retain(|&(start, end)| start < end);
    intervals.sort_unstable();
    let mut merged: Vec<Interval> = Vec::with_capacity(intervals.len());
    for (start, end) in intervals {
        match merged.last_mut() {
            Some(last) if start <= last.1 => last.1 = last.1.max(end),
            _ => merged.push((start, end)),
        }
    }
    merged
}

fn covered(merged: &[Interval]) -> i64 {
    merged.iter().map(|(s, e)| e - s).sum()
}

/// Uncovered stretches inside [lo, hi), given merged disjoint intervals.
fn gaps(merged: &[Interval], lo: i64, hi: i64) -> Vec<Interval> {
    let mut out = Vec::new();
    let mut cursor = lo;
    for &(start, end) in merged {
        if end <= lo || start >= hi {
            continue;
        }
        if start > cursor {
            out.push((cursor, start));
        }
        cursor = cursor.max(end);
    }
    if cursor < hi {
        out.push((cursor, hi));
    }
    out
}

/// Oracle: mark unit cells on a bitmap and read off the maximal runs.
fn merge_bitmap(intervals: &[Interval], size: usize) -> Vec<Interval> {
    let mut cells = vec![false; size];
    for &(s, e) in intervals {
        for cell in cells.iter_mut().take(e.max(0) as usize).skip(s.max(0) as usize) {
            *cell = true;
        }
    }
    let mut out = Vec::new();
    let mut i = 0;
    while i < size {
        if cells[i] {
            let start = i;
            while i < size && cells[i] {
                i += 1;
            }
            out.push((start as i64, i as i64));
        } else {
            i += 1;
        }
    }
    out
}

fn main() {
    let sessions = vec![(8, 10), (1, 3), (2, 6), (15, 18), (9, 12)];
    let merged = merge(sessions);
    println!("merged = {merged:?}, covered = {}", covered(&merged));
    println!("gaps in [0, 20) = {:?}", gaps(&merged, 0, 20));
    println!("touching merges: {:?}", merge(vec![(1, 4), (4, 5)]));
    println!("nested keeps the longer end: {:?}", merge(vec![(1, 10), (2, 3)]));
    println!("empty and reversed intervals are dropped: {:?}", merge(vec![(5, 5), (7, 3), (1, 2)]));
    println!("no intervals: gaps = {:?}", gaps(&[], 0, 5));

    let mut rng = Rng(0x1234);
    for _ in 0..3000 {
        let n = rng.range(0, 8) as usize;
        let intervals: Vec<Interval> = (0..n).map(|_| (rng.range(0, 30), rng.range(0, 30))).collect();
