fn prim(n: usize, weight: &[Vec<i64>]) -> i64 {
    let mut in_tree = vec![false; n];
    let mut best = vec![i64::MAX; n];
    best[0] = 0;
    let mut total = 0;
    for _ in 0..n {
        let next = (0..n).filter(|&v| !in_tree[v]).min_by_key(|&v| best[v]).unwrap();
        in_tree[next] = true;
        total += best[next];
        for v in 0..n {
            if !in_tree[v] && weight[next][v] < best[v] {
                best[v] = weight[next][v];
            }
        }
    }
    total
}

