    }
}

impl Trie {
    fn longest_common_prefix(&self) -> String {
        let mut at = 0;
        let mut prefix = Vec::new();
        while self.nodes[at].children.len() == 1 && !self.nodes[at].terminal {
            let (&byte, &next) = self.nodes[at].children.iter().next().unwrap();
            prefix.push(byte);
            at = next;
        }
        String::from_utf8(prefix).unwrap()
    }
}

fn common_prefix(words: &[String]) -> String {
    let Some(first) = words.first() else { return String::new() };
    let mut length = first.len();
    for word in words {
        length = length.min(first.bytes().zip(word.bytes()).take_while(|(a, b)| a == b).count());
    }
    first[..length].to_string()
}

fn main() {
    let mut trie = Trie::new();
    for w in ["interview", "internet", "interval"] {
        trie.insert(w).unwrap();
    }
    println!("longest common prefix = {:?}", trie.longest_common_prefix());
    let mut rng = Rng(31);
    for _ in 0..1500 {
        let mut trie = Trie::new();
        let mut words = Vec::new();
        for _ in 0..rng.range(0, 6) {
            let word: String = (0..rng.range(1, 6)).map(|_| (b'A' + rng.range(0, 1) as u8) as char).collect();
            if trie.insert(&word).unwrap() {
                words.push(word);
            }
        }
        assert_eq!(trie.longest_common_prefix(), common_prefix(&words));
    }
}

