fn gray(n: u32) -> u32 {
    n ^ (n >> 1)
}

fn gray_inverse(g: u32) -> u32 {
    let mut n = g;
    let mut shift = 1;
    while shift < 32 {
        n ^= n >> shift;
        shift <<= 1;
    }
    n
}

fn main() {
    for n in 0..4096u32 {
        assert_eq!(gray_inverse(gray(n)), n);
        if n > 0 {
            assert_eq!((gray(n) ^ gray(n - 1)).count_ones(), 1, "n = {n}");
        }
    }
    assert_eq!(gray_inverse(gray(u32::MAX)), u32::MAX);
    println!("gray codes of 0..8: {:?}", (0..8).map(|n| format!("{:03b}", gray(n))).collect::<Vec<_>>());
}

