struct Rng(u64);

impl Rng {
    fn next(&mut self) -> u64 {
        self.0 ^= self.0 << 13;
        self.0 ^= self.0 >> 7;
        self.0 ^= self.0 << 17;
        self.0
    }

    fn range(&mut self, low: i64, high: i64) -> i64 {
        low + (self.next() % (high - low + 1) as u64) as i64
    }
}
fn median_of_three(a: i64, b: i64, c: i64) -> i64 {
    a.max(b).min(a.min(b).max(c))
}

/// Classic Lomuto partition with median-of-three: simple, but quadratic when many values are equal.
fn quickselect_lomuto(values: &mut [i64], k: usize, comparisons: &mut usize) -> i64 {
    let (mut lo, mut hi) = (0usize, values.len() - 1);
    loop {
        if lo == hi {
            return values[lo];
        }
        let mid = lo + (hi - lo) / 2;
        let pivot_value = median_of_three(values[lo], values[mid], values[hi]);
        let pivot_at = (lo..=hi).find(|&i| values[i] == pivot_value).unwrap();
        values.swap(pivot_at, hi);
        let mut store = lo;
        for i in lo..hi {
            *comparisons += 1;
            if values[i] < pivot_value {
                values.swap(i, store);
                store += 1;
            }
        }
        values.swap(store, hi);
        match k.cmp(&store) {
            std::cmp::Ordering::Equal => return values[store],
            std::cmp::Ordering::Less => hi = store - 1,
            std::cmp::Ordering::Greater => lo = store + 1,
        }
    }
}

/// Three-way (Dutch national flag) partition: the block equal to the pivot is finished in one pass.
fn quickselect_three_way(values: &mut [i64], k: usize, comparisons: &mut usize) -> i64 {
    let (mut lo, mut hi) = (0usize, values.len()); // half-open [lo, hi)
    loop {
        if hi - lo == 1 {
            return values[lo];
        }
        let pivot = median_of_three(values[lo], values[lo + (hi - lo) / 2], values[hi - 1]);
        let (mut lt, mut i, mut gt) = (lo, lo, hi);
        while i < gt {
            *comparisons += 1;
            if values[i] < pivot {
                values.swap(lt, i);
                lt += 1;
                i += 1;
            } else if values[i] > pivot {
                gt -= 1;
                values.swap(i, gt);
            } else {
                i += 1;
            }
        }
        if k < lt {
            hi = lt;
        } else if k >= gt {
            lo = gt;
        } else {
            return pivot;
        }
    }
}

/// Nearest-rank percentile; `per_10000` of 5000 is the median. Uses the standard library's introselect.
fn percentile(values: &mut [i64], per_10000: u64) -> Option<i64> {
    if values.is_empty() {
        return None;
    }
    let rank = (values.len() as u64 * per_10000).div_ceil(10_000).max(1) as usize;
    let (_, nth, _) = values.select_nth_unstable(rank - 1);
    Some(*nth)
}

fn main() {
    let data = [9, 1, 8, 2, 7, 3, 6, 4, 5];
    let (mut c1, mut c2) = (0, 0);
    println!("median of {data:?}: lomuto {}, three-way {}", quickselect_lomuto(&mut data.clone(), 4, &mut c1), quickselect_three_way(&mut data.clone(), 4, &mut c2));
    println!("percentiles of 1..=100: p50 = {:?}, p95 = {:?}, p99 = {:?}", percentile(&mut (1..=100).collect::<Vec<_>>(), 5000), percentile(&mut (1..=100).collect::<Vec<_>>(), 9500), percentile(&mut (1..=100).collect::<Vec<_>>(), 9900));
    println!("percentile of an empty slice: {:?}", percentile(&mut [], 5000));

    let n = 2000;
    let (mut lomuto_equal, mut three_equal) = (0, 0);
    quickselect_lomuto(&mut vec![7; n], n / 2, &mut lomuto_equal);
    quickselect_three_way(&mut vec![7; n], n / 2, &mut three_equal);
    println!("{n} equal values: lomuto {lomuto_equal} comparisons, three-way {three_equal}");
    assert!(lomuto_equal > n * n / 8 && three_equal <= 2 * n);

    let (mut lomuto_sorted, mut three_sorted) = (0, 0);
    let sorted: Vec<i64> = (0..n as i64).collect();
    quickselect_lomuto(&mut sorted.clone(), n / 2, &mut lomuto_sorted);
    quickselect_three_way(&mut sorted.clone(), n / 2, &mut three_sorted);
    println!("{n} sorted values: lomuto {lomuto_sorted} comparisons, three-way {three_sorted} (both linear thanks to median-of-three)");
    assert!(lomuto_sorted <= 4 * n && three_sorted <= 4 * n);

    let mut rng = Rng(0x0DD5);
    for _ in 0..3000 {
        let len = rng.range(1, 40) as usize;
        let values: Vec<i64> = (0..len).map(|_| rng.range(0, 6)).collect();
        let mut sorted = values.clone();
        sorted.sort_unstable();
        let k = rng.range(0, len as i64 - 1) as usize;
        let mut counter = 0;
        assert_eq!(quickselect_lomuto(&mut values.clone(), k, &mut counter), sorted[k]);
        assert_eq!(quickselect_three_way(&mut values.clone(), k, &mut counter), sorted[k]);
        let mut copy = values.clone();
        let (_, nth, _) = copy.select_nth_unstable(k);
        assert_eq!(*nth, sorted[k]);
    }
    println!("both quickselects and select_nth_unstable match a full sort on 3000 duplicate-heavy arrays: true");
}

