use std::fmt;

fn gcd(a: u128, b: u128) -> u128 {
    if b == 0 { a } else { gcd(b, a % b) }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct Frac {
    num: u128,
    den: u128,
}

impl Frac {
    fn new(num: u128, den: u128) -> Frac {
        assert!(den > 0, "zero denominator");
        let g = gcd(num, den).max(1);
        Frac { num: num / g, den: den / g }
    }

    fn as_f64(self) -> f64 {
        self.num as f64 / self.den as f64
    }

    fn complement(self) -> Frac {
        Frac::new(self.den - self.num, self.den)
    }
}

impl fmt::Display for Frac {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        if self.den == 1 { write!(f, "{}", self.num) } else { write!(f, "{}/{}", self.num, self.den) }
    }
}

/// Binomial coefficient; None if any intermediate product overflows u128.
fn choose(n: u64, k: u64) -> Option<u128> {
    if k > n {
        return Some(0);
    }
    let k = k.min(n - k);
    let mut result: u128 = 1;
    for i in 0..k {
        // After step i the value is C(n, i + 1), so the division is always exact.
        result = result.checked_mul(u128::from(n - i))? / u128::from(i + 1);
    }
    Some(result)
}

/// ways[s] = number of ordered outcomes of `dice` six-sided dice that sum to s.
fn dice_ways(dice: usize) -> Vec<u128> {
    let mut ways = vec![0u128; 6 * dice + 1];
    ways[0] = 1;
    for round in 0..dice {
        let mut next = vec![0u128; ways.len()];
        for sum in 0..=6 * round {
            for face in 1..=6 {
                next[sum + face] += ways[sum];
            }
        }
        ways = next;
    }
    ways
}

fn main() {
    let ways = dice_ways(2);
    println!("P(two dice sum to 7) = {}", Frac::new(ways[7], 36));

    let all_rolls: Vec<[u8; 4]> = (0..6u32.pow(4)).map(|n| [(n % 6) as u8, (n / 6 % 6) as u8, (n / 36 % 6) as u8, (n / 216 % 6) as u8]).collect();
    let with_six = all_rolls.iter().filter(|roll| roll.contains(&5)).count() as u128;
    let by_complement = Frac::new(5u128.pow(4), 6u128.pow(4)).complement();
    println!("P(at least one six in 4 rolls) = {by_complement}, enumeration {}/{}", with_six, all_rolls.len());
    assert_eq!(by_complement, Frac::new(with_six, all_rolls.len() as u128));

    let two_aces = Frac::new(choose(4, 2).unwrap() * choose(48, 3).unwrap(), choose(52, 5).unwrap());
    println!("P(exactly two aces in 5 cards) = {two_aces} = {:.4}", two_aces.as_f64());
    println!("C(52, 5) = {}", choose(52, 5).unwrap());

    let three = dice_ways(3);
    let at_least_15: u128 = three[15..].iter().sum();
    println!("P(three dice sum >= 15) = {}", Frac::new(at_least_15, 216));

    let max_of_two: u128 = (1..=6u128).flat_map(|a| (1..=6u128).map(move |b| a.max(b))).sum();
    println!("E[max of two dice] = {}", Frac::new(max_of_two, 36));

    let families = [("B", "B"), ("B", "G"), ("G", "B"), ("G", "G")];
    let at_least_one_boy = families.iter().filter(|(a, b)| *a == "B" || *b == "B").count() as u128;
    let both_boys = families.iter().filter(|(a, b)| *a == "B" && *b == "B").count() as u128;
    println!("P(both boys | at least one boy) = {}", Frac::new(both_boys, at_least_one_boy));

    println!("choose(200, 100) = {:?}", choose(200, 100));
    println!("choose(5, 9) = {:?}, choose(10, 0) = {:?}", choose(5, 9), choose(10, 0));

    for dice in 1..=5 {
        let ways = dice_ways(dice);
        let mut counts = vec![0u128; 6 * dice + 1];
        for outcome in 0..6u32.pow(dice as u32) {
            let sum: u32 = (0..dice).map(|i| outcome / 6u32.pow(i as u32) % 6 + 1).sum();
            counts[sum as usize] += 1;
        }
        assert_eq!(ways, counts);
    }
    println!("dice DP equals brute-force enumeration for 1 to 5 dice: true");
    println!("total ways for 40 dice = 6^40: {}", dice_ways(40).iter().sum::<u128>() == 6u128.pow(40));
}

lessons.solution:
use std::fmt;

fn gcd(a: u128, b: u128) -> u128 {
    if b == 0 { a } else { gcd(b, a % b) }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct Frac {
    num: u128,
    den: u128,
}

impl Frac {
    fn new(num: u128, den: u128) -> Frac {
        assert!(den > 0, "zero denominator");
        let g = gcd(num, den).max(1);
        Frac { num: num / g, den: den / g }
    }

    fn as_f64(self) -> f64 {
        self.num as f64 / self.den as f64
    }

    fn complement(self) -> Frac {
        Frac::new(self.den - self.num, self.den)
    }
}

impl fmt::Display for Frac {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        if self.den == 1 { write!(f, "{}", self.num) } else { write!(f, "{}/{}", self.num, self.den) }
    }
}

/// Binomial coefficient; None if any intermediate product overflows u128.
fn choose(n: u64, k: u64) -> Option<u128> {
    if k > n {
        return Some(0);
    }
    let k = k.min(n - k);
    let mut result: u128 = 1;
    for i in 0..k {
        // After step i the value is C(n, i + 1), so the division is always exact.
        result = result.checked_mul(u128::from(n - i))? / u128::from(i + 1);
    }
    Some(result)
}

/// ways[s] = number of ordered outcomes of `dice` six-sided dice that sum to s.
fn dice_ways(dice: usize) -> Vec<u128> {
    let mut ways = vec![0u128; 6 * dice + 1];
    ways[0] = 1;
    for round in 0..dice {
        let mut next = vec![0u128; ways.len()];
        for sum in 0..=6 * round {
            for face in 1..=6 {
                next[sum + face] += ways[sum];
            }
        }
        ways = next;
    }
    ways
}

fn main() {
    let exactly_five = Frac::new(choose(10, 5).unwrap(), 1 << 10);
    let at_least_eight: u128 = (8..=10).map(|k| choose(10, k).unwrap()).sum();
    let at_least_eight = Frac::new(at_least_eight, 1 << 10);

    let (mut five, mut eight_plus) = (0u128, 0u128);
    for sequence in 0u32..1024 {
        let heads = sequence.count_ones();
        five += u128::from(heads == 5);
        eight_plus += u128::from(heads >= 8);
    }
    assert_eq!(exactly_five, Frac::new(five, 1024));
    assert_eq!(at_least_eight, Frac::new(eight_plus, 1024));
    println!("P(5 heads in 10) = {exactly_five}, P(at least 8 heads) = {at_least_eight}");
    let _ = (dice_ways(1), exactly_five.as_f64(), exactly_five.complement());
}

