(* 1. is_leap year: divisible by 4, except centuries not divisible by 400. *)
let is_leap y = (y mod 4 = 0 && y mod 100 <> 0) || y mod 400 = 0

(* 2. sum_digits n: the sum of the decimal digits of a non-negative integer. *)
let rec sum_digits n = if n < 10 then n else (n mod 10) + sum_digits (n / 10)

(* 3. gcd by Euclid's algorithm. *)
let rec gcd a b = if b = 0 then a else gcd b (a mod b)

(* 4. power b e in O(log e) multiplications, by repeated squaring. *)
let rec power b e =
  if e = 0 then 1
  else
    let half = power b (e / 2) in
    if e mod 2 = 0 then half * half else half * half * b

(* 5. collatz_length n: how many steps until n reaches 1. *)
let collatz_length n =
  let rec go n steps = if n = 1 then steps else go (if n mod 2 = 0 then n / 2 else (3 * n) + 1) (steps + 1) in
  go n 0

let () =
  Printf.printf "%b %b %b %b\n" (is_leap 1900) (is_leap 2000) (is_leap 2024) (is_leap 2023);
  Printf.printf "%d %d\n" (sum_digits 12345) (sum_digits 0);
  Printf.printf "%d %d\n" (gcd 48 18) (gcd 17 5);
  Printf.printf "%d %d\n" (power 2 10) (power 3 5);
  Printf.printf "%d\n" (collatz_length 27)

(* 1. product and concat as folds. *)
let product = List.fold_left ( * ) 1
let concat ls = List.fold_right ( @ ) ls []

(* 2. unzip a list of pairs with one fold. *)
let unzip l = List.fold_right (fun (a, b) (xs, ys) -> (a :: xs, b :: ys)) l ([], [])

(* 3. apply a function n times. *)
let rec repeat n f x = if n = 0 then x else repeat (n - 1) f (f x)

(* 4. count_if and partition by hand. *)
let count_if p l = List.fold_left (fun n x -> if p x then n + 1 else n) 0 l

(* 5. group consecutive elements that satisfy an equivalence. *)
let group_by eq l =
  List.fold_right
    (fun x groups -> match groups with (y :: _ as g) :: rest when eq x y -> (x :: g) :: rest | _ -> [ x ] :: groups)
    l []

(* 6. compose a list of functions, applied left to right. *)
let pipeline fs x = List.fold_left (fun acc f -> f acc) x fs

let () =
  Printf.printf "%d %d\n" (product [ 1; 2; 3; 4 ]) (List.length (concat [ [ 1 ]; [ 2; 3 ]; [] ]));
  (let xs, ys = unzip [ (1, "a"); (2, "b") ] in Printf.printf "%d %s\n" (List.length xs) (String.concat "" ys));
  Printf.printf "%d\n" (repeat 5 (fun n -> n * 2) 1);
  Printf.printf "%d\n" (count_if (fun n -> n mod 3 = 0) (List.init 20 Fun.id));
  print_endline (String.concat " | " (List.map (fun g -> String.concat "," (List.map string_of_int g)) (group_by (fun a b -> a / 10 = b / 10) [ 1; 5; 12; 18; 19; 30 ])));
  Printf.printf "%d\n" (pipeline [ (fun x -> x + 1); (fun x -> x * 10); (fun x -> String.length (string_of_int x)) ] 4)

(* 1. a counter factory using a closure over a ref. *)
let make_counter () = let n = ref 0 in fun () -> incr n; !n

(* 2. reverse an array in place. *)
let reverse a =
  let n = Array.length a in
  for i = 0 to (n / 2) - 1 do
    let t = a.(i) in
    a.(i) <- a.(n - 1 - i);
    a.(n - 1 - i) <- t
  done

(* 3. bubble sort in place. *)
let bubble_sort a =
  let n = Array.length a in
  for pass = 0 to n - 2 do
    for i = 0 to n - 2 - pass do
      if a.(i) > a.(i + 1) then (let t = a.(i) in a.(i) <- a.(i + 1); a.(i + 1) <- t)
    done
  done

(* 4. a running average with mutable fields. *)
type stats = { mutable count : int; mutable total : float }

let add s x = s.count <- s.count + 1; s.total <- s.total +. x
let mean s = if s.count = 0 then 0.0 else s.total /. float_of_int s.count

(* 5. memoise a function with a Hashtbl, counting the real calls. *)
let calls = ref 0
let memo f = let t = Hashtbl.create 8 in fun x -> match Hashtbl.find_opt t x with Some v -> v | None -> let v = f x in Hashtbl.add t x v; v
let slow_square = memo (fun x -> incr calls; x * x)

let () =
