import json
from contextlib import ExitStack, contextmanager
data = 'ok'
events = []
@contextmanager
def owned(name):
    events.append('open:' + name)
    try:
        yield
    finally:
        events.append('close:' + name)
try:
    with ExitStack() as stack:
        stack.enter_context(owned('outer'))
        if data == 'acquire-error':
            raise ValueError('before inner')
        stack.enter_context(owned('inner'))
        if data == 'body-error':
            raise ValueError('inside')
except ValueError:
    events.append('handled')
result = events
print(json.dumps(result, sort_keys=True, allow_nan=False))

