from abc import ABC, abstractmethod
data = [['a', 1], ['b', 2]]
class Store(ABC):
    @abstractmethod
    def load(self, key): ...
    @abstractmethod
    def save(self, key, value): ...
class Partial(Store):
    def load(self, key):
        return None
class Memory(Store):
    def __init__(self):
        self.data = {}
    def load(self, key):
        return self.data.get(key)
    def save(self, key, value):
        self.data[key] = value
try:
    Partial()
    partial_ok = True
except TypeError:
    partial_ok = False
m = Memory()
for k, v in data:
    m.save(k, v)
result = [partial_ok, sorted(Partial.__abstractmethods__), m.load(data[0][0]) if data else None]
print(json.dumps(result, sort_keys=True, allow_nan=False))

