import functools
data = [1, 3]
def retry(times):
    def decorate(fn):
        @functools.wraps(fn)
        def wrapper(*args):
            for attempt in range(1, times + 1):
                try:
                    return [fn(*args), attempt]
                except ValueError:
                    if attempt == times:
                        raise
        return wrapper
    return decorate
failures, limit = data
calls = []
@retry(limit)
def flaky():
    calls.append(1)
    if len(calls) <= failures:
        raise ValueError('transient')
    return 'ok'
try:
    outcome = flaky()
except ValueError:
    outcome = 'gave-up'
result = [outcome, len(calls), flaky.__name__, flaky.__wrapped__.__name__]
print(json.dumps(result, sort_keys=True, allow_nan=False))

