import json
from typing import Protocol, runtime_checkable
data = ['file', 'liar', 'none']
@runtime_checkable
class Closer(Protocol):
    def close(self) -> None: ...
class File:
    def close(self):
        return None
class Liar:
    close = 3
class Nothing:
    pass
def safe_close(obj):
    if not isinstance(obj, Closer):
        return 'skipped'
    try:
        obj.close()
        return 'closed'
    except TypeError:
        return 'not-callable'
kinds = {'file': File, 'liar': Liar, 'none': Nothing}
result = [safe_close(kinds[k]()) for k in data]
print(json.dumps(result, sort_keys=True, allow_nan=False))

