    for future in as_completed(futures):
        source = futures[future]
        try:
            good[source] = future.result()
        except ValueError:
            bad.append(source)
result = [sorted(good.items()), sorted(bad)]
print(json.dumps(result, sort_keys=True, allow_nan=False))

