import numpy as np

def evaluate(values,window=3,horizon=1):
    values=np.asarray(values,dtype=float)
    if values.ndim!=1 or len(values)<window+horizon or window<1 or horizon<1 or not np.isfinite(values).all():raise ValueError("series")
    predictions=[];baseline=[];targets=[];origins=[]
    for origin in range(window,len(values)-horizon+1):
        history=values[:origin]
        predictions.append(float(history[-window:].mean()))
        baseline.append(float(history[-1]))
        targets.append(float(values[origin+horizon-1]));origins.append(origin)
    errors=np.abs(np.asarray(predictions)-targets)
    return {"origins":origins,"predictions":predictions,"baseline":baseline,"targets":targets,"mae":float(errors.mean())}

