class Window
{
    private readonly Clock clock;
    public int Ticks { get; private set; }
    public Window(Clock clock)
    {
        this.clock = clock;
        clock.Ticked += OnTick;
    }
    private void OnTick(object? sender, EventArgs e) => Ticks++;
    public void Close() => clock.Ticked -= OnTick;
}

