using System.Threading.Channels;

namespace Pipeline;

/// <summary>Feeds items through a bounded channel to a fixed number of workers and sums their results.</summary>
public static class BoundedPipeline
{
    public static async Task<long> RunAsync<T>(
        IEnumerable<T> items, int capacity, int workers,
        Func<T, CancellationToken, ValueTask<int>> work, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(items);
        ArgumentNullException.ThrowIfNull(work);
        ArgumentOutOfRangeException.ThrowIfLessThan(capacity, 1);
        ArgumentOutOfRangeException.ThrowIfLessThan(workers, 1);

        // Owned by this run: a failing worker cancels its siblings and the producer.
        using var failure = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
        var token = failure.Token;
        var channel = Channel.CreateBounded<T>(new BoundedChannelOptions(capacity) { SingleWriter = true });
        long total = 0;

        async Task ProduceAsync()
        {
            try
            {
                foreach (var item in items) await channel.Writer.WriteAsync(item, token);
                channel.Writer.Complete();
            }
            catch (Exception e)
            {
                channel.Writer.TryComplete(e);
                failure.Cancel();   // a failing source must also stop workers already inside work()
                throw;
            }
        }

        async Task ConsumeAsync()
        {
            try
            {
                await foreach (var item in channel.Reader.ReadAllAsync(token))
                    Interlocked.Add(ref total, await work(item, token));
            }
            catch
            {
                // Any exit by exception, including work()'s own cancellation, stops the whole run.
                failure.Cancel();
                throw;
            }
        }

        var tasks = new List<Task> { ProduceAsync() };
        for (int i = 0; i < workers; i++) tasks.Add(ConsumeAsync());
        Task all = Task.WhenAll(tasks);
        try
        {
            await all;
        }
        catch when (all.Exception?.InnerExceptions.FirstOrDefault(e => e is not OperationCanceledException) is { } cause)
        {
            // Every task has finished here, so no work outlives the call; report the real failure, not a sibling's cancellation.
            System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(cause).Throw();
        }
        return total;
    }
}

using Pipeline;

namespace Pipeline.Tests;

public class FailureTests
{
    [Fact]
    public async Task WorkerFailureCancelsSiblingsAndSurfacesTheCause()
    {
        int running = 0, started = 0;
        var run = BoundedPipeline.RunAsync(Enumerable.Range(0, 1000), capacity: 2, workers: 3, async (n, ct) =>
        {
            Interlocked.Increment(ref started);
            Interlocked.Increment(ref running);
            try
            {
                if (n == 1) throw new InvalidDataException("bad item 1");   // reached while siblings are blocked
                await Task.Delay(Timeout.Infinite, ct);   // only cancellation ends these workers
                return 1;
            }
            finally { Interlocked.Decrement(ref running); }
        }, TestContext.Current.CancellationToken);

        var error = await Assert.ThrowsAsync<InvalidDataException>(() => run);
        Assert.Equal("bad item 1", error.Message);
        Assert.Equal(0, Volatile.Read(ref running));      // no worker outlives RunAsync
        Assert.InRange(started, 2, 10);
    }

    [Fact]
    public async Task WorkerOwnCancellationStopsTheWholeRun()
    {
        var run = BoundedPipeline.RunAsync(Enumerable.Range(0, 1000), capacity: 1, workers: 2, async (n, ct) =>
        {
            if (n == 1) throw new OperationCanceledException("worker's own timeout");   // pipeline token still active
            await Task.Delay(Timeout.Infinite, ct);
            return 1;
        }, TestContext.Current.CancellationToken);

        await Assert.ThrowsAnyAsync<OperationCanceledException>(() => run);
    }

    [Fact]
    public async Task SourceFailureCancelsBusyWorkers()
    {
        static IEnumerable<int> Source()
        {
            yield return 0;
            yield return 1;
            throw new InvalidDataException("source broke");
        }
        var run = BoundedPipeline.RunAsync(Source(), capacity: 1, workers: 1, async (n, ct) =>
        {
            await Task.Delay(Timeout.Infinite, ct);   // only cancellation releases the worker
            return 1;
        }, TestContext.Current.CancellationToken);

        var error = await Assert.ThrowsAsync<InvalidDataException>(() => run);
        Assert.Equal("source broke", error.Message);
    }
}

