// Package cache holds values that expire.
package cache

import (
	"sync"
	"time"
)

// Cache stores values for a fixed time to live.
type Cache struct {
	mu   sync.Mutex
	ttl  time.Duration
	data map[string]entry
}

type entry struct {
	value   string
	expires time.Time
}

// New returns an empty cache.
func New(ttl time.Duration) *Cache {
	return &Cache{ttl: ttl, data: map[string]entry{}}
}

// Set stores value under key.
func (c *Cache) Set(key, value string) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.data[key] = entry{value, time.Now().Add(c.ttl)}
}

// Get returns the value if it has not expired.
func (c *Cache) Get(key string) (string, bool) {
	c.mu.Lock()
	defer c.mu.Unlock()
	e, ok := c.data[key]
	if !ok || !time.Now().Before(e.expires) {
		return "", false
	}
	return e.value, true
}

package cache

import (
	"testing"
	"testing/synctest"
	"time"
)

func TestExpiry(t *testing.T) {
	synctest.Test(t, func(t *testing.T) {
		c := New(time.Hour)
		c.Set("k", "v")
		time.Sleep(59 * time.Minute)
		if _, ok := c.Get("k"); !ok {
			t.Fatal("expired too early")
		}
		time.Sleep(time.Minute)
		if _, ok := c.Get("k"); ok {
			t.Fatal("still present after an hour")
		}
	})
}

