func (s *Stack[T]) Pop() (T, bool) {
	var zero T
	if len(s.items) == 0 {
		return zero, false
	}
	v := s.items[len(s.items)-1]
	s.items = s.items[:len(s.items)-1]
	return v, true
}

type Pair[K comparable, V any] struct {
	Key K
	Val V
}

type Lookup[V any] = map[string]V

func main() {
	var s Stack[string]
	s.Push("a")
	s.Push("b")
	v, ok := s.Pop()
	fmt.Println(v, ok)
	var empty Stack[int]
	fmt.Println(empty.Pop())
	fmt.Printf("%+v\n", Pair[string, int]{"go", 1})
	l := Lookup[int]{"x": 1}
	fmt.Println(l["x"])
}

