import (
	"fmt"
	"sync"
)

type Queue struct {
	mu    sync.Mutex
	ready *sync.Cond
	items []int
}

func NewQueue() *Queue {
	q := &Queue{}
	q.ready = sync.NewCond(&q.mu)
	return q
}

func (q *Queue) Put(v int) {
	q.mu.Lock()
	q.items = append(q.items, v)
	q.mu.Unlock()
	q.ready.Signal()
}

func (q *Queue) Take() int {
	q.mu.Lock()
	defer q.mu.Unlock()
	for len(q.items) == 0 {
		q.ready.Wait()
	}
	v := q.items[0]
	q.items = q.items[1:]
	return v
}

func main() {
	q := NewQueue()
	var wg sync.WaitGroup
	sums := make([]int, 2)
	for i := range 2 {
		wg.Go(func() { sums[i] = q.Take() + q.Take() })
	}
	for v := range 4 {
		q.Put(v + 1)
	}
	wg.Wait()
	fmt.Println(sums[0] + sums[1])
}

