// Package wc counts lines, words and bytes like the Unix wc tool.
package wc

import (
	"bufio"
	"io"
	"unicode"
)

// Counts holds the totals for one input.
type Counts struct {
	Lines, Words, Bytes int
}

// Count reads r to the end and returns its totals.
func Count(r io.Reader) (Counts, error) {
	var c Counts
	br := bufio.NewReader(r)
	inWord := false
	for {
		ch, size, err := br.ReadRune()
		if err == io.EOF {
			return c, nil
		}
		if err != nil {
			return c, err
		}
		c.Bytes += size
		if ch == '\n' {
			c.Lines++
		}
		if unicode.IsSpace(ch) {
			inWord = false
		} else if !inWord {
			inWord = true
			c.Words++
		}
	}
}

package wc

import (
	"errors"
	"strings"
	"testing"
	"testing/iotest"
)

func TestCount(t *testing.T) {
	cases := []struct {
		name, in string
		want     Counts
	}{
		{"empty", "", Counts{}},
		{"one line", "hello go\n", Counts{1, 2, 9}},
		{"no newline", "a b c", Counts{0, 3, 5}},
		{"unicode", "héllo wörld\n", Counts{1, 2, 14}},
		{"spaces", "  a \t\n\n b ", Counts{2, 2, 10}},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			got, err := Count(strings.NewReader(c.in))
			if err != nil || got != c.want {
				t.Fatalf("Count(%q) = %+v, %v; want %+v", c.in, got, err, c.want)
			}
		})
	}
}

func TestCountReadError(t *testing.T) {
	boom := errors.New("boom")
	if _, err := Count(iotest.ErrReader(boom)); !errors.Is(err, boom) {
		t.Fatalf("err = %v", err)
	}
}

// Command wc prints line, word and byte counts for files or standard input.
package main

import (
	"flag"
