	n, err := io.Copy(io.Discard, io.LimitReader(resp.Body, 1<<20))
	if err != nil {
		return Result{URL: url, Status: resp.StatusCode, Err: fmt.Errorf("read body: %w", err)}
	}
	return Result{URL: url, Status: resp.StatusCode, Bytes: int(n)}
}

