// Package limit is a token-bucket rate limiter.
package limit

import (
	"context"
	"sync"
	"time"
)

// Bucket allows rate events per second with bursts of up to burst events.
type Bucket struct {
	mu     sync.Mutex
	rate   float64
	burst  float64
	tokens float64
	last   time.Time
}

// New returns a full bucket.
func New(rate float64, burst int) *Bucket {
	return &Bucket{rate: rate, burst: float64(burst), tokens: float64(burst), last: time.Now()}
}

func (b *Bucket) refill(now time.Time) {
	b.tokens = min(b.burst, b.tokens+now.Sub(b.last).Seconds()*b.rate)
	b.last = now
}

// Allow reports whether an event may happen now, consuming a token if so.
func (b *Bucket) Allow() bool {
	b.mu.Lock()
	defer b.mu.Unlock()
	b.refill(time.Now())
	if b.tokens >= 1 {
		b.tokens--
		return true
	}
	return false
}

// Wait blocks until a token is available or ctx is done.
func (b *Bucket) Wait(ctx context.Context) error {
	for {
		b.mu.Lock()
		b.refill(time.Now())
		if b.tokens >= 1 {
			b.tokens--
			b.mu.Unlock()
			return nil
		}
		need := time.Duration((1 - b.tokens) / b.rate * float64(time.Second))
		b.mu.Unlock()
		t := time.NewTimer(need)
		select {
		case <-t.C:
		case <-ctx.Done():
			t.Stop()
			return ctx.Err()
		}
	}
}

package limit

import (
	"context"
	"errors"
	"sync"
	"testing"
	"testing/synctest"
	"time"
)

func TestBurstThenRefill(t *testing.T) {
	synctest.Test(t, func(t *testing.T) {
		b := New(2, 3)
		for i := range 3 {
			if !b.Allow() {
				t.Fatalf("burst event %d refused", i)
			}
		}
		if b.Allow() {
			t.Fatal("fourth immediate event allowed")
		}
		time.Sleep(500 * time.Millisecond)
		if !b.Allow() || b.Allow() {
			t.Fatal("half a second at 2/s should refill exactly one token")
		}
		time.Sleep(10 * time.Second)
		allowed := 0
		for range 10 {
			if b.Allow() {
				allowed++
			}
		}
		if allowed != 3 {
			t.Fatalf("after a long idle period %d events were allowed; the burst cap is 3", allowed)
		}
	})
}

func TestWaitPacesWorkers(t *testing.T) {
	synctest.Test(t, func(t *testing.T) {
		b := New(10, 1)
		start := time.Now()
		var wg sync.WaitGroup
		for range 5 {
			wg.Go(func() {
				if err := b.Wait(context.Background()); err != nil {
					t.Error(err)
				}
			})
		}
		wg.Wait()
		// shortcut: 1ms tolerance absorbs float refill rounding; fake time is otherwise exact
		if got := time.Since(start); got < 400*time.Millisecond || got > 401*time.Millisecond {
			t.Fatalf("five events at 10/s with burst 1 took %v, want 400ms", got)
		}
	})
}

func TestWaitCancelled(t *testing.T) {
	synctest.Test(t, func(t *testing.T) {
		b := New(1, 1)
		b.Allow()
		ctx, cancel := context.WithTimeout(context.Background(), 100*time.Millisecond)
		defer cancel()
		if err := b.Wait(ctx); !errors.Is(err, context.DeadlineExceeded) {
			t.Fatalf("err = %v", err)
		}
	})
}

