A single-producer single-consumer ring needs only two atomics
Why may push load tail_ with memory_order_relaxed?

Program:
#include <iostream>
#include <array>
#include <atomic>
#include <cstddef>
#include <thread>
template <typename T, std::size_t N>
class SpscRing {
    std::array<T, N> slots_{};
    std::atomic<std::size_t> head_{0};
    std::atomic<std::size_t> tail_{0};
public:
    bool push(const T& value) {
        const auto tail = tail_.load(std::memory_order_relaxed);
        const auto next = (tail + 1) % N;
        if (next == head_.load(std::memory_order_acquire)) return false;
        slots_[tail] = value;
        tail_.store(next, std::memory_order_release);
        return true;
    }
    bool pop(T& out) {
        const auto head = head_.load(std::memory_order_relaxed);
        if (head == tail_.load(std::memory_order_acquire)) return false;
        out = slots_[head];
        head_.store((head + 1) % N, std::memory_order_release);
        return true;
    }
};

int main() {
    SpscRing<int, 8> ring;
    long sum = 0;
    std::thread consumer([&] {
        int value = 0;
        for (int got = 0; got < 100;)
            if (ring.pop(value)) { sum += value; ++got; }
    });
    for (int i = 1; i <= 100; ++i)
        while (!ring.push(i)) {}
    consumer.join();
    std::cout << sum << "\n";
}

