#include <iostream>
#include <vector>
constexpr int sumSquares(int n) {
    std::vector<int> squares;
    for (int i = 1; i <= n; ++i) squares.push_back(i * i);
    int total = 0;
    for (int x : squares) total += x;
    return total;
}

int main() {
    constexpr int result = sumSquares(4);
    static_assert(result == 30);
    std::cout << result << "\n";
}

