#include <iostream>
#include <cstdlib>
#include <new>
#include <vector>
static std::size_t allocations = 0;
void* operator new(std::size_t size) {
    ++allocations;
    if (void* p = std::malloc(size ? size : 1)) return p;
    throw std::bad_alloc{};
}
void operator delete(void* p) noexcept { std::free(p); }
void operator delete(void* p, std::size_t) noexcept { std::free(p); }

int main() {
    allocations = 0;
    std::vector<int> grown;
    for (int i = 0; i < 100; ++i) grown.push_back(i);
    const std::size_t without_reserve = allocations;
    allocations = 0;
    std::vector<int> reserved;
    reserved.reserve(100);
    for (int i = 0; i < 100; ++i) reserved.push_back(i);
    const std::size_t with_reserve = allocations;
    std::cout << without_reserve << " " << with_reserve << "\n";
}

