}

#include <iostream>
#include <condition_variable>
#include <mutex>
#include <thread>
int main() {
    std::mutex m;
    std::condition_variable cv;
    bool ready = false;
    {
        std::lock_guard<std::mutex> lock(m);
        ready = true;
    }
    cv.notify_one();
    std::thread waiter([&] {
        std::unique_lock<std::mutex> lock(m);
        cv.wait(lock, [&] { return ready; });
        std::cout << "proceeded\n";
    });
    waiter.join();
}

#include <iostream>
#include <chrono>
#include <condition_variable>
#include <mutex>
#include <thread>
int main() {
    std::mutex m;
    std::condition_variable cv;
    bool ready = false;
    std::thread waiter([&] {
        std::unique_lock<std::mutex> lock(m);
        while (!ready) cv.wait_for(lock, std::chrono::milliseconds(1));
    });
    ready = true;
    cv.notify_one();
    waiter.join();
    std::cout << "done\n";
}

