struct Rect { int w, h; };
int main() {
    std::vector<std::variant<Square, Rect>> shapes{Square{2}, Rect{2, 4}};
    int total = 0;
    for (const auto& s : shapes) total += std::visit(overloaded{[](Square q) { return q.side * q.side; }, [](Rect r) { return r.w * r.h; }}, s);
    std::cout << total << "\n";
}

#include <iostream>
#include <variant>
template <class... F> struct overloaded : F... { using F::operator()...; };
template <class... F> overloaded(F...) -> overloaded<F...>;
struct Square { int side; };
struct Rect { int w, h; };
int main() {
    std::variant<Square, Rect> s{Rect{2, 4}};
    std::cout << std::visit(overloaded{[](Square q) { return q.side; }}, s) << "\n";
}
